    var taskLinkSheetActive: Bool { !taskLinkSheet.isEmpty }
    var taskLinkSheetProtected: Bool {
        taskLinkSheetActive && taskRecoverySnapshot != nil
            && taskRecoveryCheckpointError == nil
            && taskRecoveryCheckpointedGeneration == taskRecoveryGeneration
    }

    var taskReferenceEnabled: Bool {
        taskPresented && !taskEditor.isEmpty && !taskView.isEmpty && !appLock.concealed
            && !busy && !retryNeeded && !taskReferenceOpening && !taskAttachmentOpening
            && !taskRecoverySaving && !taskSavePending && !taskPersonCreateOwed && !taskPersonCreateNeedsReview
            && !taskLinkSubmitting && taskLinkSheet.isEmpty && taskDestinationKind.isEmpty
            && taskChecklistWriteKind == nil && !taskChecklistReadPending && !taskScheduleUpdating
    }

    func openTaskViewReference(sourceID: String, revision: String, position: CoreObject) async {
        guard taskReferenceEnabled, viewedTaskID == sourceID, taskView.text("revision") == revision else { return }
        let section = position["checklistIndex"] != nil ? "checklist"
            : ["project", "contexts", "tags"].contains(position.text("field")) ? position.text("field") : "description"
        taskReferenceSection = section
        guard !taskDirty else {
            taskReferenceError = "Save or discard this task's changes before opening an internal link."
            return
        }
        let id = viewedTaskID, session = taskRecoverySession, caller = selectedSurface
        let view: CoreObject = ["id": id, "draft": taskDraft, "checklist": taskChecklist, "attachments": taskAttachments]
        guard let identity = try? json(view) else { return }
        taskReferenceOpening = true
        taskReferenceError = nil
        busy = true
        defer { taskReferenceOpening = false; finishOperation() }
        func sourceCurrent() -> Bool {
            taskPresented && viewedTaskID == id && taskRecoverySession == session && selectedSurface == caller
                && taskView.text("revision") == revision && !appLock.concealed && !retryNeeded && !taskDirty
                && !taskSavePending && !taskPersonCreateOwed && !taskPersonCreateNeedsReview
                && !taskLinkSubmitting && taskLinkSheet.isEmpty && taskDestinationKind.isEmpty
                && taskChecklistWriteKind == nil && !taskChecklistReadPending && !taskScheduleUpdating
                && (try? json(["id": viewedTaskID, "draft": taskDraft, "checklist": taskChecklist,
                              "attachments": taskAttachments])) == identity
        }
        do {
            var input = position
            input["view"] = view
            input["revision"] = revision
            let target = try await query("taskViewReferenceTarget", [try json(input)])
            guard sourceCurrent(), target.count == 2, ["task", "project", "context", "tag"].contains(target.text("kind")),
                  !target.text("id").isEmpty else { throw CocoaError(.coderReadCorrupt) }
            if target.text("kind") == "task" && target.text("id") == id { return }
            // Reuse Close's exact clean-draft cleanup before replacing the editor.
            busy = false
            await discardCleanTaskSnapshotAndClose(refreshCaller: false)
            guard !taskPresented, taskRecoverySession == session, selectedSurface == caller,
                  !appLock.concealed, !retryNeeded, !busy else { return }
            if target.text("kind") == "task" {
                prepareTaskPresentation(target.text("id"))
                await readTaskView()
                if taskError == nil && taskPresented && viewedTaskID == target.text("id") {
                    NSLog("Native iOS Task preview reference opened releaseCheck=v1.3.4/ios-task-preview-links destination=task source=\(section)")
                }
            } else if target.text("kind") == "project" {
                await presentProject(["id": target.text("id")], caller: caller == .project ? projectCaller : caller)
                if projectCurrent && projectHeader.text("id") == target.text("id") {
                    NSLog("Native iOS Task preview reference opened releaseCheck=v1.3.4/ios-task-preview-links destination=project source=\(section)")
                }
            } else {
                contextsIntents.append(["kind": "focus", "value": target.text("id")])
                contextsLoadedDepth = pageSize
                await openContexts()
                if selectedSurface == .contexts && contextsCurrent {
                    NSLog("Native iOS Task preview reference opened releaseCheck=v1.3.4/ios-task-preview-links destination=contexts source=\(section)")
                }
            }
        } catch {
            if taskPresented && viewedTaskID == id && taskRecoverySession == session {
                taskReferenceError = "This link changed or is unavailable. Refresh Preview and try again."
            }
        }
    }

    func retryTaskViewReference() async {
        guard taskReferenceEnabled, !taskDirty else { return }
        taskReferenceError = nil
        await readTaskView()
    }

    private func taskAttachmentOwner() -> CoreObject {
        ["kind": "task", "taskId": viewedTaskID, "attachments": taskAttachments]
    }

    func shareTask() async {
        guard taskPresented, !taskEditor.isEmpty, !taskEditor.flag("readOnly"), !appLock.concealed,
              !busy, !retryNeeded, !taskAttachmentOpening, !taskReferenceOpening,
              !taskRecoverySaving, !taskSavePending, !taskPersonCreateOwed, !taskPersonCreateNeedsReview,
              !taskLinkSubmitting, taskLinkSheet.isEmpty, taskDestinationKind.isEmpty,
              taskChecklistWriteKind == nil, !taskChecklistReadPending, !taskScheduleUpdating,
              taskChecklistLoaded, taskSharePayload == nil else { return }
        let id = viewedTaskID, session = taskRecoverySession, checklistSession = taskChecklistSession
        let current = { [self] in
            taskPresented && viewedTaskID == id && taskRecoverySession == session
                && !appLock.concealed && !retryNeeded && !taskSavePending && !taskRecoverySaving
        }
        busy = true
        taskShareError = nil
        defer { finishOperation() }
        do {
            try await resolveTaskEditorInputs()
            try await flushTaskChecklistInputs(id: id, session: checklistSession)
            guard current() else { return }
            let request = try json(["id": id, "taskRevision": taskView.text("taskRevision"),
                                    "draft": taskDraft, "checklist": taskChecklist])
            let generation = taskRecoveryGeneration
            if taskRecoverySnapshot != nil || taskDirty {
                await flushTaskDraftCheckpoint()
                guard current() else { return }
                guard taskRecoveryProtected else { throw CocoaError(.fileWriteUnknown) }
            }
            let result = try await query("taskShare", [request])
            guard current(), taskRecoveryGeneration == generation,
                  request == (try json(["id": id, "taskRevision": taskView.text("taskRevision"),
                                        "draft": taskDraft, "checklist": taskChecklist])) else { return }
            guard Set(result.keys) == Set(["title", "message"]),
                  result["title"] is String || result["title"] is NSNull,
                  let message = result["message"] as? String, !message.isEmpty else {
                throw CocoaError(.coderReadCorrupt)
            }
            taskSharePayload = TaskSharePayload(title: result["title"] as? String, message: message)
        } catch {
            if current() { taskShareError = label("share.unavailable") }
        }
    }

    func dismissTaskShare() { taskSharePayload = nil }
    func dismissTaskShareError() { taskShareError = nil }

    func openTaskAttachment(_ attachmentID: String) async {
        guard ready, taskPresented, !taskEditor.isEmpty, !appLock.concealed, let currentHost = host,
              !busy, !retryNeeded, !taskAttachmentOpening, !taskRecoverySaving, !taskSavePending,
              !taskAttachmentWorking, taskFileImporterID == nil, !taskFileImporterPresented,
              taskSharePayload == nil, taskFileOpenPresentation == nil, !taskReferenceOpening,
              !taskPersonCreateOwed, !taskPersonCreateNeedsReview, !taskLinkSubmitting,
              taskLinkSheet.isEmpty, taskDestinationKind.isEmpty,
              taskChecklistWriteKind == nil, !taskChecklistReadPending, !taskScheduleUpdating,
              let attachment = taskAttachments.first(where: {
                  $0.text("id") == attachmentID && ["link", "file"].contains($0.text("kind")) && $0["deletedAt"] == nil
              }) else { return }
        let id = viewedTaskID, session = taskRecoverySession
        let kind = attachment.text("kind")
        guard let raw = try? json(taskAttachments), let editorRaw = try? json(taskRecoveryPayload()) else { return }
        let claim = UUID()
        observeDiagnosticsConcealment()
        taskAttachmentOpenClaim = claim
        taskAttachmentOpening = true
        taskAttachmentOpeningFile = kind == "file"
        taskAttachmentOpenError = nil
        defer {
            if taskAttachmentOpenClaim == claim && taskFileOpenPresentation?.id != claim {
                taskAttachmentOpening = false
                taskAttachmentOpeningFile = false
            }
        }
        let current = { [self] in
            host === currentHost && ready && !Task.isCancelled
                && taskAttachmentOpenClaim == claim && taskAttachmentOpening && taskPresented && viewedTaskID == id
                && taskRecoverySession == session && !appLock.concealed && !busy && !retryNeeded
                && !taskAttachmentWorking && taskFileImporterID == nil && !taskFileImporterPresented
                && taskSharePayload == nil && !taskReferenceOpening
                && !taskRecoverySaving && !taskSavePending && !taskPersonCreateOwed
                && !taskPersonCreateNeedsReview && !taskLinkSubmitting && taskLinkSheet.isEmpty
                && taskDestinationKind.isEmpty && taskChecklistWriteKind == nil
                && !taskChecklistReadPending && !taskScheduleUpdating
                && (try? json(taskAttachments)) == raw
                && (try? json(taskRecoveryPayload())) == editorRaw
                && taskAttachments.contains(where: { $0.text("id") == attachmentID && $0.text("kind") == kind && $0["deletedAt"] == nil })
        }
        if taskRecoverySnapshot != nil || (!taskEditor.flag("readOnly") && taskDirty) {
            await flushTaskDraftCheckpoint()
            guard current() else { return }
            guard taskRecoveryProtected else {
                taskAttachmentOpenError = "The task draft could not be saved for recovery."
                return
            }
        }
        do {
            let request = try json(["owner": taskAttachmentOwner(), "attachmentId": attachmentID])
            let generation = taskRecoveryGeneration
            let result: CoreObject
            if kind == "file" {
                let encoded = try await currentHost.prepareTaskFileOpen(requestJSON: request)
                result = try decode(encoded)
            } else {
                result = try await query("taskAttachmentOpen", [request])
            }
            guard current(), taskRecoveryGeneration == generation else { return }
            if kind == "file" {
                guard result["update"] is NSNull else { throw CocoaError(.coderReadCorrupt) }
                guard result.text("status") == "available" else {
                    taskAttachmentOpenError = result["message"] as? String ?? "This file could not be opened. Try again."
                    return
                }
                let plan = result.object("open")
                guard result["message"] is NSNull,
                      let planKind = AttachmentFileOpenPresentation.Kind(rawValue: plan.text("kind")) else {
                    throw CocoaError(.coderReadCorrupt)
                }
                let uri = planKind == .file ? plan.text("uri") : plan.object("attachment").text("uri")
                if let original = result["relocatedFrom"] {
                    guard Set(result.keys) == Set(["status", "message", "update", "open", "relocatedFrom"]),
                          let originalURI = original as? String,
                          Data(originalURI.utf8) == Data(attachment.text("uri").utf8),
                          Data(uri.utf8) != Data(originalURI.utf8) else { throw CocoaError(.coderReadCorrupt) }
                } else {
                    guard uri.utf8.elementsEqual(attachment.text("uri").utf8) else { throw CocoaError(.coderReadCorrupt) }
                }
                guard let url = URL(string: uri), url.isFileURL else { throw CocoaError(.coderReadCorrupt) }
                guard current() else { return }
                taskFileOpenPresentation = AttachmentFileOpenPresentation(id: claim, url: url, kind: planKind)
                if planKind == .audio {
                    startTaskAudio(presentationID: claim, host: currentHost, taskID: id, session: session,
                        generation: generation, title: attachment.text("title"), url: url)
                }
                return
            }
            guard result.text("status") == "available", result["message"] is NSNull,
                  result["update"] is NSNull else { throw CocoaError(.coderReadCorrupt) }
            let plan = result.object("open")
            if plan.text("kind") == "alert", let message = plan["message"] as? String {
                taskAttachmentOpenError = message
                return
            }
            guard plan.text("kind") == "link", let uri = plan["uri"] as? String,
                  let failedMessage = plan["failedMessage"] as? String else { throw CocoaError(.coderReadCorrupt) }
            if uri.lowercased().hasPrefix("upnote://") {
                guard current() else { return }
                let opened = await NativeUpNoteLink.open(uri, surface: "attachment")
                await recordUpNoteHandoff(opened ? "opened" : "failed", surface: "attachment")
                guard current() else { return }
                if !opened { NativeUpNoteLink.showFailure(uri, labels: strings) }
                return
            }
            guard let url = URL(string: uri) else { taskAttachmentOpenError = failedMessage; return }
            guard current() else { return }
            let opened = await withCheckedContinuation { continuation in
                UIApplication.shared.open(url, options: [:]) { continuation.resume(returning: $0) }
            }
            guard current() else { return }
            if opened { NSLog("Native iOS Task URL opened releaseCheck=v1.3.4/ios-task-link-open outcome=opened") }
            else { taskAttachmentOpenError = failedMessage }
        } catch {
            if current() {
                taskAttachmentOpenError = kind == "file" ? "This file could not be opened. Try again." : "The link could not be opened. Try again."
            }
        }
    }

    func dismissTaskFileOpen(presentationID: UUID) {
        guard taskFileOpenPresentation?.id == presentationID, taskAttachmentOpenClaim == presentationID else { return }
        invalidateTaskAttachmentOpen()
    }

    private func invalidateTaskAttachmentOpen() {
        cancelTaskAttachmentDownload()
        // Stop the original owner synchronously before publishing its removal.
        taskAudioPlayer?.retire()
        taskAudioPlayer = nil
        taskAudioPlayback = nil
        taskAttachmentOpenClaim = UUID()
        taskFileOpenPresentation = nil
        taskAttachmentOpening = false
        taskAttachmentOpeningFile = false
    }

    func dismissTaskAttachmentOpenError() { taskAttachmentOpenError = nil }

    func stopTaskAudioForBackground() {
        // An awaiting file plan has not revealed its kind yet. Fence its claim,
        // but leave already-adopted image and document presentations intact.
        if taskAudioPlayer != nil || taskFileOpenPresentation?.kind == .audio
            || (taskAttachmentOpening && taskAttachmentOpeningFile && taskFileOpenPresentation == nil) {
            invalidateTaskAttachmentOpen()
        }
    }

    func toggleTaskAudioPlayback(presentationID: UUID) {
        guard let audio = taskAudioPlayer, audio.presentationID == presentationID,
              taskAudioOwnerIsCurrent(audio), audio.state.canToggle else { return }
        do {
            if audio.state.playing { audio.pause() }
            else { try audio.play() }
            taskAudioPlayback = audio.state
        } catch { failTaskAudio(audio) }
    }

    private func taskAudioOwnerIsCurrent(_ audio: TaskAttachmentAudioPlayer) -> Bool {
        taskAudioPlayer === audio && taskAttachmentOpenClaim == audio.presentationID
            && taskFileOpenPresentation?.id == audio.presentationID && taskFileOpenPresentation?.kind == .audio
            && host === audio.host && ready && taskPresented && viewedTaskID == audio.taskID
            && taskRecoverySession == audio.session && taskRecoveryGeneration == audio.generation
            && !appLock.concealed && UIApplication.shared.applicationState == .active
    }

    private func startTaskAudio(presentationID: UUID, host: CoreHost, taskID: String, session: String,
                                generation: Int, title: String, url: URL) {
        do {
            let audio = try TaskAttachmentAudioPlayer(presentationID: presentationID, host: host,
                taskID: taskID, session: session, generation: generation,
                title: title.isEmpty ? label("quickAdd.audioNoteTitle") : title, url: url)
            audio.onEvent = { [weak self] player, event in self?.receiveTaskAudioEvent(player, event: event) }
            taskAudioPlayer = audio
            guard taskAudioOwnerIsCurrent(audio) else { invalidateTaskAttachmentOpen(); return }
            try audio.play()
            taskAudioPlayback = audio.state
            // The original admitted host records actual autoplay, best-effort.
            // No new await splits claimed playback from its UI publication.
            Task { await host.recordTaskAudioPlaybackStarted() }
        } catch {
            guard taskAttachmentOpenClaim == presentationID, taskFileOpenPresentation?.id == presentationID else { return }
            invalidateTaskAttachmentOpen()
            taskAttachmentOpenError = label("settings.feedback.actionFailed")
        }
    }

    private func receiveTaskAudioEvent(_ audio: TaskAttachmentAudioPlayer, event: TaskAttachmentAudioPlayer.Event) {
        guard taskAudioOwnerIsCurrent(audio) else {
            if taskAudioPlayer === audio { invalidateTaskAttachmentOpen() }
            return
        }
        switch event {
        case .tick: break
        case .finished(let success):
            guard success else { failTaskAudio(audio); return }
            audio.finish()
        case .failed: failTaskAudio(audio); return
        case .interruptionBegan: audio.pause(interruption: true)
        case .interruptionEnded: audio.endInterruption()
        case .routeLost: audio.pause()
        }
        taskAudioPlayback = audio.state
    }

    private func failTaskAudio(_ audio: TaskAttachmentAudioPlayer) {
        guard taskAudioOwnerIsCurrent(audio) else { return }
        invalidateTaskAttachmentOpen()
        taskAttachmentOpenError = label("settings.feedback.actionFailed")
    }

    private func refreshTaskAttachmentRows(ownedGuard: (() -> Bool)? = nil) async throws {
        let id = viewedTaskID, session = taskRecoverySession
        let currentHost = host
        let current = try json(taskAttachments)
        let result = try await query("taskAttachmentList", [try json(["owner": taskAttachmentOwner()])])
        guard ownedGuard?() != false else { throw CancellationError() }
        guard host === currentHost, taskPresented, viewedTaskID == id, taskRecoverySession == session,
              try json(taskAttachments) == current,
              let rows = result["rows"] as? [CoreObject] else { return }
        taskAttachmentRows = rows
    }

    func openTaskLinkSheet(_ attachmentID: String? = nil) {
        guard taskPresented, !taskEditor.flag("readOnly"), !busy, !retryNeeded, !taskRecoverySaving,
              !taskAttachmentOpening, taskAttachmentListChangesAllowed,
              taskLinkSheet.isEmpty else { return }
        var sheet: CoreObject = ["id": UUID().uuidString.lowercased(), "text": ""]
        if let attachmentID {
            guard let row = taskAttachmentRows.first(where: { $0.text("id") == attachmentID && $0.text("kind") == "link" }),
                  let editText = row["editText"] as? String,
                  let attachment = taskAttachments.first(where: { $0.text("id") == attachmentID }) else { return }
            sheet["text"] = editText
            sheet["editing"] = ["attachmentId": attachmentID, "title": attachment.text("title"), "uri": attachment.text("uri")]
        }
        taskLinkSheetError = nil
        taskLinkSheet = sheet
        taskRecoveryOwn(attachments: true)
    }

    func setTaskLinkText(_ text: String) {
        guard taskLinkSheetActive, !taskRecoverySaving, taskAttachmentCheckpointFailed == nil else { return }
        taskLinkSheet["text"] = text
        taskLinkSheetError = nil
        taskRecoveryOwn(attachments: true)
    }

    func cancelTaskLinkSheet() {
        guard taskLinkSheetActive, !taskRecoverySaving else { return }
        taskLinkSheet = [:]
        taskLinkSheetError = nil
        taskRecoveryOwn(attachments: true)
    }

    func submitTaskLinkSheet() async {
        guard taskPresented, taskLinkSheetActive, !taskLinkSubmitting, !taskEditor.flag("readOnly"),
              !taskAttachmentOpening, taskAttachmentListChangesAllowed,
              !busy, !retryNeeded, !taskRecoverySaving else { return }
        taskLinkSubmitting = true
        defer { taskLinkSubmitting = false }
        let id = viewedTaskID, session = taskRecoverySession, sheet = taskLinkSheet
        let current = (try? json(taskAttachments)) ?? ""
        guard !current.isEmpty else { return }
        var request: CoreObject = ["owner": taskAttachmentOwner(),
                                   "requestId": UUID().uuidString.lowercased(), "text": sheet.text("text")]
        if let editing = sheet["editing"] as? CoreObject { request["editing"] = editing }
        taskLinkSheetError = nil
        do {
            let result = try await query("taskAttachmentLinks", [try json(request)])
            guard taskPresented, viewedTaskID == id, taskRecoverySession == session,
                  taskLinkSheet.text("id") == sheet.text("id"),
                  taskLinkSheet.text("text") == sheet.text("text"),
                  try json(taskAttachments) == current else { return }
            if result.text("kind") == "saved", let attachments = result["attachments"] as? [CoreObject] {
                taskLinkSheet = [:]
                taskLinkSheetError = nil
                taskAttachments = attachments
                taskRecoveryOwn(attachments: true)
                try await refreshTaskAttachmentRows()
            } else if result.text("kind") == "refused" {
                taskLinkSheetError = result.text("message")
            }
        } catch {
            if taskPresented, viewedTaskID == id, taskRecoverySession == session,
               taskLinkSheet.text("id") == sheet.text("id") {
                taskLinkSheetError = "The link could not be added. Try again."
            }
        }
    }

    func removeTaskLink(_ attachmentID: String) async {
        guard taskPresented, !taskEditor.flag("readOnly"), !busy, !retryNeeded, !taskRecoverySaving,
              !taskAttachmentOpening, taskAttachmentListChangesAllowed,
              taskLinkSheet.isEmpty,
              taskAttachmentRows.contains(where: { $0.text("id") == attachmentID && $0.text("kind") == "link" }) else { return }
        let id = viewedTaskID, session = taskRecoverySession
        let current = (try? json(taskAttachments)) ?? ""
        guard !current.isEmpty else { return }
        do {
            let result = try await query("taskAttachmentRemove", [try json([
                "owner": taskAttachmentOwner(), "requestId": UUID().uuidString.lowercased(),
                "attachmentId": attachmentID])])
            guard taskPresented, viewedTaskID == id, taskRecoverySession == session,
                  try json(taskAttachments) == current else { return }
            if result.text("kind") == "saved", let attachments = result["attachments"] as? [CoreObject] {
                taskAttachments = attachments
                taskRecoveryOwn(attachments: true)
                try await refreshTaskAttachmentRows()
            } else if result.text("kind") == "refused" { taskError = result.text("message") }
        } catch {
            if taskPresented, viewedTaskID == id, taskRecoverySession == session {
                taskError = "The link could not be removed. Try again."
            }
        }
    }
    func setTaskInitialTab(_ tab: String) {
        guard ["task", "view"].contains(tab) else { return }
        taskOpeningIntent = nil
        taskInitialTab = tab
        if taskRecoverySnapshot != nil { checkpointTaskDraft() }
    }
    var taskDirty: Bool {
        !taskEditor.isEmpty && ((taskSaveFields + taskRecurrenceFields).contains { !taskDraftValuesEqual(taskDraft[$0], taskOriginalDraft[$0]) }
            || !taskDraftValuesEqual(taskDraft["relativeStartOffset"], taskOriginalDraft["relativeStartOffset"])
            || ["status", "focusedToday", "completedAt"].contains { !taskDraftValuesEqual(taskDraft[$0], taskOriginalDraft[$0]) }
            || !taskDraftValuesEqual(taskChecklist, taskOriginalChecklist)
            || !taskDraftValuesEqual(taskAttachments, taskOriginalAttachments)
            || !taskLinkSheet.isEmpty
            || taskChecklistInputs.contains { entry in
                entry.key < taskChecklist.count && entry.value != taskChecklist[entry.key].text("title")
            }
            || !taskChecklistAppendInput.isEmpty
            || taskSchedulePending || taskEstimatePending || taskTimeSpentPending
            || !taskDraftValuesEqual(taskDraft["timeSpentMinutes"], taskOriginalDraft["timeSpentMinutes"])
            || taskTokenFields.contains { taskTokenResolvedInputs[$0] != taskTokenInputs[$0] })
    }
    var taskDestinationActionsEnabled: Bool {
        taskPresented && !taskDestinationKind.isEmpty && taskDestinationCurrent && !busy && !retryNeeded
            && !taskEditor.flag("readOnly") && !taskDestination.flag("readOnly")
            && taskDestination.text("id") == viewedTaskID
            && taskDestination.text("query") == taskDestinationQuery
            && (try? json(taskDraft)) == taskDestinationDraftIdentity
    }
    private var taskDraft: CoreObject {
        var draft = taskEditor.object("draft")
        draft["title"] = taskTitleDraft
        draft["description"] = taskNoteDraft
        draft["location"] = taskLocationDraft
        for field in taskTokenFields {
            if let canonical = taskTokenCanonical[field] { draft[field] = canonical }
        }
        return draft
    }
    private func taskEditRequest(_ edit: CoreObject? = nil) -> CoreObject {
        var request: CoreObject = ["id": viewedTaskID, "draft": taskDraft]
        if taskChecklistLoaded { request["checklist"] = taskChecklist }
        if let edit { request["edit"] = edit }
        return request
    }
    private var taskEstimatePending: Bool {
        taskEditor.object("fields").object("timeEstimate").flag("customSelected")
            && taskEstimateInput != taskEstimateResolvedInput
    }
    private var taskTimeSpentPending: Bool { taskTimeSpentInput != taskTimeSpentResolvedInput }

