        do {
            #if DEBUG && (targetEnvironment(simulator) || NATIVE_DEVICE_TEST)
            if command == "testSyncConnection" && settingsSyncTestThrowOnce {
                settingsSyncTestThrowOnce = false
                throw CocoaError(.fileWriteUnknown)
            }
            #endif
            let encoded = try json(input)
            let result = try decode(try await capturedHost.foregroundSync(command: command, requestJSON: encoded))
            guard result["ok"] is Bool,
                  result.flag("ok") ? result["value"] != nil
                    : (result.object("error")["message"] is String && result.object("error")["code"] is String) else {
                throw CocoaError(.coderReadCorrupt)
            }
            return result
        } catch {
            requireSettingsSyncRestart(capturedHost)
            return nil
        }
    }

    private func settingsSyncValue(_ result: CoreObject) -> CoreObject? {
        guard result.flag("ok") else {
            let failure = result.object("error")
            settingsSyncError = failure.text("message").isEmpty
                ? label("settings.feedback.actionFailed") : failure.text("message")
            if failure.text("code") == "STALE_REVISION" { settingsSyncNeedsReload = true }
            return nil
        }
        guard let value = result["value"] as? CoreObject else {
            if let capturedHost = host { requireSettingsSyncRestart(capturedHost) }
            return nil
        }
        return value
    }

    private func validSettingsSyncPanel(_ value: Any?) -> Bool {
        if value is NSNull { return true }
        guard let panel = value as? CoreObject, let kind = SettingsSyncFormKind(rawValue: panel.text("kind")) else { return false }
        if kind == .webdav { return true }
        let url = panel.object("url"), token = panel.object("token")
        return Set(panel.keys) == Set(["kind", "url", "allowInsecureHttp", "token", "save", "syncNow", "test", "lastSync"])
            && Set(url.keys) == Set(["label", "placeholder", "value", "hints", "invalid"])
            && url["label"] is String && (url["placeholder"] is String || url["placeholder"] is NSNull)
            && url["value"] is String && url["hints"] is [String] && (url["invalid"] is String || url["invalid"] is NSNull)
            && Set(token.keys) == Set(["label", "placeholder", "mask", "hint", "invalid"])
            && token["label"] is String && token["placeholder"] is String && token["mask"] is String
            && token.text("mask").allSatisfy({ $0 == "•" })
            && token["hint"] is String && (token["invalid"] is String || token["invalid"] is NSNull)
    }

    private func adoptSettingsSync(_ view: CoreObject, resetDraft: Bool, host capturedHost: CoreHost) -> Bool {
        guard !view.text("title").isEmpty, !view.text("configRevision").isEmpty,
              view.object("backend")["options"] is [CoreObject],
              view.object("backend").objects("options").allSatisfy({ ["off", "webdav", "selfhosted"].contains($0.text("option")) }),
              validSettingsSyncPanel(view["panel"]),
              view.object("panel").text("kind") != "selfhosted" || view["encryption"] is NSNull,
              validSettingsSyncEncryption(view["encryption"]) else {
            requireSettingsSyncRestart(capturedHost)
            return false
        }
        settingsSync = view
        if resetDraft {
            let panel = view.object("panel")
            settingsSyncURL = panel.object("url").text("value")
            settingsSyncUsername = panel.object("username").text("value")
            settingsSyncPassword = ""
            settingsSyncToken = ""
            settingsSyncTokenEdited = false
            settingsSyncAllowInsecure = panel.object("allowInsecureHttp").flag("value")
            settingsSyncOpeningURL = settingsSyncURL
            settingsSyncOpeningUsername = settingsSyncUsername
            settingsSyncOpeningAllowInsecure = settingsSyncAllowInsecure
            settingsSyncOpeningRevision = view.text("configRevision")
            settingsSyncValidatedURL = settingsSyncURL
            settingsSyncValidatedTokenDraft = nil
            settingsSyncNeedsReload = false
        }
        return true
    }

    // These messages are the shared transport's redacted user-facing toasts.
    private func adoptSettingsSyncToasts(_ value: CoreObject) -> Bool {
        let toasts = value.objects("toasts")
        let failed = toasts.filter { $0.text("tone") == "error" }
        let text: (CoreObject) -> String = { [$0.text("title"), $0.text("message")].filter { !$0.isEmpty }.joined(separator: "\n") }
        if !failed.isEmpty { settingsSyncError = failed.map(text).joined(separator: "\n"); return false }
        settingsSyncStatus = toasts.map(text).filter { !$0.isEmpty }.joined(separator: "\n")
        return true
    }

    func openSyncSettings() async {
        guard ready, selectedSurface == .settings, !busy, !retryNeeded, !settingsSyncPresented,
              !settingsAboutPresented, !settingsManagePresented, !settingsCalendarPresented, !calendarSettingActive, !settingsNotificationsPresented, !settingsGeneralPresented, !settingsGtdPresented, !settingsDataPresented,
              !settingsSyncRestartRequired, !appLock.concealed, settingsSyncEncryptionOwner == nil else { return }
        settingsSearchTask?.cancel()
        settingsSearchGeneration += 1
        settingsSyncPresented = true
        settingsSyncSession = UUID()
        settingsSyncError = nil
        settingsSyncStatus = nil
        settingsSyncNeedsReload = false
        guard settingsSyncAvailable, let capturedHost = host else { return }
        let session = settingsSyncSession
        busy = true
        defer { finishOperation() }
        guard let result = await callSettingsSync("openSyncSettings", input: [:], host: capturedHost),
              settingsSyncCurrent(capturedHost, session), let view = settingsSyncValue(result) else { return }
        if adoptSettingsSync(view, resetDraft: true, host: capturedHost) { _ = adoptSettingsSyncToasts(view) }
    }

    func closeSyncSettings() async {
        guard settingsSyncPresented, settingsSyncCanClose, !appLock.concealed else { return }
        let capturedHost = host
        let available = settingsSyncAvailable
        // Retire plaintext before the closing command can suspend.
        clearSettingsSyncForPrivacy()
        settingsSyncPresented = false
        let closedSession = settingsSyncSession
        guard available, let capturedHost else { return }
        busy = true
        defer { finishOperation() }
        guard let result = await callSettingsSync("closeSyncSettings", input: [:], host: capturedHost),
              host === capturedHost, settingsSyncSession == closedSession, !settingsSyncPresented,
              !appLock.concealed, !settingsSyncRestartRequired else { return }
        if !result.flag("ok") {
            settingsSyncPresented = true
            _ = settingsSyncValue(result)
            settingsSyncNeedsReload = true
        }
    }

    func reloadSyncSettings() async {
        guard settingsSyncPresented, settingsSyncCanClose, settingsSyncAvailable,
              !appLock.concealed, let capturedHost = host else { return }
        clearSettingsSyncForPrivacy()
        let session = settingsSyncSession
        busy = true
        defer { finishOperation() }
        guard let closed = await callSettingsSync("closeSyncSettings", input: [:], host: capturedHost),
              settingsSyncCurrent(capturedHost, session) else { return }
        guard closed.flag("ok") else { _ = settingsSyncValue(closed); return }
        guard let result = await callSettingsSync("openSyncSettings", input: [:], host: capturedHost),
              settingsSyncCurrent(capturedHost, session), let view = settingsSyncValue(result) else { return }
        if adoptSettingsSync(view, resetDraft: true, host: capturedHost) { _ = adoptSettingsSyncToasts(view) }
    }

    func clearSettingsSyncForPrivacy() {
        // Revoke delivery and local text synchronously; the captured owner keeps
        // busy until its accepted bridge call and any required host close settle.
        settingsSyncEncryptionTask?.cancel()
        settingsSyncPassphrases = [:]
        settingsSyncReadTask?.cancel()
        settingsSyncReadTask = nil
        settingsSyncGeneration += 1
        settingsSyncSession = UUID()
        settingsSyncURL = ""
        settingsSyncUsername = ""
        settingsSyncPassword = ""
        settingsSyncToken = ""
        settingsSyncTokenEdited = false
        settingsSyncAllowInsecure = false
        settingsSyncOpeningURL = ""
        settingsSyncOpeningUsername = ""
        settingsSyncOpeningAllowInsecure = false
        settingsSyncOpeningRevision = ""
        settingsSyncValidatedURL = ""
        settingsSyncValidatedTokenDraft = nil
        settingsSync = [:]
        settingsSyncStatus = nil
        settingsSyncError = nil
        if settingsSyncPresented { settingsSyncNeedsReload = true }
    }

    private func settingsSyncWireBool(_ value: Any?) -> Bool? {
        guard let number = value as? NSNumber, CFGetTypeID(number) == CFBooleanGetTypeID() else { return nil }
        return number.boolValue
    }

    private func settingsSyncEncryptionActionAllowed(_ action: CoreObject) -> Bool {
        switch action.text("type") {
        case "open", "submit": return Set(action.keys) == Set(["type", "flow"]) && ["unlock", "enable", "change", "disable", "abandon"].contains(action.text("flow"))
        case "cancel", "decline", "retry", "recheck": return Set(action.keys) == Set(["type"])
        default: return false
        }
    }

    // Admit selected saved-WebDAV and local setup flows, never returned plaintext or reveal controls.
    private func validSettingsSyncEncryption(_ value: Any?) -> Bool {
        if value is NSNull { return true }
        guard let card = value as? CoreObject, Set(card.keys) == Set(["title", "guide", "rows"]),
              card["title"] is String, let rows = card["rows"] as? [CoreObject], rows.count <= 128,
              card["guide"] is NSNull || card["guide"] is CoreObject else { return false }
        var fields = Set<String>()
        for row in rows {
            switch row.text("kind") {
            case "text":
                guard Set(row.keys) == Set(["kind", "text", "tone"]), row["text"] is String,
                      ["label", "description", "warning", "danger"].contains(row.text("tone")) else { return false }
            case "field":
                guard fields.insert(row.text("field")).inserted,
                      Set(row.keys) == Set(["kind", "field", "label", "secure", "maxLength", "tooLong"]),
                      ["current", "next", "confirm"].contains(row.text("field")), row["label"] is String, row["tooLong"] is String,
                      settingsSyncWireBool(row["secure"]) == true, let limit = row["maxLength"] as? NSNumber,
                      CFGetTypeID(limit) != CFBooleanGetTypeID(), limit.doubleValue == Double(limit.intValue),
                      limit.intValue > 0, limit.intValue <= 1000 else { return false }
            case "action":
                guard Set(row.keys) == Set(["kind", "label", "action", "enabled", "busy"]), row["label"] is String,
                      let action = row["action"] as? CoreObject, settingsSyncEncryptionActionAllowed(action),
                      settingsSyncWireBool(row["enabled"]) != nil, settingsSyncWireBool(row["busy"]) != nil else { return false }
            default: return false
            }
        }
        guard fields.isEmpty || fields == Set(["current"]) || fields == Set(["next", "confirm"])
            || fields == Set(["current", "next", "confirm"]) else { return false }
        if !fields.isEmpty {
            let flow = fields.count == 3 ? "change" : fields.contains("current") ? "unlock" : "enable"
            guard rows.contains(where: { $0.text("kind") == "action" && $0.object("action").text("type") == "submit"
                && $0.object("action").text("flow") == flow }) else { return false }
        }
        return true
    }

    private func settingsSyncEncryptionField(_ field: String) -> CoreObject? {
        settingsSync.object("encryption").objects("rows").first { $0.text("kind") == "field" && $0.text("field") == field }
    }
    private func settingsSyncEncryptionFields(_ flow: String) -> [String] {
        switch flow {
        case "unlock": return ["current"]
        case "enable": return ["next", "confirm"]
        case "change": return ["current", "next", "confirm"]
        default: return []
        }
    }
    func settingsSyncPassphrase(_ field: String) -> String { settingsSyncPassphrases[field] ?? "" }
    func settingsSyncPassphraseTooLong(_ field: String) -> String? {
        guard let row = settingsSyncEncryptionField(field), settingsSyncPassphrase(field).utf16.count > row.number("maxLength") else { return nil }
        return row.text("tooLong")
    }
    func setSettingsSyncPassphrase(_ value: String, field: String) {
        guard settingsSyncCanEdit, !settingsSyncDraftDirty, !settingsSyncChecking, settingsSyncEncryptionField(field) != nil else { return }
        settingsSyncPassphrases[field] = value
    }
    func settingsSyncEncryptionActionID(_ action: CoreObject) -> String {
        if action.text("type") == "submit" { return action.text("flow") }
        if action.text("type") == "open", action.text("flow") != "unlock" { return "open-" + action.text("flow") }
        return action.text("type")
    }
    private func settingsSyncEncryptionOffered(_ action: CoreObject, enabled: Bool) -> Bool {
        settingsSync.object("encryption").objects("rows").contains {
            $0.text("kind") == "action" && (!enabled || $0.flag("enabled")) && !$0.flag("busy")
                && $0.object("action").text("type") == action.text("type")
                && $0.object("action").text("flow") == action.text("flow")
        }
    }
    func settingsSyncEncryptionActionEnabled(_ action: CoreObject) -> Bool {
        guard settingsSyncCanEdit, !settingsSyncChecking, !settingsSyncDraftDirty,
              foregroundSyncSceneActive, UIApplication.shared.applicationState == .active,
              settingsSyncEncryptionActionAllowed(action), !settingsSyncOpeningRevision.isEmpty,
              settingsSync.text("configRevision") == settingsSyncOpeningRevision else { return false }
        if action.text("type") == "submit" {
            let fields = settingsSyncEncryptionFields(action.text("flow"))
            return settingsSyncEncryptionOffered(action, enabled: fields.isEmpty) && fields.allSatisfy {
                settingsSyncEncryptionField($0) != nil && !settingsSyncPassphrase($0).isEmpty && settingsSyncPassphraseTooLong($0) == nil
            }
        }
        return settingsSyncEncryptionOffered(action, enabled: true)
    }

    private func settingsSyncEncryptionCurrent(_ owner: SettingsSyncEncryptionOwner) -> Bool {
        settingsSyncEncryptionOwner?.id == owner.id && settingsSyncCurrent(owner.host, owner.session)
            && settingsSyncGeneration == owner.generation && !Task.isCancelled
            && foregroundSyncSceneActive && UIApplication.shared.applicationState == .active && !settingsSyncNeedsReload
    }

    private func settingsSyncEncryptionReply(_ encoded: String, action: Bool) throws -> CoreObject {
        let reply = try decode(encoded)
        guard let ok = settingsSyncWireBool(reply["ok"]) else { throw CocoaError(.coderReadCorrupt) }
        if !ok {
            let error = reply.object("error")
            guard Set(reply.keys) == Set(["ok", "error"]), Set(error.keys) == Set(["code", "message"]),
                  error["code"] is String, error["message"] is String else { throw CocoaError(.coderReadCorrupt) }
        } else {
            guard Set(reply.keys) == Set(["ok", "value"]), let value = reply["value"] as? CoreObject else { throw CocoaError(.coderReadCorrupt) }
            if action {
                guard Set(value.keys) == Set(["toasts", "passphrase"]), value["passphrase"] is NSNull,
                      let toasts = value["toasts"] as? [CoreObject], toasts.allSatisfy({
                          $0["title"] is String && $0["message"] is String && ["warning", "error", "success", "info"].contains($0.text("tone"))
                      }) else { throw CocoaError(.coderReadCorrupt) }
            }
        }
        return reply
    }

    func performSettingsSyncEncryption(_ action: CoreObject) async {
        guard settingsSyncEncryptionActionEnabled(action), let capturedHost = host, settingsSyncEncryptionTask == nil else { return }
        settingsSyncReadTask?.cancel()
        settingsSyncReadTask = nil
        settingsSyncGeneration += 1
        let owner = SettingsSyncEncryptionOwner(id: UUID(), host: capturedHost, session: settingsSyncSession,
            generation: settingsSyncGeneration, revision: settingsSyncOpeningRevision)
        settingsSyncEncryptionOwner = owner
        settingsSyncError = nil
        settingsSyncStatus = nil
        busy = true
        let passphrases = settingsSyncPassphrases
        let task = Task { await runSettingsSyncEncryption(owner, action: action, passphrases: passphrases) }
        settingsSyncEncryptionTask = task
        await task.value
    }

    private func runSettingsSyncEncryption(_ owner: SettingsSyncEncryptionOwner, action: CoreObject, passphrases: [String: String]) async {
        var staged = false
        do {
            guard settingsSyncEncryptionCurrent(owner), settingsSyncOpeningRevision == owner.revision, !settingsSyncDraftDirty else { throw CancellationError() }
            let fields = action.text("type") == "submit" ? settingsSyncEncryptionFields(action.text("flow")) : []
            for field in fields {
                // Typed may mutate before an acknowledgement is lost. From this
                // point only confirmed Submit retirement or closing this host is safe.
                staged = true
                let typed = try settingsSyncEncryptionReply(try await owner.host.foregroundSync(command: "runSyncEncryptionAction",
                    requestJSON: try json(["revision": owner.revision, "action": ["type": "typed", "field": field, "value": passphrases[field] ?? ""]])), action: true)
                guard settingsSyncEncryptionCurrent(owner), typed.flag("ok") else { throw CocoaError(.coderReadCorrupt) }
                #if DEBUG && (targetEnvironment(simulator) || NATIVE_DEVICE_TEST)
                if settingsSyncEncryptionTypedThrowOnce {
                    settingsSyncEncryptionTypedThrowOnce = false
                    throw CocoaError(.fileWriteUnknown)
                }
                if settingsSyncEncryptionTypedDelayOnce {
                    settingsSyncEncryptionTypedDelayOnce = false
                    settingsSyncEncryptionTypedHolding = true
                    await withCheckedContinuation { continuation in
                        DispatchQueue.main.asyncAfter(deadline: .now() + 8) { continuation.resume() }
                    }
                    settingsSyncEncryptionTypedHolding = false
                }
                #endif
                guard settingsSyncEncryptionCurrent(owner), typed.flag("ok") else { throw CocoaError(.coderReadCorrupt) }
            }
            if !fields.isEmpty {
                let fresh = try settingsSyncEncryptionReply(try await owner.host.foregroundSync(command: "syncSettings",
                    requestJSON: try json(["draft": ["url": settingsSyncURL]])), action: false)
                guard settingsSyncEncryptionCurrent(owner), fresh.flag("ok"), let view = fresh["value"] as? CoreObject,
                      view.text("configRevision") == owner.revision,
                      adoptSettingsSync(view, resetDraft: false, host: owner.host),
                      settingsSyncEncryptionOffered(action, enabled: true) else { throw CocoaError(.coderReadCorrupt) }
            }
            guard settingsSyncEncryptionCurrent(owner), settingsSyncOpeningRevision == owner.revision, !settingsSyncDraftDirty else { throw CancellationError() }
            var input: CoreObject = ["revision": owner.revision, "action": action]
            if ["submit", "decline", "recheck"].contains(action.text("type")) { input["requestId"] = owner.id.uuidString.lowercased() }
            let reply = try settingsSyncEncryptionReply(try await owner.host.foregroundSync(command: "runSyncEncryptionAction", requestJSON: try json(input)), action: true)
            if action.text("type") == "submit", reply.flag("ok") { staged = false }
            guard settingsSyncEncryptionCurrent(owner) else { throw CancellationError() }
            settingsSyncPassphrases = [:]
            guard let value = settingsSyncValue(reply) else {
                if staged { throw CocoaError(.coderReadCorrupt) }
                return finishSettingsSyncEncryption(owner)
            }
            _ = adoptSettingsSyncToasts(value)
            let read = try settingsSyncEncryptionReply(try await owner.host.foregroundSync(command: "syncSettings",
                requestJSON: try json(["draft": ["url": settingsSyncURL]])), action: false)
            guard settingsSyncEncryptionCurrent(owner) else { throw CancellationError() }
            if let view = settingsSyncValue(read) { _ = adoptSettingsSync(view, resetDraft: true, host: owner.host) }
        } catch {
            if !Task.isCancelled { requireSettingsSyncRestart(owner.host) }
        }
        if staged {
            requireSettingsSyncRestart(owner.host)
            // The last accepted native call above has returned/drained. Close
            // even an old captured host, while never gating its replacement.
            await owner.host.close()
        }
        finishSettingsSyncEncryption(owner)
    }

    private func finishSettingsSyncEncryption(_ owner: SettingsSyncEncryptionOwner) {
        guard settingsSyncEncryptionOwner?.id == owner.id else { return }
        settingsSyncEncryptionOwner = nil
        settingsSyncEncryptionTask = nil
        settingsSyncPassphrases = [:]
        if host === owner.host { finishOperation() }
    }

    func setSettingsSyncURL(_ value: String) {
        guard settingsSyncCanEdit else { return }
        settingsSyncURL = value
        settingsSyncGeneration += 1
        settingsSyncError = nil
        scheduleSettingsSyncRead()
    }
    func setSettingsSyncUsername(_ value: String) {
        guard settingsSyncCanEdit else { return }
        settingsSyncUsername = value
        settingsSyncError = nil
    }
    func setSettingsSyncPassword(_ value: String) {
        guard settingsSyncCanEdit else { return }
        settingsSyncPassword = value
        settingsSyncError = nil
    }
    func setSettingsSyncToken(_ value: String) {
        guard settingsSyncCanEdit, settingsSyncFormKind == .selfhosted else { return }
        settingsSyncToken = value
        settingsSyncTokenEdited = true
        settingsSyncGeneration += 1
        settingsSyncError = nil
        scheduleSettingsSyncRead()
    }
    func setSettingsSyncAllowInsecure(_ value: Bool) {
        guard settingsSyncCanEdit else { return }
        settingsSyncAllowInsecure = value
        settingsSyncError = nil
    }

    private func scheduleSettingsSyncRead() {
        settingsSyncReadTask?.cancel()
        settingsSyncReadTask = Task {
            do { try await Task.sleep(nanoseconds: 150_000_000) } catch { return }
            guard !Task.isCancelled, settingsSyncPresented, !settingsSyncNeedsReload,
                  !settingsSyncRestartRequired, !busy else { return }
            // Only cancel the delay, never an already-dispatched foreground command.
            settingsSyncReadTask = nil
            await readSettingsSyncModel()
        }
    }

    private func readSettingsSyncModel(resetDraft: Bool = false) async {
        guard settingsSyncPresented, !settingsSyncChecking, !settingsSyncNeedsReload,
              !settingsSyncRestartRequired, !appLock.concealed, let capturedHost = host else { return }
        let session = settingsSyncSession, generation = settingsSyncGeneration
        let url = settingsSyncURL, token = settingsSyncTokenDraft, form = settingsSyncFormKind
        var draft: CoreObject = ["url": url]
        if form == .selfhosted { draft["token"] = token.map { $0 as Any } ?? NSNull() }
        settingsSyncChecking = true
        defer {
            settingsSyncChecking = false
            if settingsSyncCurrent(capturedHost, session), generation != settingsSyncGeneration,
               !busy, !settingsSyncNeedsReload { scheduleSettingsSyncRead() }
        }
        guard let result = await callSettingsSync("syncSettings", input: ["draft": draft], host: capturedHost),
              settingsSyncCurrent(capturedHost, session), generation == settingsSyncGeneration,
              let view = settingsSyncValue(result) else { return }
        // Validation for one credential shape cannot admit another panel's fields.
        guard resetDraft || SettingsSyncFormKind(rawValue: view.object("panel").text("kind")) == form else {
            settingsSyncNeedsReload = true
            return
        }
        if adoptSettingsSync(view, resetDraft: resetDraft, host: capturedHost) {
            settingsSyncValidatedURL = resetDraft ? settingsSyncURL : url
            settingsSyncValidatedTokenDraft = resetDraft ? nil : token
        }
    }

    func selectSettingsSyncBackend(_ option: String) async {
        guard settingsSyncCanEdit, !settingsSyncChecking,
              settingsSync.object("backend").objects("options").contains(where: { $0.text("option") == option && !$0.flag("selected") }),
              let capturedHost = host else { return }
        let session = settingsSyncSession
        settingsSyncReadTask?.cancel(); settingsSyncReadTask = nil
        settingsSyncGeneration += 1
        settingsSyncError = nil; settingsSyncStatus = nil
        busy = true
        defer { finishOperation() }
        guard let result = await callSettingsSync("selectSyncBackend",
            input: ["requestId": UUID().uuidString.lowercased(), "option": option], host: capturedHost),
              settingsSyncCurrent(capturedHost, session), let value = settingsSyncValue(result) else { return }
        let succeeded = adoptSettingsSyncToasts(value)
        await readSettingsSyncModel(resetDraft: succeeded)
    }

    func performSettingsSync(_ action: String) async {
        guard ["save", "syncNow", "test"].contains(action), settingsSyncActionEnabled(action),
              let capturedHost = host, let form = settingsSyncFormKind, !settingsSyncOpeningRevision.isEmpty else { return }
        let session = settingsSyncSession
        let command = action == "save" ? "saveSyncBackend" : action == "test" ? "testSyncConnection" : "syncNow"
        var input: CoreObject
        switch form {
        case .webdav:
            input = ["webdav": ["url": settingsSyncURL, "username": settingsSyncUsername,
                "password": settingsSyncPassword.isEmpty ? NSNull() : settingsSyncPassword as Any,
                "allowInsecureHttp": settingsSyncAllowInsecure]]
        case .selfhosted:
            input = ["selfHosted": ["url": settingsSyncURL,
                "token": settingsSyncTokenDraft.map { $0 as Any } ?? NSNull(),
                "allowInsecureHttp": settingsSyncAllowInsecure]]
        }
        if action != "test" {
            input["requestId"] = UUID().uuidString.lowercased()
            input["revision"] = settingsSyncOpeningRevision
        }
        settingsSyncReadTask?.cancel(); settingsSyncReadTask = nil
        settingsSyncGeneration += 1
        settingsSyncError = nil; settingsSyncStatus = nil
        busy = true
        defer { finishOperation() }
        guard let result = await callSettingsSync(command, input: input, host: capturedHost),
              settingsSyncCurrent(capturedHost, session), let value = settingsSyncValue(result) else { return }
        let succeeded = adoptSettingsSyncToasts(value)
        // A known failure preserves both the fields and their opening revision.
        await readSettingsSyncModel(resetDraft: succeeded && action != "test")
    }

    func openGtdSettings() async {
        guard ready, selectedSurface == .settings, !settingsAboutPresented, !settingsManagePresented, !settingsCalendarPresented, !calendarSettingActive, !settingsNotificationsPresented, !settingsGeneralPresented, !busy, !retryNeeded else { return }
        settingsSearchTask?.cancel()
        settingsSearchGeneration += 1
        settingsGtdPresented = true
        settingsGtdArchivePresented = false
        settingsGtdReviewPresented = false
        settingsGtdInboxPresented = false
        settingsGtdCapturePresented = false
        settingsGtdTaskEditorPresented = false
        gtdTaskEditorFieldId = nil
        gtdCaptureAreaPicker = false
        gtdWorkflowError = nil
        busy = true
        defer { finishOperation() }
        do { try await readGtdSettings() }
        catch { gtdWorkflowReadError = error.localizedDescription }
    }

    func openGtdSubpage(_ page: String) async {
        guard ["review", "inbox", "capture", "taskEditor", "autoArchive"].contains(page), gtdWorkflowEnabled,
              !settingsGtdArchivePresented, !settingsGtdReviewPresented, !settingsGtdInboxPresented, !settingsGtdCapturePresented, !settingsGtdTaskEditorPresented else { return }
        if gtdWorkflowDraftDirty {
            await commitGtdScheduleDraft()
            guard gtdWorkflowError == nil else { return }
        }
        guard gtdWorkflowEnabled, !gtdWorkflowDraftDirty else { return }
        settingsGtdArchivePresented = page == "autoArchive"
        settingsGtdReviewPresented = page == "review"
        settingsGtdInboxPresented = page == "inbox"
        settingsGtdCapturePresented = page == "capture"
        settingsGtdTaskEditorPresented = page == "taskEditor"
        if settingsGtdTaskEditorPresented {
            gtdTaskEditorFieldId = nil
            gtdTaskEditorExpandedResetKey = nil
            gtdTaskEditorExpanded = [:]
        }
        gtdWorkflowError = nil
        busy = true
        defer { finishOperation() }
        do { try await readGtdSettings() }
        catch { gtdWorkflowReadError = error.localizedDescription }
    }

    func closeGtdSettings() async {
        guard settingsGtdPresented, !busy, !retryNeeded, !gtdWorkflowPending else { return }
        if gtdTaskEditorFieldId != nil { closeGtdTaskEditorField(); return }
        if gtdCaptureAreaPicker { closeGtdCaptureAreaPicker(); return }
        if settingsGtdArchivePresented || settingsGtdReviewPresented || settingsGtdInboxPresented || settingsGtdCapturePresented || settingsGtdTaskEditorPresented {
            settingsGtdArchivePresented = false
            settingsGtdReviewPresented = false
            settingsGtdInboxPresented = false
            settingsGtdCapturePresented = false
            settingsGtdTaskEditorPresented = false
            gtdTaskEditorFieldId = nil
            gtdCaptureAreaPicker = false
            gtdWorkflowError = nil
            busy = true
            defer { finishOperation() }
            do { try await readGtdSettings() }
            catch { gtdWorkflowReadError = error.localizedDescription }
            return
        }
        if gtdWorkflowDraftDirty {
            await commitGtdScheduleDraft()
            guard gtdWorkflowError == nil else { return }
        }
        guard !busy, !retryNeeded, !gtdWorkflowPending, !gtdWorkflowDraftDirty else { return }
        settingsGtdPresented = false
        gtdWorkflowReadError = nil
    }

    private func readGtdSettings() async throws {
        if settingsGtdArchivePresented {
            let options = try await query("gtdArchiveOptions", ["{}"])
            let content = options.object("archive"), expected = options.object("expected")
            guard Set(options.keys) == Set(["archive", "expected"]), !content.text("title").isEmpty,
                  !expected.isEmpty else { throw CocoaError(.coderReadCorrupt) }
            gtdArchive = content
            gtdWorkflowExpected = ["autoArchiveDays": expected]
            gtdWorkflowReadError = nil
            gtdWorkflowAwaitingRefresh = false
            return
        }
        if settingsGtdCapturePresented {
            let options = try await query("gtdCaptureAreaOptions", [try json(["offset": 0, "limit": 50])])
            let parsing = try await query("gtdCaptureParseOptions", ["{}"])
            let expected = parsing.object("expected"), areaExpected = options.object("expected")
            guard ["quickAddAutoClean", "naturalLanguageDates"].allSatisfy({ field in
                let witness = expected.object(field)
                return witness.flag("stampPresent") == areaExpected.flag("stampPresent")
                    && witness.text("stamp") == areaExpected.text("stamp")
            }) else { throw CocoaError(.coderReadCorrupt) }
            var capture = options.object("capture")
            guard !capture.text("title").isEmpty, options.number("offset") == 0 else { throw CocoaError(.coderReadCorrupt) }
            for field in ["quickAddAutoClean", "naturalLanguageDates"] { capture[field] = parsing.object("capture").object(field) }
            gtdCapture = capture
            gtdCaptureAreaOptions = capture.object("defaultArea").objects("options")
            gtdCaptureAreaTotal = options.number("total")
            gtdCaptureAreaRevision = options.text("revision")
            gtdWorkflowExpected = expected.merging(["defaultArea": areaExpected]) { _, new in new }
            gtdWorkflowReadError = nil
            gtdWorkflowAwaitingRefresh = false
            return
        }
        let reviewing = settingsGtdReviewPresented, inboxing = settingsGtdInboxPresented, editing = settingsGtdTaskEditorPresented
        let options = try await query(editing ? "gtdTaskEditorOpenOptions" : inboxing ? "gtdInboxOptions" : reviewing ? "gtdReviewOptions" : "gtdWorkflowOptions", ["{}"])
        let contentKey = editing ? "taskEditor" : inboxing ? "inbox" : reviewing ? "review" : "hub"
        var content = options.object(contentKey), expected = options.object("expected")
        let fields = editing ? ["scheduling", "organization", "details"] : inboxing ? ["inboxTwoMinute", "inboxProjectFirst", "inboxContextStep", "inboxSchedule"] : reviewing ? ["dailyReviewFocusStep", "weeklyReviewContextStep"] : ["defaultScheduleTime", "focusTaskLimit", "focusIncludeStartDates", "defaultProjectFlowMode"]
        guard Set(options.keys) == Set([contentKey, "expected"]), !content.text("title").isEmpty,
              Set(expected.keys) == Set(fields) else { throw CocoaError(.coderReadCorrupt) }
        if editing {
            gtdTaskEditorPresetError = nil
            do {
                let presets = try await query("gtdTaskEditorPresetOptions", [try json(["rawMode": rawTaskOpenMode])])
                let presetExpected = presets.object("expected")
                guard fields.allSatisfy({ field in
                    let witness = expected.object(field)
                    return witness.flag("stampPresent") == presetExpected.flag("stampPresent")
                        && witness.text("stamp") == presetExpected.text("stamp")
                }) else { throw CocoaError(.coderReadCorrupt) }
                content["presets"] = presets.object("taskEditor").object("presets")
                content["reset"] = presets.object("taskEditor").object("reset")
                content["openMode"] = presets.object("taskEditor").object("openMode")
                expected["taskEditorPreset"] = presetExpected
                expected["taskEditorReset"] = presetExpected
                let fieldOptions = try await query("gtdTaskEditorFieldOptions", ["{}"])
                let fieldExpected = fieldOptions.object("expected")
                guard try json(fieldExpected) == json(presetExpected) else { throw CocoaError(.coderReadCorrupt) }
                let openGroups = content.objects("groups")
                content["groups"] = fieldOptions.object("taskEditor").objects("groups").map { group in
                    var merged = group
                    if let original = openGroups.first(where: { $0.text("id") == group.text("id") }) {
                        merged["defaultOpen"] = original.object("defaultOpen")
                    }
                    return merged
                }
                expected["taskEditorFieldVisible"] = fieldExpected
                expected["taskEditorFieldSection"] = fieldExpected
                expected["taskEditorOrder"] = fieldExpected
                let editor = fieldOptions.object("taskEditor")
                let resetKey = editor.text("expandedResetKey")
                if gtdTaskEditorExpandedResetKey != resetKey {
                    // Initial cold recovery retains its field sheet; later default changes follow RN's reset.
                    if gtdTaskEditorExpandedResetKey != nil { gtdTaskEditorFieldId = nil }
                    let defaults = editor.object("initiallyExpanded")
                    gtdTaskEditorExpanded = defaults.mapValues { $0 as? Bool ?? false }
                    gtdTaskEditorExpandedResetKey = resetKey
                }
            } catch {
                // Unsupported legacy layout prevents layout changes, but section defaults remain usable.
                guard isDefiniteRejection(error), error.localizedDescription.hasPrefix("INVALID_INPUT:") else { throw error }
                gtdTaskEditorPresetError = error.localizedDescription
            }
            gtdTaskEditor = content
        }
        else if inboxing { gtdInbox = content }
        else if reviewing { gtdReview = content }
        else {
            gtdWorkflow = content
            gtdScheduleDraft = content.object("defaultScheduleTime").text("value")
        }
        gtdWorkflowExpected = expected
        gtdWorkflowReadError = nil
        gtdWorkflowAwaitingRefresh = false
    }

    func chooseTaskOpenMode(_ edit: CoreObject) async {
        guard gtdWorkflowEnabled, settingsGtdTaskEditorPresented,
              let option = gtdTaskEditor.object("openMode").objects("options").first(where: {
                  taskDraftValuesEqual($0.object("edit"), edit)
              }), !option.flag("selected") else { return }
        busy = true
        defer { finishOperation() }
        do {
            let options = try await query("gtdTaskEditorPresetOptions", [try json(["rawMode": option.text("value")])])
            let mode = options.object("taskEditor").object("openMode")
            guard mode.objects("options").first(where: { $0.flag("selected") })?.text("value") == option.text("value") else {
                throw CocoaError(.coderReadCorrupt)
            }
            preferenceDefaults.set(option.text("value"), forKey: taskOpenModePreference)
            gtdTaskEditor["openMode"] = mode
            gtdTaskEditorPresetError = nil
        } catch { gtdTaskEditorPresetError = error.localizedDescription }
    }

    func toggleGtdTaskEditorGroup(_ id: String) {
        guard gtdWorkflowEnabled, settingsGtdTaskEditorPresented,
              gtdTaskEditor.objects("groups").contains(where: { $0.text("id") == id }) else { return }
        gtdTaskEditorExpanded[id] = !(gtdTaskEditorExpanded[id] ?? true)
    }

    func openGtdTaskEditorField(_ id: String) {
        guard gtdWorkflowEnabled, settingsGtdTaskEditorPresented,
              gtdTaskEditor.objects("groups").flatMap({ $0.objects("fields") }).contains(where: { $0.text("id") == id }) else { return }
        gtdTaskEditorFieldId = id
    }

    func closeGtdTaskEditorField() {
        guard !busy, !retryNeeded, !gtdWorkflowPending else { return }
        gtdTaskEditorFieldId = nil
    }

    func openGtdCaptureAreaPicker() {
        guard gtdWorkflowEnabled, settingsGtdCapturePresented else { return }
        gtdCaptureAreaPicker = true
    }

    func closeGtdCaptureAreaPicker() {
        guard !busy, !retryNeeded, !gtdWorkflowPending else { return }
        gtdCaptureAreaPicker = false
    }

    func loadMoreGtdCaptureAreas() async {
        guard gtdWorkflowEnabled, gtdCaptureAreaPicker, gtdCaptureAreaOptions.count < gtdCaptureAreaTotal else { return }
        busy = true
        defer { finishOperation() }
        do {
            let offset = gtdCaptureAreaOptions.count
            let options = try await query("gtdCaptureAreaOptions", [try json(["offset": offset, "limit": 50, "revision": gtdCaptureAreaRevision])])
            guard options.number("offset") == offset, options.number("total") == gtdCaptureAreaTotal,
                  options.text("revision") == gtdCaptureAreaRevision,
                  try json(options.object("expected")) == json(gtdWorkflowExpected.object("defaultArea")) else { throw CocoaError(.coderReadCorrupt) }
            let rows = options.object("capture").object("defaultArea").objects("options")
            guard !rows.isEmpty else { throw CocoaError(.coderReadCorrupt) }
            gtdCaptureAreaOptions += rows
        } catch { gtdWorkflowReadError = error.localizedDescription }
    }

    func chooseGtdCaptureArea(_ edit: CoreObject) async {
        await chooseGtdWorkflow(edit)
        if !gtdWorkflowPending && gtdWorkflowError == nil && gtdWorkflowReadError == nil { gtdCaptureAreaPicker = false }
    }

    func setGtdScheduleDraft(_ value: String) {
        guard gtdWorkflowEnabled else { return }
        gtdScheduleDraft = value
        gtdWorkflowError = nil
    }

    func commitGtdScheduleDraft() async {
        guard gtdWorkflowEnabled, gtdWorkflowDraftDirty, !appLock.concealed else { return }
        busy = true
        let draft = gtdScheduleDraft
        do {
            let normalized = try await query("gtdWorkflowDraft", [try json(["value": draft])])
            guard normalized.flag("valid") else {
                gtdScheduleDraft = gtdWorkflow.object("defaultScheduleTime").text("value")
                gtdWorkflowError = gtdWorkflow.object("defaultScheduleTime").text("invalidMessage")
                finishOperation()
                return
            }
            gtdScheduleDraft = normalized.text("value")
            finishOperation()
            await saveGtdWorkflow(["type": "defaultScheduleTime", "value": normalized.text("value")])
        } catch {
            if isDefiniteRejection(error) {
                gtdScheduleDraft = gtdWorkflow.object("defaultScheduleTime").text("value")
                gtdWorkflowError = gtdWorkflow.object("defaultScheduleTime").text("invalidMessage")
            } else { gtdWorkflowError = error.localizedDescription }
            finishOperation()
        }
    }

    func chooseGtdWorkflow(_ edit: CoreObject) async {
        guard gtdWorkflowEnabled else { return }
        if gtdWorkflowDraftDirty {
            await commitGtdScheduleDraft()
            guard gtdWorkflowError == nil else { return }
        }
        guard gtdWorkflowEnabled, !gtdWorkflowDraftDirty else { return }
        await saveGtdWorkflow(edit)
    }

    private func saveGtdWorkflow(_ edit: CoreObject) async {
        guard gtdWorkflowEnabled, let expected = gtdWorkflowExpected[edit.text("type") == "taskEditorSectionOpen" ? edit.text("section") : edit.text("type")] as? CoreObject else { return }
        gtdWorkflowEdit = edit
        gtdWorkflowError = nil
        busy = true
        defer { finishOperation() }
        do {
            let request = try json(["requestId": UUID().uuidString.lowercased(), "edit": edit, "expected": expected])
            gtdWorkflowRequest = request
            try acknowledgeGtdWorkflow(await query("gtdWorkflow", [request]))
            try await readGtdSettings()
        } catch { await handleGtdWorkflowError(error) }
    }

    private func acknowledgeGtdWorkflow(_ result: CoreObject) throws {
        let editing = gtdWorkflowEdit.text("type") == "taskEditorSectionOpen"
        let resetting = gtdWorkflowEdit.text("type") == "taskEditorReset"
        let fieldEdit = ["taskEditorFieldVisible", "taskEditorFieldSection", "taskEditorOrder"].contains(gtdWorkflowEdit.text("type"))
        guard gtdWorkflowRequest != nil, Set(result.keys) == Set(resetting ? ["type", "changed"] : editing ? ["type", "section", "value", "changed"] : fieldEdit ? ["type", "field", "value", "changed"] : ["type", "value", "changed"]),
              !editing || result.text("section") == gtdWorkflowEdit.text("section"),
              !fieldEdit || result.text("field") == gtdWorkflowEdit.text("field"),
              result.text("type") == gtdWorkflowEdit.text("type"), result["changed"] is Bool,
              try json(["value": result["value"] ?? NSNull()]) == json(["value": gtdWorkflowEdit["value"] ?? NSNull()]) else { throw CocoaError(.coderReadCorrupt) }
        gtdWorkflowRequest = nil
        gtdWorkflowAwaitingRefresh = true
        gtdWorkflowError = nil
        retryNeeded = false
        error = nil
    }

    private func handleGtdWorkflowError(_ failure: Error) async {
        gtdWorkflowError = failure.localizedDescription
        if gtdWorkflowRequest != nil && isDefiniteRejection(failure) {
            gtdWorkflowRequest = nil
            retryNeeded = false
            error = nil
            gtdWorkflowAwaitingRefresh = true
            do { try await readGtdSettings() }
            catch { gtdWorkflowReadError = error.localizedDescription }
        } else if gtdWorkflowRequest != nil {
            retryNeeded = true
            error = failure.localizedDescription
        } else {
            gtdWorkflowReadError = failure.localizedDescription
        }
    }

    func retryGtdWorkflow() async {
        if retryNeeded { await retry(); return }
        guard settingsGtdPresented, !busy, gtdWorkflowRequest == nil else { return }
        busy = true
        defer { finishOperation() }
        do { try await readGtdSettings(); gtdWorkflowError = nil }
        catch { gtdWorkflowReadError = error.localizedDescription }
    }

    private func observeDiagnosticsConcealment() {
        guard diagnosticsLockObserver == nil else { return }
        diagnosticsLockObserver = appLock.$enabled.combineLatest(appLock.$locked).sink { [weak self] enabled, locked in
            if enabled == nil || locked {
                self?.invalidateTaskAttachmentOpen()
                self?.invalidateProjectAttachmentOpen()
                self?.cancelProjectFileImport()
                self?.invalidateDiagnostics(dropCache: true)
            }
        }
    }

    private func beginDiagnostics(owner: UUID) {
        observeDiagnosticsConcealment()
        invalidateDiagnostics()
        diagnosticsOwner = owner
        diagnosticsSession = UUID()
    }

    func invalidateDiagnostics(dropCache: Bool = false) {
        dismissBackupShare()
        cancelBackupImportPreview()
        backupImportPickerPresented = false
        backupImportPickerID = nil
        backupPickerSession = nil
        backupImportBusy = false
        backupImportError = nil
        cancelBackupRestore()
        backupSnapshots = []
        backupSnapshotReadError = nil
        backupDocumentResult = [:]
        if backupDocumentHost !== host {
            backupDocumentPending = false
            backupDocumentReply = nil
            backupDocumentHost = nil
            backupUndoSnapshotName = nil
        }
        backupExportBusy = false
        backupExportError = nil
        diagnosticsSession = nil
        diagnosticsOwner = nil
        diagnosticsShare = nil
        diagnosticsMessage = nil
        diagnosticsFileBusy = false
        if dropCache {
            diagnosticsCacheHost = nil
            dataSettings = [:]
            settingsDataPresented = false
        }
    }

    func openCachedFailureDiagnostics(owner: UUID) -> Bool {
        guard cachedFailureDiagnosticsAvailable else { return false }
        beginDiagnostics(owner: owner)
        return true
    }

    func closeDiagnostics(owner: UUID) {
        guard diagnosticsOwner == owner else { return }
        invalidateDiagnostics()
        if owner == settingsDiagnosticsOwner { settingsDataPresented = false }
        // The original domain error, request and retry context are untouched.
    }

    func diagnosticsCurrent(owner: UUID, session: UUID) -> Bool {
        ready && !appLock.concealed && diagnosticsOwner == owner && diagnosticsSession == session
            && diagnosticsCacheIsCurrent
    }

    func diagnosticsFileActionsEnabled(owner: UUID) -> Bool {
        diagnosticsOwner == owner && diagnosticsSession != nil && diagnosticsCacheIsCurrent
            && ready && !appLock.concealed && !busy && !diagnosticsFileBusy && diagnosticsShare == nil
            && !backupExportBusy && backupShare == nil && !backupTransferActive
    }

    private var backupTransferActive: Bool {
        backupImportPickerPresented || backupImportBusy || !backupImportPreview.isEmpty
            || !backupRestoreConfirmation.isEmpty || backupDocumentPending
    }

    var backupImportEnabled: Bool { backupExportEnabled && backupSnapshotReadError == nil }

    var backupUndoEnabled: Bool {
        backupImportEnabled && backupUndoSnapshotName.map { name in backupSnapshots.contains { $0.name == name } } == true
    }

    var backupImportIsReplacement: Bool { backupImportAction == .replace }

    var backupResultReadRetryNeeded: Bool {
        backupDocumentReply != nil && backupDocumentResult.isEmpty && !backupDocumentPending
    }

    var backupExportEnabled: Bool {
        settingsDataPresented && diagnosticsOwner == settingsDiagnosticsOwner
            && diagnosticsFileActionsEnabled(owner: settingsDiagnosticsOwner)
            && !retryNeeded && diagnosticsReadError == nil && dataSettingRequest == nil
            && !dataSettingAwaitingRefresh
    }

    func exportDataBackup(format: NativeBackupFormat = .json) async {
        guard backupExportEnabled, let session = diagnosticsSession, let currentHost = host else { return }
        backupExportBusy = true
        backupExportError = nil
        defer {
            if host === currentHost, diagnosticsCurrent(owner: settingsDiagnosticsOwner, session: session) {
                backupExportBusy = false
            }
        }
        do {
            let prepared = try await currentHost.prepareDataBackup(format: format)
            #if DEBUG && targetEnvironment(simulator)
            if backupExportTestHoldOnce {
                backupExportTestHoldOnce = false
                backupExportTestState = "held"
                let until = ProcessInfo.processInfo.systemUptime + 900
                while (diagnosticsSession == nil || diagnosticsSession == session), host === currentHost,
                      !appLock.concealed, ProcessInfo.processInfo.systemUptime < until, !Task.isCancelled {
                    try? await Task.sleep(nanoseconds: 20_000_000)
                }
            }
            #endif
            guard host === currentHost, settingsDataPresented,
                  diagnosticsCurrent(owner: settingsDiagnosticsOwner, session: session), !retryNeeded, !Task.isCancelled else {
                await currentHost.discardDataBackup(prepared.id)
                #if DEBUG && targetEnvironment(simulator)
                if backupExportTestState == "held" { backupExportTestState = "discarded" }
                #endif
                return
            }
            backupShareHost = currentHost
            backupShare = prepared
        } catch {
            if host === currentHost, diagnosticsCurrent(owner: settingsDiagnosticsOwner, session: session) {
                let failureField: String
                switch format {
                case .json: failureField = "failed"
                case .csv: failureField = "csvFailed"
                case .tasknotes: failureField = "tasknotesFailed"
                }
                backupExportError = dataSettings.object("backup").text(failureField)
            }
        }
    }

    func dismissBackupShare() {
        if let prepared = backupShare, let owner = backupShareHost {
            Task { await owner.discardDataBackup(prepared.id) }
        }
        backupShare = nil
        backupShareHost = nil
    }

    func openBackupImportPicker(action: NativeBackupImportAction = .merge) {
        guard backupImportEnabled, let session = diagnosticsSession else { return }
        backupImportError = nil
        backupPickerSession = session
        backupImportPickerAction = action
        backupImportPickerID = UUID()
        backupImportPickerPresented = true
    }

    func setBackupImportPickerPresented(_ presented: Bool) {
        if !presented { backupImportPickerPresented = false }
        // Cancel may dismiss without a completion. Only presentation gates
        // actions; retain identity to recognize a late selection completion.
    }

    func receiveBackupImportSelection(_ result: Result<[URL], Error>, pickerID: UUID?, action: NativeBackupImportAction) async {
        guard let pickerID, pickerID == backupImportPickerID, action == backupImportPickerAction else { return }
        let session = backupPickerSession
        let currentHost = host
        backupImportPickerID = nil
        backupPickerSession = nil
        backupImportPickerPresented = false
        guard let session, let currentHost, backupSessionIsCurrent(currentHost, session: session),
              backupImportEnabled, !Task.isCancelled else { return }
        // The picker can dismiss before its callback. Recheck all action gates
        // so a late callback cannot overlap a new export, share, or write.
        let url: URL
        switch result {
        case .success(let urls):
            guard urls.count == 1, let selected = urls.first else { return }
            url = selected
        case .failure(let failure):
            let error = failure as NSError
            if error.domain != NSCocoaErrorDomain || error.code != NSUserCancelledError {
                backupImportError = backupTransferFailure(mode: action.operation)
            }
            return
        }
        backupImportBusy = true
        defer { if backupSessionIsCurrent(currentHost, session: session) { backupImportBusy = false } }
        do {
            let prepared = try await currentHost.prepareBackupImport(url, action: action)
            guard backupSessionIsCurrent(currentHost, session: session), !retryNeeded, !Task.isCancelled else {
                await currentHost.discardBackupImport(prepared.id)
                return
            }
            do {
                let model = try decode(prepared.json)
                guard prepared.action == action,
                      Set(model.keys) == Set(["valid", "title", "summary", "confirmLabel", "cancelLabel", "errorTitle", "errorMessage"]),
                      model["valid"] is Bool,
                      ["title", "summary", "confirmLabel", "cancelLabel", "errorTitle", "errorMessage"].allSatisfy({ model[$0] is String }),
                      !model.text("cancelLabel").isEmpty else { throw CocoaError(.coderReadCorrupt) }
                backupImportID = prepared.id
                backupImportHost = currentHost
                backupImportSession = session
                backupImportAction = prepared.action
                backupImportPreview = model
            } catch {
                await currentHost.discardBackupImport(prepared.id)
                throw error
            }
        } catch {
            if backupSessionIsCurrent(currentHost, session: session) {
                backupImportError = backupControlledFailure(error, mode: action.operation)
            }
        }
    }

    func cancelBackupImportPreview() {
        if let id = backupImportID, let owner = backupImportHost {
            Task { await owner.discardBackupImport(id) }
        }
        backupImportID = nil
        backupImportHost = nil
        backupImportSession = nil
        backupImportAction = nil
        backupImportPreview = [:]
    }

    func confirmBackupImport() async {
        guard let id = backupImportID, let currentHost = backupImportHost, let session = backupImportSession,
              let action = backupImportAction,
              backupSessionIsCurrent(currentHost, session: session), backupImportPreview.flag("valid"),
              !busy, !retryNeeded, !backupImportBusy, !backupDocumentPending else { return }
        // From dispatch onward the host owns acceptance and any owed journal.
        // Session dismissal must not delete or re-prepare that accepted operation.
        backupImportID = nil
        backupImportHost = nil
        backupImportSession = nil
        backupImportAction = nil
        backupImportPreview = [:]
        beginBackupDocumentOperation(currentHost, mode: action.operation)
        defer { finishOperation() }
        do { try await acceptBackupDocumentReply(await currentHost.mergeBackupImport(id), from: currentHost) }
        catch {
            if isDefiniteRejection(error) { await currentHost.discardBackupImport(id) }
            handleBackupDocumentFailure(error, from: currentHost)
        }
    }

    func requestBackupRestore(_ snapshot: BackupSnapshotRow) async {
        guard backupImportEnabled, backupSnapshots.contains(where: { $0.id == snapshot.id && $0.referenceJSON == snapshot.referenceJSON }),
              let currentHost = host, let session = diagnosticsSession else { return }
        backupImportBusy = true
        backupImportError = nil
        defer { if backupSessionIsCurrent(currentHost, session: session) { backupImportBusy = false } }
        do {
            let model = try decode(await currentHost.backupSnapshotRestoreModel(snapshot.referenceJSON))
            guard Set(model.keys) == Set(["title", "message", "confirmLabel", "cancelLabel"]),
                  model.values.allSatisfy({ $0 is String }),
                  ["title", "message", "confirmLabel", "cancelLabel"].allSatisfy({ !model.text($0).isEmpty }) else {
                throw CocoaError(.coderReadCorrupt)
            }
            guard backupSessionIsCurrent(currentHost, session: session), !retryNeeded, !Task.isCancelled else { return }
            backupRestoreReference = snapshot.referenceJSON
            backupRestoreSession = session
            backupRestoreConfirmation = model
        } catch {
            if backupSessionIsCurrent(currentHost, session: session) { backupImportError = backupTransferFailure(mode: "restore") }
        }
    }

    func requestBackupUndo() async {
        guard backupUndoEnabled, let name = backupUndoSnapshotName,
              let snapshot = backupSnapshots.first(where: { $0.name == name }) else { return }
        await requestBackupRestore(snapshot)
    }

    func cancelBackupRestore() {
        backupRestoreReference = nil
        backupRestoreSession = nil
        backupRestoreConfirmation = [:]
    }

    func confirmBackupRestore() async {
        guard let reference = backupRestoreReference, let session = backupRestoreSession, let currentHost = host,
              backupSessionIsCurrent(currentHost, session: session), !backupRestoreConfirmation.isEmpty,
              !busy, !retryNeeded, !backupImportBusy, !backupDocumentPending else { return }
        cancelBackupRestore()
        beginBackupDocumentOperation(currentHost, mode: "restore")
        defer { finishOperation() }
        do { try await acceptBackupDocumentReply(await currentHost.restoreBackupSnapshot(reference), from: currentHost) }
        catch { handleBackupDocumentFailure(error, from: currentHost) }
    }

    func dismissBackupDocumentResult() {
        backupDocumentResult = [:]
        backupDocumentReply = nil
        backupUndoSnapshotName = nil
    }

    func retryBackupTransferRead() async {
        if backupDocumentPending { await retry(); return }
        guard ready, settingsDataPresented, !busy, !retryNeeded, !appLock.concealed else { return }
        busy = true
        backupImportError = nil
        defer { finishOperation() }
        do {
            try await readLanguage()
            try await readTheme()
            try await readAppLock()
            try await readDataSettings()
        } catch { backupImportError = backupTransferFailure(mode: backupDocumentMode) }
    }

    private func backupSessionIsCurrent(_ currentHost: CoreHost, session: UUID) -> Bool {
        host === currentHost && selectedSurface == .settings && settingsDataPresented
            && diagnosticsCurrent(owner: settingsDiagnosticsOwner, session: session)
    }

    private func backupTransferFailure(mode: String = "merge") -> String {
        let localized = mode == "restore" ? label("settings.backupMobile.failedToRestoreBackup")
            : mode == "replace" ? label("settings.backupMobile.restoreFailed")
            : ["csv", "todoist", "ticktick", "dgt", "omnifocus"].contains(mode) ? label("settings.backupMobile.importFailed") : dataSettings.object("backup").text("mergeFailed")
        return localized.isEmpty ? label("settings.feedback.actionFailed") : localized
    }

    private func backupControlledFailure(_ failure: Error, mode: String = "merge") -> String {
        let reason: String
        switch failure.localizedDescription {
        case "Backup exceeds the supported byte limit", "INVALID_INPUT: Import source exceeds supported limit":
            reason = ["csv", "todoist", "ticktick", "dgt", "omnifocus"].contains(mode) ? label("settings.importDiagnostics.limitExceeded") : "Backup source exceeds 128 MiB"
        case "INVALID_INPUT: CSV source exceeds 16 MiB", "INVALID_INPUT: Todoist source exceeds 16 MiB", "INVALID_INPUT: Todoist import result exceeds 64 KiB",
             "INVALID_INPUT: TickTick source exceeds 16 MiB", "INVALID_INPUT: TickTick import result exceeds 64 KiB",
             "INVALID_INPUT: DGT source exceeds 16 MiB", "INVALID_INPUT: DGT import result exceeds 64 KiB",
             "INVALID_INPUT: OmniFocus source exceeds 16 MiB", "INVALID_INPUT: OmniFocus import result exceeds 64 KiB":
            reason = label("settings.importDiagnostics.limitExceeded")
        case "INVALID_INPUT: CSV import result exceeds 64 KiB":
            reason = "CSV import result exceeds 64 KiB"
        case "INVALID_INPUT: Backup source exceeds 128 MiB":
            reason = "Backup source exceeds 128 MiB"
        case "INVALID_INPUT: Recovery snapshot exceeds 128 MiB":
            reason = "Recovery snapshot exceeds 128 MiB"
        case "INVALID_INPUT: Prepared backup plan exceeds 512 MiB":
            reason = "Prepared backup plan exceeds 512 MiB"
        default:
            return backupTransferFailure(mode: mode)
        }
        // Only fixed, owned capacity reasons cross the presentation boundary.
        return backupTransferFailure(mode: mode) + "\n" + reason
    }

    private func beginBackupDocumentOperation(_ currentHost: CoreHost, mode: String) {
        backupDocumentHost = currentHost
        backupDocumentMode = mode
        backupDocumentPending = true
        backupDocumentReply = nil
        backupDocumentResult = [:]
        backupUndoSnapshotName = nil
        backupImportError = nil
        backupImportBusy = true
        busy = true
    }

    private func handleBackupDocumentFailure(_ failure: Error, from currentHost: CoreHost) {
        guard host === currentHost, backupDocumentHost === currentHost else { return }
        backupImportBusy = false
        if isDefiniteRejection(failure) { backupDocumentPending = false; retryNeeded = false }
        else { retryNeeded = backupDocumentPending }
        let message = backupControlledFailure(failure, mode: backupDocumentMode)
        backupImportError = message
        self.error = retryNeeded ? message : nil
    }

    private func validBackupInteger(_ value: Any?, maximum: Double = 9_007_199_254_740_991) -> Bool {
        guard let number = value as? NSNumber, CFGetTypeID(number) != CFBooleanGetTypeID() else { return false }
        let count = number.doubleValue
        return count.isFinite && count >= 0 && count <= maximum && count.rounded() == count
    }

    private func acceptBackupDocumentReply(_ encoded: String, from currentHost: CoreHost) async throws {
        let reply = try decode(encoded)
        guard validBackupInteger(reply["version"], maximum: 1), reply.number("version") == 1,
              !reply.text("snapshotName").isEmpty else { throw CocoaError(.coderReadCorrupt) }
        if ["csv", "todoist", "ticktick", "dgt", "omnifocus"].contains(reply.text("operation")) {
            let result = reply.object("result")
            let counts: [String]
            switch reply.text("operation") {
            case "todoist":
                counts = ["importedChecklistItemCount", "importedProjectCount", "importedSectionCount", "importedTaskCount"]
            case "ticktick", "dgt":
                counts = ["importedAreaCount", "importedChecklistItemCount", "importedProjectCount", "importedSectionCount", "importedTaskCount"]
            default:
                counts = ["importedAreaCount", "importedChecklistItemCount", "importedProjectCount", "importedSectionCount", "importedStandaloneTaskCount", "importedTaskCount"]
            }
            // Core bounds the canonical reply before journaling. Foundation can
            // expand its transport representation by escaping slashes, so do
            // not reapply that byte bound after native reserialization.
            guard Set(reply.keys) == Set(["version", "operation", "snapshotName", "result"]),
                  Set(result.keys) == Set(counts + ["warnings"]),
                  counts.allSatisfy({ validBackupInteger(result[$0]) }), result["warnings"] is [String] else {
                throw CocoaError(.coderReadCorrupt)
            }
        } else {
            guard Set(reply.keys) == Set(["version", "operation", "snapshotName", "added", "updated"]),
                  ["merge", "restore", "replace"].contains(reply.text("operation")),
                  validBackupInteger(reply["added"]), validBackupInteger(reply["updated"]) else { throw CocoaError(.coderReadCorrupt) }
            if ["restore", "replace"].contains(reply.text("operation")) {
                guard reply.number("added") == 0, reply.number("updated") == 0 else { throw CocoaError(.coderReadCorrupt) }
            }
        }
        guard host === currentHost else { return }
        guard !backupDocumentPending || backupDocumentHost !== currentHost || reply.text("operation") == backupDocumentMode else {
            throw CocoaError(.coderReadCorrupt)
        }
        backupDocumentHost = currentHost
        backupDocumentReply = encoded
        backupDocumentMode = reply.text("operation")
        backupUndoSnapshotName = ["merge", "csv", "replace", "todoist", "ticktick", "dgt", "omnifocus"].contains(reply.text("operation")) ? reply.text("snapshotName") : nil
        backupDocumentPending = false
        backupImportBusy = false
        backupImportError = nil
        retryNeeded = false
        error = nil
        // The host already proved the document and canonical reload. A failure
        // of presentation reads retains this reply and retries only those reads.
        guard settingsDataPresented, !appLock.concealed else { return }
        do {
            try await readLanguage()
            try await readTheme()
            try await readAppLock()
            try await readSettingsMenu()
            try await readDataSettings()
        } catch { backupImportError = backupTransferFailure(mode: backupDocumentMode) }
    }

    private func readBackupTransferModels(_ currentHost: CoreHost, session: UUID) async {
        guard host === currentHost, settingsDataPresented, !appLock.concealed else { return }
        do {
            let encoded = try await currentHost.listBackupSnapshots()
            guard let references = try NativeJSON.jsonObject(with: Data(encoded.utf8)) as? [CoreObject] else {
                throw CocoaError(.coderReadCorrupt)
            }
            var rows: [BackupSnapshotRow] = []
            var ids = Set<String>()
            var names = Set<String>()
            for reference in references {
                let id = reference.text("id"), name = reference.text("name"), digest = reference.text("sha256")
                guard Set(reference.keys) == Set(["id", "name", "sha256", "byteCount"]),
                      UUID(uuidString: id)?.uuidString.lowercased() == id, !name.isEmpty,
                      ids.insert(id).inserted, names.insert(name).inserted,
                      digest.utf8.count == 64, digest.utf8.allSatisfy({ (48...57).contains($0) || (97...102).contains($0) }),
                      validBackupInteger(reference["byteCount"], maximum: 134_217_728), reference.number("byteCount") > 0 else {
                    throw CocoaError(.coderReadCorrupt)
                }
                rows.append(BackupSnapshotRow(id: id, name: name, referenceJSON: try json(reference)))
            }
            guard backupSessionIsCurrent(currentHost, session: session) else { return }
            backupSnapshots = rows
            backupSnapshotReadError = nil
        } catch {
            if backupSessionIsCurrent(currentHost, session: session) {
                backupSnapshots = []
                backupSnapshotReadError = label("settings.feedback.actionFailed")
            }
        }
        guard backupSessionIsCurrent(currentHost, session: session), backupDocumentHost === currentHost,
              let reply = backupDocumentReply else { return }
        do {
            let model = try decode(await currentHost.backupDocumentResultModel(reply))
            guard Set(model.keys) == Set(["title", "message", "undoLabel", "doneLabel"]), model.values.allSatisfy({ $0 is String }),
                  ["title", "message", "doneLabel"].allSatisfy({ !model.text($0).isEmpty }) else { throw CocoaError(.coderReadCorrupt) }
            guard backupSessionIsCurrent(currentHost, session: session), backupDocumentReply == reply else { return }
            backupDocumentResult = model
            backupImportError = nil
        } catch {
            if backupSessionIsCurrent(currentHost, session: session) { backupImportError = backupTransferFailure(mode: backupDocumentMode) }
        }
    }

    func openDataSettings() async {
        guard ready, selectedSurface == .settings, !busy, !retryNeeded, !appLock.concealed,
              !settingsAboutPresented, !settingsManagePresented, !settingsCalendarPresented, !calendarSettingActive, !settingsNotificationsPresented, !settingsGeneralPresented, !settingsGtdPresented else { return }
        settingsSearchTask?.cancel()
        settingsSearchGeneration += 1
        settingsDataPresented = true
        diagnosticsReadError = nil
        beginDiagnostics(owner: settingsDiagnosticsOwner)
        busy = true
        defer { finishOperation() }
        do { try await readDataSettings() }
        catch { diagnosticsReadError = error.localizedDescription }
    }

    private func readDataSettings() async throws {
        guard let currentHost = host, let session = diagnosticsSession, !appLock.concealed else { throw CocoaError(.coderInvalidValue) }
        let result = try await query("menuRead", ["dataSettings", "{}"])
        let labels = result.object("diagnostics")
        let backup = result.object("backup")
        guard result["version"] is NSNumber, !result.text("revision").isEmpty, !result.text("title").isEmpty,
              ["title", "exportLabel", "description", "failed", "csvLabel", "csvDescription", "csvFailed", "tasknotesLabel", "tasknotesDescription", "tasknotesFailed", "mergeLabel", "mergeDescription", "mergeFailed", "restoreFileLabel", "restoreFileDescription", "csvImportLabel", "csvImportDescription", "todoistImportLabel", "todoistImportDescription", "ticktickImportLabel", "ticktickImportDescription", "dgtImportLabel", "dgtImportDescription", "omnifocusImportLabel", "omnifocusImportDescription", "snapshotsLabel", "restoreLabel"].allSatisfy({ backup[$0] is String && !backup.text($0).isEmpty }),
              !labels.text("title").isEmpty, labels.object("debugLogging")["value"] is Bool,
              ["toastTitle", "logMissing", "shareUnavailable", "logCleared", "logClearFailed"].allSatisfy({ labels[$0] is String }),
              labels["shareLog"] is NSNull || labels["shareLog"] is CoreObject,
              labels["clearLog"] is NSNull || labels["clearLog"] is CoreObject else { throw CocoaError(.coderReadCorrupt) }
        guard host === currentHost, !appLock.concealed, session == diagnosticsSession else { return }
        dataSettings = result
        diagnosticsCacheHost = ObjectIdentifier(currentHost)
        diagnosticsReadError = nil
        dataSettingAwaitingRefresh = false
        await readBackupTransferModels(currentHost, session: session)
    }

    func retryDataSettingsRead() async {
        if retryNeeded { await retry(); return }
        guard settingsDataPresented, !busy, !appLock.concealed else { return }
        busy = true
        defer { finishOperation() }
        do { try await readDataSettings() }
        catch { diagnosticsReadError = error.localizedDescription }
    }

    func setDiagnosticsDebugLogging(_ value: Bool) async {
        guard diagnosticsToggleEnabled else { return }
        busy = true
        defer { finishOperation() }
        do {
            let request = try json(["requestId": UUID().uuidString.lowercased(),
                                    "edit": ["type": "debugLogging", "value": value]])
            dataSettingRequest = request
            try acknowledgeDataSetting(await query("dataSetting", [request]))
        } catch { handleDataSettingError(error); return }
        if settingsDataPresented, diagnosticsSession != nil {
            do { try await readDataSettings() }
            catch { diagnosticsReadError = error.localizedDescription }
        }
    }

    private func acknowledgeDataSetting(_ result: CoreObject) throws {
        guard dataSettingRequest != nil, Set(result.keys) == Set(["changed", "deviceWrites"]),
              let changed = result["changed"] as? NSNumber, CFGetTypeID(changed) == CFBooleanGetTypeID(),
              let writes = result["deviceWrites"] as? [Any], writes.isEmpty else { throw CocoaError(.coderReadCorrupt) }
        dataSettingRequest = nil
        dataSettingAwaitingRefresh = true
        retryNeeded = false
        error = nil
    }

    private func handleDataSettingError(_ failure: Error) {
        diagnosticsReadError = failure.localizedDescription
        if isDefiniteRejection(failure) {
            dataSettingRequest = nil
            dataSettingAwaitingRefresh = true
            retryNeeded = false
        } else { retryNeeded = dataSettingRequest != nil }
        error = failure.localizedDescription
    }

    func shareDiagnostics(owner: UUID) async {
        guard diagnosticsFileActionsEnabled(owner: owner), let session = diagnosticsSession, let currentHost = host else { return }
        diagnosticsFileBusy = true
        diagnosticsMessage = nil
        defer { if diagnosticsCurrent(owner: owner, session: session) { diagnosticsFileBusy = false } }
        do {
            let reply = try decode(await currentHost.diagnosticsFileAction("logShare"))
            guard Set(reply.keys) == Set(["path"]), reply["path"] is NSNull || reply["path"] is String else { throw CocoaError(.coderReadCorrupt) }
            #if DEBUG && targetEnvironment(simulator)
            if diagnosticsShareTestHoldOnce {
                diagnosticsShareTestHoldOnce = false
                diagnosticsShareTestState = "held"
                let until = ProcessInfo.processInfo.systemUptime + 900
                // Keep the actual settled reply across close/reopen. The normal
                // host/library/concealment/session fence below still decides delivery.
                while (diagnosticsSession == nil || diagnosticsSession == session), host === currentHost,
                      !appLock.concealed, ProcessInfo.processInfo.systemUptime < until, !Task.isCancelled {
                    try await Task.sleep(nanoseconds: 20_000_000)
                }
                diagnosticsShareTestState += "\ndelivered"
            }
            #endif
            guard let path = reply["path"] as? String else {
                if diagnosticsCurrent(owner: owner, session: session) { diagnosticsMessage = diagnosticsLabels.text("logMissing") }
                return
            }
            let url = try await currentHost.validatedDiagnosticsShareURL(path)
            guard host === currentHost, diagnosticsCurrent(owner: owner, session: session) else {
                #if DEBUG && targetEnvironment(simulator)
                if diagnosticsShareTestState.contains("delivered") { diagnosticsShareTestState += "\ndiscarded" }
                #endif
                return
            }
            diagnosticsShare = DiagnosticsSharePayload(id: session, owner: owner, url: url)
        } catch {
            if host === currentHost, diagnosticsCurrent(owner: owner, session: session) {
                diagnosticsMessage = diagnosticsLabels.text("shareUnavailable")
            }
        }
    }

    func dismissDiagnosticsShare(owner: UUID) {
        guard diagnosticsShare?.owner == owner else { return }
        diagnosticsShare = nil
    }

    func clearDiagnostics(owner: UUID) async {
        guard diagnosticsFileActionsEnabled(owner: owner), let session = diagnosticsSession, let currentHost = host else { return }
        diagnosticsFileBusy = true
        diagnosticsMessage = nil
        defer { if diagnosticsCurrent(owner: owner, session: session) { diagnosticsFileBusy = false } }
        do {
            let reply = try decode(await currentHost.diagnosticsFileAction("logClearChecked"))
            guard Set(reply.keys) == Set(["outcome"]), ["cleared", "alreadyAbsent", "unavailable", "unconfirmed"].contains(reply.text("outcome")) else { throw CocoaError(.coderReadCorrupt) }
            guard host === currentHost, diagnosticsCurrent(owner: owner, session: session) else { return }
            diagnosticsMessage = diagnosticsLabels.text(["cleared", "alreadyAbsent"].contains(reply.text("outcome")) ? "logCleared" : "logClearFailed")
        } catch {
            if host === currentHost, diagnosticsCurrent(owner: owner, session: session) {
                diagnosticsMessage = diagnosticsLabels.text("logClearFailed")
            }
        }
    }

    private func settingsAboutCurrent(host capturedHost: CoreHost, session: UUID) -> Bool {
        host === capturedHost && settingsAboutSession == session && ready
            && selectedSurface == .settings && settingsAboutPresented
            && (!busy || settingsAboutBusySession == session) && !retryNeeded
            && !settingsSyncRestartRequired && !appLock.concealed
            && UIApplication.shared.applicationState == .active
    }

    var settingsAboutCanCancel: Bool { settingsAboutPresented && settingsAboutBusySession != nil }

    var settingsAboutLinksEnabled: Bool {
        guard let currentHost = host else { return false }
        return settingsAboutCurrent(host: currentHost, session: settingsAboutSession)
            && !settingsFeedbackPresented && settingsAboutTask == nil && !settingsAboutChecking && !settingsAboutOpening
    }

    var settingsAboutUpdateTitle: String {
        label(settingsAboutUpdate?.updateAvailable == true ? "settings.updateAvailable" : "settings.aboutMobile.upToDate")
    }

    var settingsAboutUpdateMessage: String {
        guard let notice = settingsAboutUpdate else { return "" }
        return notice.updateAvailable
            ? label("settings.aboutMobile.appStoreUpdateAvailableWithVersions")
                .replacingOccurrences(of: "{{currentVersion}}", with: notice.currentVersion)
                .replacingOccurrences(of: "{{latestVersion}}", with: notice.latestVersion)
            : label("settings.aboutMobile.youAreUsingTheLatestAppStoreVersion")
    }

    var settingsAboutUpdateCanOpen: Bool {
        guard settingsAboutLinksEnabled, let notice = settingsAboutUpdate,
              notice.updateAvailable, let listing = notice.listing else { return false }
        return Self.aboutAppleListing(listing) != nil
    }

    func openAboutSettings() {
        guard ready, selectedSurface == .settings, !busy, !retryNeeded, !settingsSyncRestartRequired,
              !settingsAboutPresented, !settingsManagePresented, !settingsCalendarPresented, !calendarSettingActive, !settingsNotificationsPresented, !settingsGeneralPresented,
              !settingsGtdPresented, !settingsDataPresented, !settingsSyncPresented, !appLock.concealed else { return }
        settingsSearchTask?.cancel()
        settingsSearchGeneration += 1
        invalidateAboutLinkOpening()
        settingsAboutPresented = true
        lookupAboutAppStore(automatic: true)
    }

    func closeAboutSettings() {
        guard settingsAboutPresented else { return }
        invalidateAboutLinkOpening(retireFeedback: true)
        settingsAboutPresented = false
        // A canceled owner must drain before menu reads can observe stored state.
        if settingsAboutTask != nil || busy { refreshRequested = true }
        else { setSettingsSearch(settingsSearch) }
    }

    func invalidateAboutLinkOpening(retireFeedback: Bool = false) {
        settingsAboutSession = UUID()
        settingsAboutTask?.cancel()
        // Keep the task until it drains so reopening cannot overlap an old lookup.
        settingsAboutChecking = false
        settingsAboutOpening = false
        settingsAboutError = nil
        settingsAboutUpdate = nil
        settingsFeedbackLoading = false
        settingsFeedbackSending = false
        if retireFeedback || !settingsAboutPresented || selectedSurface != .settings {
            settingsFeedbackPresented = false
            settingsFeedbackConfigured = nil
            clearFeedbackDraft()
        }
        if !settingsFeedbackPresented { settingsFeedbackSent = false; settingsFeedbackError = nil }
    }

    static let feedbackCategories = ["bug", "feature", "other"]
    static let feedbackLocations = ["inbox", "focus", "projects", "review", "settings", "sync", "importExport", "notifications", "other"]

    func feedbackCategoryLabel(_ value: String) -> String {
        label(["bug": "settings.feedbackCategoryBug", "feature": "settings.feedbackCategoryFeature", "other": "settings.feedbackCategoryOther"][value] ?? "settings.feedbackCategoryOther")
    }

    func feedbackLocationLabel(_ value: String) -> String {
        label(["inbox": "settings.feedbackWhereInbox", "focus": "settings.feedbackWhereFocus", "projects": "settings.feedbackWhereProjects",
               "review": "settings.feedbackWhereReview", "settings": "settings.feedbackWhereSettings", "sync": "settings.feedbackWhereSync",
               "importExport": "settings.feedbackWhereImportExport", "notifications": "settings.feedbackWhereNotifications", "other": "settings.feedbackWhereOther"][value] ?? "settings.feedbackWherePlaceholder")
    }

    var settingsFeedbackPlaceholder: String {
        label(["bug": "settings.feedbackMessagePlaceholderBug", "feature": "settings.feedbackMessagePlaceholderFeature", "other": "settings.feedbackMessagePlaceholderOther"][settingsFeedbackCategory] ?? "settings.feedbackMessagePlaceholder")
    }

    // Match JavaScript trim/\s rather than Foundation's broader whitespace set.
    private static let feedbackWhitespace = CharacterSet(charactersIn: "\u{0009}\u{000A}\u{000B}\u{000C}\u{000D} \u{00A0}\u{1680}\u{2000}\u{2001}\u{2002}\u{2003}\u{2004}\u{2005}\u{2006}\u{2007}\u{2008}\u{2009}\u{200A}\u{2028}\u{2029}\u{202F}\u{205F}\u{3000}\u{FEFF}")
    private var feedbackSubmittedMessage: String {
        let message = settingsFeedbackMessage.trimmingCharacters(in: Self.feedbackWhitespace)
        return settingsFeedbackCategory == "bug" && !settingsFeedbackLocation.isEmpty
            ? label("settings.feedbackWhereMessagePrefix") + ": " + feedbackLocationLabel(settingsFeedbackLocation) + "\n\n" + message : message
    }
    var settingsFeedbackMessageCount: Int { feedbackSubmittedMessage.utf16.count }
    var settingsFeedbackEmailValid: Bool {
        let email = settingsFeedbackEmail.trimmingCharacters(in: Self.feedbackWhitespace)
        if email.isEmpty { return true }
        let parts = email.components(separatedBy: "@")
        guard email.utf16.count <= 254, parts.count == 2, !parts[0].isEmpty,
              !email.unicodeScalars.contains(where: { Self.feedbackWhitespace.contains($0) }),
              !parts[1].isEmpty else { return false }
        let domain = Array(parts[1].unicodeScalars)
        return domain.enumerated().contains { index, scalar in
            scalar.value == 46 && index > 0 && index < domain.count - 1
        }
    }
    var settingsFeedbackEditable: Bool {
        guard let currentHost = host else { return false }
        return settingsAboutCurrent(host: currentHost, session: settingsAboutSession) && settingsFeedbackPresented
            && settingsAboutTask == nil && !settingsFeedbackSent
    }
    var settingsFeedbackCanSubmit: Bool {
        settingsFeedbackEditable && settingsFeedbackConfigured == true && settingsFeedbackEmailValid
            && !settingsFeedbackMessage.trimmingCharacters(in: Self.feedbackWhitespace).isEmpty && settingsFeedbackMessageCount <= 4_000
    }
    var settingsFeedbackVisibleError: String? {
        settingsFeedbackError ?? (!settingsFeedbackEmailValid ? label("settings.feedbackInvalidEmail") : nil)
    }

    private var feedbackEndpointURL: String {
        #if DEBUG && (targetEnvironment(simulator) || NATIVE_DEVICE_TEST)
        if settingsFeedbackTestUnavailable { return "" }
        #endif
        return (Bundle.main.object(forInfoDictionaryKey: "MindwtrFeedbackEndpointURL") as? String ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
    }

    func openFeedbackSettings() {
        guard settingsAboutLinksEnabled else { return }
        settingsAboutError = nil
        settingsAboutUpdate = nil
        settingsFeedbackPresented = true
        settingsFeedbackConfigured = nil
        settingsFeedbackError = nil
        settingsFeedbackSent = false
        loadFeedbackConfiguration()
    }

    func closeFeedbackSettings() {
        guard settingsFeedbackPresented else { return }
        // Canceling an in-flight POST cannot undo a request already received.
        settingsFeedbackPresented = false
        invalidateAboutLinkOpening()
        settingsFeedbackConfigured = nil
    }

    private func clearFeedbackDraft(resetCategory: Bool = true) {
        if resetCategory { settingsFeedbackCategory = "bug" }
        settingsFeedbackLocation = ""
        settingsFeedbackMessage = ""
        settingsFeedbackEmail = ""
        settingsFeedbackIncludeDiagnostics = false
    }

    func setFeedbackCategory(_ value: String) {
        guard settingsFeedbackEditable, Self.feedbackCategories.contains(value) else { return }
        settingsFeedbackCategory = value
        if value != "bug" { settingsFeedbackLocation = ""; settingsFeedbackIncludeDiagnostics = false }
        settingsFeedbackError = nil
    }
    func setFeedbackLocation(_ value: String) {
        guard settingsFeedbackEditable, settingsFeedbackCategory == "bug", Self.feedbackLocations.contains(value) else { return }
        settingsFeedbackLocation = settingsFeedbackLocation == value ? "" : value
        settingsFeedbackError = nil
    }
    func setFeedbackMessage(_ value: String) {
        guard settingsFeedbackEditable else { return }
        var bounded = "", count = 0
        for character in value {
            let size = String(character).utf16.count
            if count + size > 4_000 { break }
            bounded.append(character); count += size
        }
        settingsFeedbackMessage = bounded
        settingsFeedbackError = nil
    }
    func setFeedbackEmail(_ value: String) {
        guard settingsFeedbackEditable else { return }
        settingsFeedbackEmail = value
        settingsFeedbackError = nil
    }
    func setFeedbackIncludeDiagnostics(_ value: Bool) {
        guard settingsFeedbackEditable, settingsFeedbackCategory == "bug" else { return }
        settingsFeedbackIncludeDiagnostics = value
    }

    @discardableResult private func resumeFeedbackConfigurationIfNeeded() -> Bool {
        guard settingsFeedbackPresented, settingsFeedbackConfigured == nil, settingsFeedbackError == nil,
              settingsFeedbackEditable else { return false }
        loadFeedbackConfiguration()
        return settingsFeedbackLoading
    }

    func loadFeedbackConfiguration() {
        guard settingsFeedbackEditable, let currentHost = host else { return }
        let session = settingsAboutSession, endpoint = feedbackEndpointURL
        settingsFeedbackLoading = true
        settingsFeedbackError = nil
        settingsAboutBusySession = session
        busy = true
        settingsAboutTask = Task {
            defer { finishFeedbackOperation(session: session) }
            do {
                guard settingsAboutCurrent(host: currentHost, session: session), settingsFeedbackPresented, !Task.isCancelled else { return }
                let result = try decode(await currentHost.feedbackConfiguration(endpointURL: endpoint))
                guard settingsAboutCurrent(host: currentHost, session: session), settingsFeedbackPresented, !Task.isCancelled else { return }
                guard Set(result.keys) == Set(["configured", "categories"]),
                      let configured = result["configured"] as? NSNumber, CFGetTypeID(configured) == CFBooleanGetTypeID(),
                      let categories = result["categories"] as? [String], categories == Self.feedbackCategories else { throw CocoaError(.coderReadCorrupt) }
                settingsFeedbackConfigured = configured.boolValue
            } catch {
                guard settingsAboutCurrent(host: currentHost, session: session), settingsFeedbackPresented, !Task.isCancelled else { return }
                settingsFeedbackError = label("settings.feedback.actionFailed")
            }
        }
    }

    private func finishFeedbackOperation(session: UUID) {
        settingsAboutTask = nil
        if settingsAboutSession == session { settingsFeedbackLoading = false; settingsFeedbackSending = false }
        if settingsAboutBusySession == session { settingsAboutBusySession = nil; finishOperation() }
    }

    func submitFeedbackSettings() {
        guard settingsFeedbackCanSubmit, let currentHost = host else { return }
        let session = settingsAboutSession, endpoint = feedbackEndpointURL
        var input: CoreObject = ["category": settingsFeedbackCategory, "message": feedbackSubmittedMessage,
                                 "includeDiagnostics": settingsFeedbackCategory == "bug" && settingsFeedbackIncludeDiagnostics]
        let email = settingsFeedbackEmail.trimmingCharacters(in: Self.feedbackWhitespace)
        if !email.isEmpty { input["email"] = email }
        guard let request = try? json(input) else { settingsFeedbackError = label("settings.feedbackFailed"); return }
        settingsFeedbackSending = true
        settingsFeedbackError = nil
        settingsAboutBusySession = session
        busy = true
        settingsAboutTask = Task {
            defer { finishFeedbackOperation(session: session) }
            do {
                guard settingsAboutCurrent(host: currentHost, session: session), settingsFeedbackPresented, !Task.isCancelled else { return }
                let result = try decode(await currentHost.submitFeedback(requestJSON: request, endpointURL: endpoint))
                guard settingsAboutCurrent(host: currentHost, session: session), settingsFeedbackPresented, !Task.isCancelled else { return }
                guard Set(result.keys) == Set(["status"]), result["status"] as? String == "sent" else { throw CocoaError(.coderReadCorrupt) }
                clearFeedbackDraft(resetCategory: false)
                settingsFeedbackSent = true
            } catch {
                guard settingsAboutCurrent(host: currentHost, session: session), settingsFeedbackPresented, !Task.isCancelled else { return }
                switch (error as? CoreHostRejection)?.message ?? error.localizedDescription {
                case "message_required": settingsFeedbackError = label("settings.feedbackRequired")
                case "invalid_email": settingsFeedbackError = label("settings.feedbackInvalidEmail")
                case "feedback_not_configured": settingsFeedbackConfigured = false
                default: settingsFeedbackError = label("settings.feedbackFailed")
                }
            }
        }
    }

