    private func fetchSomedayMovePage(offset: Int, revision: String? = nil) async throws -> CoreObject {
        var input: CoreObject = ["taskId": somedayMoveTaskID, "offset": offset, "limit": 25]
        if let revision { input["revision"] = revision }
        let page = try await query("somedaySectionMoveOptions", [try json(input)])
        let choices = page.object("choices")
        let items = choices.objects("items")
        guard Set(page.keys) == Set(["revision", "taskId", "taskRevision", "title", "choices", "cancelLabel",
                                    "undoLabel", "errorTitle", "moveFailed", "undoFailed"]),
              !page.text("revision").isEmpty, page.text("taskId") == somedayMoveTaskID,
              !page.text("taskRevision").isEmpty, !page.text("title").isEmpty,
              !page.text("cancelLabel").isEmpty, !page.text("undoLabel").isEmpty,
              !page.text("errorTitle").isEmpty, !page.text("moveFailed").isEmpty,
              !page.text("undoFailed").isEmpty, Set(choices.keys) == Set(["total", "items"]),
              choices.number("total") > 0, choices.number("total") >= offset,
              items.count == min(25, choices.number("total") - offset),
              items.allSatisfy({ item in
                  Set(item.keys) == Set(["sectionId", "title", "selected", "toast"])
                      && (item["sectionId"] is NSNull || item["sectionId"] is String)
                      && !item.text("title").isEmpty && !item.text("toast").isEmpty
                      && item["selected"] is Bool
              }) else { throw CocoaError(.coderReadCorrupt) }
        return page
    }

    private func readSomedayMoveOptions() async {
        guard selectedSurface == .someday, somedayPanel == "moveSection", !busy, !retryNeeded,
              !somedayMovePending, somedayMoveCreatedSectionID == nil else { return }
        busy = true
        somedayMoveOptions = [:]
        somedayMoveReadError = nil
        defer { finishOperation() }
        do { somedayMoveOptions = try await fetchSomedayMovePage(offset: 0) }
        catch { somedayMoveReadError = error.localizedDescription }
    }

    private func appendedSomedayMovePage(_ options: CoreObject) async throws -> CoreObject {
        let choices = options.object("choices")
        let entries = choices.objects("items")
        guard entries.count < choices.number("total") else { throw CocoaError(.coderReadCorrupt) }
        let page = try await fetchSomedayMovePage(offset: entries.count, revision: options.text("revision"))
        guard page.text("revision") == options.text("revision"),
              page.text("taskRevision") == options.text("taskRevision"),
              page.object("choices").number("total") == choices.number("total"),
              page.text("title") == options.text("title"),
              page.text("cancelLabel") == options.text("cancelLabel"),
              page.text("undoLabel") == options.text("undoLabel"),
              page.text("errorTitle") == options.text("errorTitle"),
              page.text("moveFailed") == options.text("moveFailed"),
              page.text("undoFailed") == options.text("undoFailed") else {
            throw CocoaError(.coderReadCorrupt)
        }
        var merged = options
        var mergedChoices = choices
        mergedChoices["items"] = entries + page.object("choices").objects("items")
        merged["choices"] = mergedChoices
        return merged
    }

    func loadMoreSomedayMoveChoices() async {
        guard somedayMoveActionsEnabled, !busy else { return }
        let choices = somedayMoveOptions.object("choices")
        let entries = choices.objects("items")
        guard entries.count < choices.number("total") else { return }
        busy = true
        defer { finishOperation() }
        do {
            somedayMoveOptions = try await appendedSomedayMovePage(somedayMoveOptions)
        } catch {
            somedayMoveOptions = [:]
            somedayMoveReadError = error.localizedDescription
        }
    }

    private func resumeSomedayMoveAfterCreate() async {
        guard selectedSurface == .someday, somedayPanel == "moveSection",
              let createdID = somedayMoveCreatedSectionID, busy, !somedayMovePending else { return }
        somedayMoveOptions = [:]
        somedayMoveReadError = nil
        do {
            var options = try await fetchSomedayMovePage(offset: 0)
            while true {
                if let choice = options.object("choices").objects("items").first(where: { $0.text("sectionId") == createdID }) {
                    somedayMoveOptions = options
                    somedayMoveCreatedSectionID = nil
                    await writeSomedayMove(sectionID: createdID, toast: choice.text("toast"),
                                          taskRevision: options.text("taskRevision"))
                    return
                }
                options = try await appendedSomedayMovePage(options)
            }
        } catch {
            somedayMoveReadError = error.localizedDescription
        }
    }

    func chooseSomedayMoveSection(_ index: Int) async {
        guard somedayMoveActionsEnabled else { return }
        let entries = somedayMoveOptions.object("choices").objects("items")
        guard entries.indices.contains(index), let sectionID = entries[index]["sectionId"],
              sectionID is NSNull || sectionID is String else { return }
        busy = true
        defer { finishOperation() }
        await writeSomedayMove(sectionID: sectionID, toast: entries[index].text("toast"),
                              taskRevision: somedayMoveOptions.text("taskRevision"))
    }

    private func writeSomedayMove(sectionID: Any, toast: String, taskRevision: String) async {
        somedayMoveChoiceSectionID = sectionID
        somedayMoveChoiceToast = toast
        let requestID = UUID().uuidString.lowercased()
        do {
            let request = try json(["requestId": requestID, "taskId": somedayMoveTaskID,
                                    "taskRevision": taskRevision,
                                    "sectionId": sectionID])
            somedayMoveRequest = request
            somedayMoveRequestID = requestID
            somedayMoveError = nil
            do {
                let result = try await query("somedaySectionMoveWrite", [request])
                try acknowledgeSomedayMove(result)
                await refreshSomedayAfterMove()
            } catch { await handleSomedayMoveError(error) }
        } catch { somedayMoveError = error.localizedDescription }
    }

    private func acknowledgeSomedayMove(_ result: CoreObject) throws {
        let actualSection = try json(["sectionId": result["sectionId"] ?? "missing"])
        let requestedSection = try json(["sectionId": somedayMoveChoiceSectionID])
        guard somedayMoveRequest != nil, let requestID = somedayMoveRequestID,
              Set(result.keys) == Set(["id", "changed", "sectionId"]),
              result.text("id") == somedayMoveTaskID,
              let changed = result["changed"] as? NSNumber,
              CFGetTypeID(changed) == CFBooleanGetTypeID(),
              actualSection == requestedSection else {
            throw CocoaError(.coderReadCorrupt)
        }
        somedayMoveRequest = nil
        somedayMoveRequestID = nil
        somedayMoveAcknowledgedID = requestID
        somedayMoveAcknowledgedChanged = changed.boolValue
        somedayMoveError = nil
        somedayMoveReadError = nil
        somedayMoveAwaitingRefresh = true
        retryNeeded = false
        error = nil
    }

    private func refreshSomedayAfterMove() async {
        guard selectedSurface == .someday, somedayMoveAwaitingRefresh else { return }
        if await readSomeday() {
            let undoLabel = somedayMoveOptions.text("undoLabel")
            let undoFailed = somedayMoveOptions.text("undoFailed")
            somedayMoveAwaitingRefresh = false
            somedayPanel = ""
            somedayMoveOptions = [:]
            somedayMoveReadError = nil
            somedayMoveError = nil
            if somedayMoveAcknowledgedChanged, let requestID = somedayMoveAcknowledgedID {
                showSomedayMoveNotice(requestID: requestID, taskID: somedayMoveTaskID,
                                      message: somedayMoveChoiceToast,
                                      undoLabel: undoLabel, undoFailed: undoFailed)
            }
            somedayMoveAcknowledgedID = nil
            somedayMoveAcknowledgedChanged = false
            somedayMoveTaskID = ""
            somedayMoveChoiceSectionID = NSNull()
            somedayMoveChoiceToast = ""
        } else {
            somedayMoveReadError = somedayError ?? label("settings.feedback.actionFailed")
        }
    }

    private func handleSomedayMoveError(_ failure: Error) async {
        if somedayMoveRequest != nil && isDefiniteRejection(failure) {
            somedayMoveRequest = nil
            somedayMoveRequestID = nil
            somedayMoveOptions = [:]
            retryNeeded = false
            error = nil
            somedayMoveError = failure.localizedDescription
            do { somedayMoveOptions = try await fetchSomedayMovePage(offset: 0) }
            catch { somedayMoveReadError = error.localizedDescription }
        } else {
            retryNeeded = somedayMoveRequest != nil
            somedayMoveError = failure.localizedDescription
            if retryNeeded { error = failure.localizedDescription }
        }
    }

    func retrySomedayMove() async {
        if retryNeeded { await retry(); return }
        guard selectedSurface == .someday, somedayPanel == "moveSection", !busy,
              !somedayMovePending else { return }
        if somedayMoveCreatedSectionID != nil {
            busy = true
            defer { finishOperation() }
            await resumeSomedayMoveAfterCreate()
        } else if somedayMoveAwaitingRefresh {
            busy = true
            defer { finishOperation() }
            await refreshSomedayAfterMove()
        } else {
            somedayMoveError = nil
            await readSomedayMoveOptions()
        }
    }

    private func showSomedayMoveNotice(requestID: String, taskID: String, message: String,
                                       undoLabel: String, undoFailed: String) {
        clearSomedayMoveNotice()
        somedayMoveUndoFailureLabel = undoFailed
        somedayMoveNotice = ["requestId": requestID, "taskId": taskID, "message": message,
                             "undoLabel": undoLabel]
        somedayMoveNoticeExpiry = Task {
            do { try await Task.sleep(nanoseconds: 5_200_000_000) } catch { return }
            if somedayMoveNotice.text("requestId") == requestID && somedayMoveUndoRequest == nil {
                somedayMoveNotice = [:]
                somedayMoveNoticeExpiry = nil
            }
        }
    }

    private func clearSomedayMoveNotice() {
        somedayMoveNoticeExpiry?.cancel()
        somedayMoveNoticeExpiry = nil
        somedayMoveNotice = [:]
    }

    func undoSomedaySectionMove() async {
        guard somedayMoveUndoEnabled, !busy,
              let moveRequestID = somedayMoveNotice["requestId"] as? String,
              let taskID = somedayMoveNotice["taskId"] as? String else { return }
        somedayMoveNoticeExpiry?.cancel()
        somedayMoveNoticeExpiry = nil
        let requestID = UUID().uuidString.lowercased()
        do {
            let request = try json(["requestId": requestID, "moveRequestId": moveRequestID])
            somedayMoveUndoRequest = request
            somedayMoveUndoRequestID = requestID
            somedayMoveUndoTaskID = taskID
            somedayMoveUndoError = nil
            busy = true
            defer { finishOperation() }
            do {
                let result = try await query("somedaySectionMoveUndo", [request])
                try acknowledgeSomedayMoveUndo(result)
                await refreshSomedayAfterUndo()
            } catch { handleSomedayMoveUndoError(error) }
        } catch { somedayMoveUndoError = error.localizedDescription }
    }

    private func acknowledgeSomedayMoveUndo(_ result: CoreObject) throws {
        guard somedayMoveUndoRequest != nil, somedayMoveUndoRequestID != nil,
              Set(result.keys) == Set(["id", "changed", "sectionId"]),
              result.text("id") == somedayMoveUndoTaskID,
              let changed = result["changed"] as? NSNumber,
              CFGetTypeID(changed) == CFBooleanGetTypeID(),
              result["sectionId"] is NSNull || result["sectionId"] is String else {
            throw CocoaError(.coderReadCorrupt)
        }
        somedayMoveUndoRequest = nil
        somedayMoveUndoRequestID = nil
        somedayMoveUndoError = nil
        somedayMoveUndoAwaitingRefresh = true
        retryNeeded = false
        error = nil
    }

    private func refreshSomedayAfterUndo() async {
        guard selectedSurface == .someday, somedayMoveUndoAwaitingRefresh else { return }
        if await readSomeday() {
            somedayMoveUndoAwaitingRefresh = false
            somedayMoveUndoTaskID = ""
            somedayMoveUndoError = nil
            clearSomedayMoveNotice()
        } else {
            somedayMoveUndoError = somedayError ?? label("settings.feedback.actionFailed")
        }
    }

    private func handleSomedayMoveUndoError(_ failure: Error) {
        if somedayMoveUndoRequest != nil && isDefiniteRejection(failure) {
            somedayMoveUndoRequest = nil
            somedayMoveUndoRequestID = nil
            somedayMoveUndoTaskID = ""
            retryNeeded = false
            error = nil
            clearSomedayMoveNotice()
        } else {
            retryNeeded = somedayMoveUndoRequest != nil
            if retryNeeded { error = failure.localizedDescription }
        }
        somedayMoveUndoError = failure.localizedDescription
    }

    func retrySomedayMoveUndo() async {
        if retryNeeded { await retry(); return }
        guard selectedSurface == .someday, !busy, somedayMoveUndoAwaitingRefresh else { return }
        busy = true
        defer { finishOperation() }
        await refreshSomedayAfterUndo()
    }

    func dismissSomedayMoveUndoError() {
        guard !busy, !retryNeeded, !somedayMovePending, !somedayMoveUndoAwaitingRefresh else { return }
        somedayMoveUndoError = nil
        somedayMoveUndoFailureLabel = ""
    }

    func setSomedayOption(_ key: String, value: Any) async {
        guard somedayActionsEnabled, ["sortBy", "groupBy", "showDetails"].contains(key) else { return }
        somedayParams[key] = value
        if key != "showDetails" { somedayLoadedDepth = pageSize }
        busy = true
        defer { finishOperation() }
        await readSomeday()
    }

    func editSomedayFilter(_ edit: CoreObject) async {
        guard somedayActionsEnabled, !edit.isEmpty else { return }
        somedayPendingEdit = edit
        somedayLoadedDepth = pageSize
        busy = true
        defer { finishOperation() }
        await readSomeday()
    }

    func setSomedayText(_ text: String, location: Bool = false) {
        guard selectedSurface == .someday, !retryNeeded, !taskPresented else { return }
        guard text != (location ? somedayLocationText : somedaySearchText) else { return }
        if location { somedayLocationText = text } else { somedaySearchText = text }
        let type = location ? "setLocation" : "setSearch"
        somedayTextEdits[type] = ["type": type, "value": text]
        if somedayPendingEdit?.text("type") == type { somedayPendingEdit = somedayTextEdits[type] }
        somedayTextNeedsRead = true
        somedayCurrent = false
        somedayError = nil
        somedayLoadedDepth = pageSize
        scheduleSomedayRead()
    }

    func retrySomeday() async {
        guard selectedSurface == .someday, !busy, !retryNeeded, !taskPresented else { return }
        if !somedayTextEdits.isEmpty {
            somedayTextNeedsRead = true
            scheduleSomedayRead(delay: 0)
        } else { await refresh() }
    }

    private func scheduleSomedayRead(delay: UInt64 = 200_000_000) {
        guard selectedSurface == .someday, !busy, !retryNeeded, !taskPresented else { return }
        somedayReadTask?.cancel()
        somedayReadTask = Task {
            do { try await Task.sleep(nanoseconds: delay) } catch { return }
            guard !Task.isCancelled, selectedSurface == .someday, !busy, !retryNeeded, !taskPresented else { return }
            busy = true
            defer { finishOperation() }
            somedayTextNeedsRead = false
            // Text remains editable during reads. Drain the latest value of each
            // text field in order, always starting from core's effective state.
            if somedayPendingEdit != nil || somedayError != nil {
                guard await readSomeday() else {
                    somedayTextNeedsRead = false
                    somedayPickerNeedsRead = false
                    return
                }
            }
            while let type = somedayTextEdits.keys.sorted().first, let edit = somedayTextEdits[type] {
                somedayPendingEdit = edit
                guard await readSomeday() else { somedayTextNeedsRead = false; return }
                if somedayTextEdits[type]?.text("value") == edit.text("value") { somedayTextEdits.removeValue(forKey: type) }
            }
            somedayTextNeedsRead = false
            if !someday.isEmpty {
                syncSomedayText()
                somedayCurrent = true
            }
            if somedayPickerNeedsRead { await readSomedayPicker() }
        }
    }

    private func syncSomedayText() {
        let state = someday.object("filters").object("state")
        if somedayTextEdits["setSearch"] == nil { somedaySearchText = state.text("searchQuery") }
        if somedayTextEdits["setLocation"] == nil { somedayLocationText = state.text("location") }
    }

    private func effectiveSomedayParams(_ snapshot: CoreObject) -> CoreObject {
        ["sortBy": snapshot.text("sortBy"), "groupBy": snapshot.text("groupBy"),
         "showDetails": snapshot.flag("showDetails"), "filters": snapshot.object("filters").object("state")]
    }

    private func somedayPage(params: CoreObject, offset: Int, limit: Int, revision: String? = nil,
                             edit: CoreObject? = nil) async throws -> CoreObject {
        var input = params
        input["offset"] = offset
        input["limit"] = limit
        if let revision { input["revision"] = revision }
        if let edit { input["filterEdit"] = edit }
        return try await query("menuRead", ["someday", try json(input)])
    }

    @discardableResult private func readSomeday() async -> Bool {
        somedayCurrent = false
        somedayPickerCurrent = false
        somedayError = nil
        for attempt in 0..<2 {
            do {
                var next = try await somedayPage(params: somedayParams, offset: 0, limit: pageSize, edit: somedayPendingEdit)
                guard !next.text("revision").isEmpty, next.number("total") >= 0,
                      next.objects("items").count == min(pageSize, next.number("total")) else { throw CocoaError(.coderReadCorrupt) }
                let params = effectiveSomedayParams(next)
                var items = next.objects("items")
                let target = min(somedayLoadedDepth, next.number("total"))
                while items.count < target {
                    let limit = min(pageSize, target - items.count)
                    let page = try await somedayPage(params: params, offset: items.count, limit: limit, revision: next.text("revision"))
                    try validateSomedayPage(page, against: next, count: limit)
                    items += page.objects("items")
                }
                next["items"] = items
                for name in ["tokens", "projects", "sections", "deferredProjects"] {
                    let collection = somedayCollection(name, in: next)
                    guard collection.number("total") >= 0,
                          collection.objects("items").count == min(100, collection.number("total")) else {
                        throw CocoaError(.coderReadCorrupt)
                    }
                }
                var deferred = next.object("deferred")
                var collection = deferred.object("rows")
                var entries = collection.objects("items")
                let deferredTarget = min(somedayDeferredDepth, collection.number("total"))
                while entries.count < deferredTarget {
                    let limit = min(pageSize, deferredTarget - entries.count)
                    let page = try await somedayCollectionPage("deferredProjects", snapshot: next, offset: entries.count, limit: limit)
                    guard page.number("total") == collection.number("total"), page.objects("items").count == limit else {
                        throw CocoaError(.coderReadCorrupt)
                    }
                    entries += page.objects("items")
                }
                if !deferred.isEmpty {
                    collection["items"] = entries
                    deferred["rows"] = collection
                    next["deferred"] = deferred
                }
                somedayParams = params
                somedayPendingEdit = nil
                someday = next
                syncSomedayText()
                somedayCurrent = somedayTextEdits.isEmpty
                if !somedayPickerName.isEmpty { somedayPickerNeedsRead = true }
                return true
            } catch {
                if attempt == 1 { somedayError = error.localizedDescription }
            }
        }
        return false
    }

    private func validateSomedayPage(_ page: CoreObject, against snapshot: CoreObject, count: Int) throws {
        guard page.text("revision") == snapshot.text("revision"), page.number("total") == snapshot.number("total"),
              page.objects("items").count == count,
              try json(effectiveSomedayParams(page)) == json(effectiveSomedayParams(snapshot)) else {
            throw CocoaError(.coderReadCorrupt)
        }
    }

    func loadMoreSomeday(deferred: Bool = false) async {
        guard somedayActionsEnabled else { return }
        let collection = somedayCollection("deferredProjects", in: someday)
        let count = deferred ? collection.objects("items").count : someday.objects("items").count
        let total = deferred ? collection.number("total") : someday.number("total")
        guard count < total else { return }
        if deferred { somedayDeferredDepth = count + min(pageSize, total - count) }
        else { somedayLoadedDepth = count + min(pageSize, total - count) }
        busy = true
        defer { finishOperation() }
        // Stage all windows offscreen before publishing so headings and tasks,
        // including the deferred collection, always share one revision.
        await readSomeday()
    }

    private func somedayCollection(_ name: String, in snapshot: CoreObject) -> CoreObject {
        if name == "deferredProjects" { return snapshot.object("deferred").object("rows") }
        if name == "sections" { return snapshot.object("sections") }
        return snapshot.object("filters").object(name)
    }

    private func somedayCollectionPage(_ name: String, snapshot: CoreObject, query text: String? = nil,
                                       offset: Int, limit: Int) async throws -> CoreObject {
        var input: CoreObject = ["view": "someday", "collection": name, "params": effectiveSomedayParams(snapshot),
                                 "offset": offset, "limit": limit, "revision": snapshot.text("revision")]
        if let text { input["query"] = text }
        let page = try await query("menuRead", ["collection", try json(input)])
        guard page.text("view") == "someday", page.text("collection") == name,
              page.text("revision") == snapshot.text("revision"), page.number("total") >= offset,
              page.objects("items").count == min(limit, page.number("total") - offset) else {
            throw CocoaError(.coderReadCorrupt)
        }
        return page
    }

    func openSomedayPicker(_ name: String) {
        guard somedayActionsEnabled, ["tokens", "projects"].contains(name) else { return }
        somedayPickerName = name
        somedayPickerQuery = ""
        somedayPickerDepth = 100
        somedayPicker = somedayCollection(name, in: someday)
        somedayPickerCurrent = true
        somedayPickerError = nil
        somedayPickerNeedsRead = false
    }

    func closeSomedayPicker() {
        somedayPickerName = ""
        somedayPickerNeedsRead = false
        somedayPickerCurrent = false
        somedayPickerError = nil
    }

    func setSomedayPickerQuery(_ text: String) {
        guard !somedayPickerName.isEmpty, text != somedayPickerQuery, !retryNeeded else { return }
        somedayPickerQuery = text
        somedayPickerDepth = 100
        somedayPickerCurrent = false
        somedayPickerError = nil
        somedayPickerNeedsRead = true
        scheduleSomedayRead()
    }

    func loadMoreSomedayPicker() {
        guard somedayPickerActionsEnabled, somedayPicker.objects("items").count < somedayPicker.number("total") else { return }
        somedayPickerDepth = somedayPicker.objects("items").count + pageSize
        retrySomedayPicker()
    }

    func retrySomedayPicker() {
        guard !somedayPickerName.isEmpty, !busy, !retryNeeded else { return }
        somedayPickerCurrent = false
        somedayPickerNeedsRead = true
        scheduleSomedayRead(delay: 0)
    }

    private func readSomedayPicker() async {
        let name = somedayPickerName
        let text = somedayPickerQuery
        guard !name.isEmpty else { return }
        somedayPickerNeedsRead = false
        somedayPickerCurrent = false
        somedayPickerError = nil
        for attempt in 0..<2 {
            do {
                let snapshot = someday
                var next = try await somedayCollectionPage(name, snapshot: snapshot, query: text, offset: 0, limit: 100)
                var items = next.objects("items")
                let target = min(somedayPickerDepth, next.number("total"))
                while items.count < target {
                    let limit = min(pageSize, target - items.count)
                    let page = try await somedayCollectionPage(name, snapshot: snapshot, query: text, offset: items.count, limit: limit)
                    guard page.number("total") == next.number("total") else { throw CocoaError(.coderReadCorrupt) }
                    items += page.objects("items")
                }
                guard name == somedayPickerName, text == somedayPickerQuery else { return }
                next["items"] = items
                somedayPicker = next
                somedayPickerCurrent = true
                return
            } catch {
                guard name == somedayPickerName, text == somedayPickerQuery else { return }
                if attempt == 0, await readSomeday() {
                    guard name == somedayPickerName, text == somedayPickerQuery else { return }
                    somedayPickerNeedsRead = false
                    continue
                }
                somedayPickerNeedsRead = false
                somedayPickerError = error.localizedDescription
                return
            }
        }
    }

    func openReference() async {
        guard ready, !settingsPersonCreatePresented, !settingsPersonEditPresented && !settingsTaxonomyActive && !generalPreferenceActive, !settingsPersonDeleteActive, !busy, !retryNeeded, !capturePresented, !areaPickerPresented, !taskPresented else { return }
        if selectedSurface != .reference { referenceCaller = selectedSurface; clearReferenceTaskSelection() }
        morePresented = false
        selectedSurface = .reference
        await refresh()
    }

    func closeReference() async {
        guard selectedSurface == .reference, !busy, !retryNeeded, !taskPresented else { return }
        closeReferencePicker()
        clearReferenceTaskSelection()
        selectedSurface = referenceCaller
