    private func acceptDoneTaskBulk(_ bulk: CoreObject) throws {
        guard bulk.text("list") == "done", bulk["selectAll"] is NSNull,
              let ids = bulk["selectedIds"] as? [String], bulk.number("selectedCount") == ids.count,
