            && !processInboxPresented && processInboxRequest == nil && !processInboxTransitioning
            && !mindSweepPresented && mindSweepRequest == nil && mindSweepDraft.isEmpty
            && !morePresented && !areaPickerPresented && !areaManagerPresented && bulkConfirm.isEmpty
            && !taskPresented && taskOpeningIntent == nil && taskEditor.isEmpty && !taskSavePending
            && !taskRecoveryAvailable && !taskRecoveryGateVisible && !taskRecoveryStartupCorrupt
            && !taskRecoveryHydrating && !taskRecoverySaving && taskRecoveryCheckpointTask == nil
            && taskRecoveryCheckpointError == nil && taskAttachmentCheckpointFailed == nil
            && taskAttachmentCheckpointDesired == nil && taskStartupSaveReceipt == nil
            && !taskAttachmentWorking && taskAttachmentSaveRequest == nil && taskAttachmentDiscardRequest == nil
            && taskFileImportClaim == nil && taskFileImportTask == nil && taskFileImporterID == nil
            && !taskFileImporterPresented && !taskLinkSheetActive && !taskReferenceOpening && !taskAttachmentOpening
            && taskFileOpenPresentation == nil && taskAudioPlayer == nil && taskSharePayload == nil
            && taskOwnedMenuSelection == nil && taskOwnedMenuAction == nil
            && !projectFileAddPending && !projectFileAvailabilityPending
            && !projectFileAddOpening && projectFileImportClaim == nil
            && projectFileImportTask == nil && projectFileImporterID == nil && !projectFileImporterPresented
            && projectAttachmentWriteRequest == nil && projectNotesWriteRequest == nil
            && projectCreateRequest == nil && projectFocusRequest == nil && projectRenameRequest == nil
            && projectFlowRequest == nil && projectTaskSortRequest == nil && projectTaskOrderRequest == nil
            && projectStatusRequest == nil && projectDateRequest == nil && projectAreaRequest == nil
            && projectTagsRequest == nil && projectSectionRequest == nil && projectSectionRenameRequest == nil
            && projectSectionDeleteRequest == nil && projectSectionOrderRequest == nil
            && projectDuplicateRequest == nil && projectLifecycleRequest == nil
            && projectDeleteRequest == nil && projectDeleteUndoRequest == nil
            && !savedSearchWritePresented && !settingsSyncPresented && !settingsSyncChecking
            && !settingsManagePresented && !settingsAboutPresented && !settingsCalendarPresented && !settingsNotificationsPresented && !settingsGeneralPresented && !settingsDataPresented && !settingsGtdPresented
    }

    func downloadProjectAttachment(_ attachmentID: String) {
        guard projectAttachmentDownloadEnabled || projectNotesFlushTask != nil,
              ready, selectedSurface == .project, !retryNeeded, !settingsSyncRestartRequired,
              !appLock.concealed, projectAttachmentDownloadOwner == nil, let currentHost = host,
              projectAttachmentRows.filter({ $0.text("id") == attachmentID }).count == 1,
              let row = projectAttachmentRows.first(where: { $0.text("id") == attachmentID }),
              row.text("kind") == "file", row.flag("canDownload"), !row.flag("downloading"),
              !attachmentID.isEmpty, attachmentID.utf16.count <= 500,
              let selectedRaw = try? json(row) else { return }
        let id = projectHeader.text("id")
        guard !id.isEmpty, id.utf16.count <= 500 else { return }
        let owner = ProjectAttachmentDownloadOwner(id: UUID(), host: currentHost, projectID: id,
            attachmentID: attachmentID, session: projectFilterSession,
            generation: projectAttachmentDownloadGeneration, notesDraft: projectNotesDraft)
        observeDiagnosticsConcealment()
        projectAttachmentDownloadOwner = owner
        projectAttachmentOpenError = nil
        projectAttachmentDownloadTask = Task { await performProjectAttachmentDownload(owner, selectedRaw: selectedRaw) }
    }

    // Cancellation revokes delivery, never the busy owner of an awaited bridge call.
    func cancelProjectAttachmentDownload() {
        guard projectAttachmentDownloadOwner != nil else { return }
        projectAttachmentDownloadGeneration += 1
        projectAttachmentDownloadTask?.cancel()
        projectAttachmentReadGeneration += 1
        projectAttachmentLoading = false
    }

    private func projectAttachmentDownloadCurrent(_ owner: ProjectAttachmentDownloadOwner, requireClaim: Bool = true) -> Bool {
        host === owner.host && projectAttachmentDownloadOwner?.id == owner.id
            && projectAttachmentDownloadGeneration == owner.generation
            && (!requireClaim || projectAttachmentOpenClaim == owner.id)
            && !Task.isCancelled && foregroundSyncSceneActive && UIApplication.shared.applicationState == .active
            && projectAttachmentDownloadContextClean && selectedSurface == .project
            && projectFilterSession == owner.session && projectHeader.text("id") == owner.projectID
            && projectDetail.text("projectId") == owner.projectID
            && projectNotesDraft.utf8.elementsEqual(owner.notesDraft.utf8)
    }

    private enum ProjectAttachmentDownloadReply {
        case resolution(status: String, message: String?)
        case refused(code: String, message: String)
    }

    private func validateProjectAttachmentDownloadReply(_ result: CoreObject) throws -> ProjectAttachmentDownloadReply {
        guard let ok = result["ok"] as? NSNumber, CFGetTypeID(ok) == CFBooleanGetTypeID() else {
            throw CocoaError(.coderReadCorrupt)
        }
        if ok.boolValue {
            guard Set(result.keys) == Set(["ok", "value"]), let value = result["value"] as? CoreObject,
                  Set(value.keys) == Set(["status", "message", "update"]), let status = value["status"] as? String,
                  ["available", "generation-conflict", "unrecoverable", "unavailable", "stale"].contains(status),
                  value["update"] is NSNull else { throw CocoaError(.coderReadCorrupt) }
            if status == "available" || status == "stale" {
                guard value["message"] is NSNull else { throw CocoaError(.coderReadCorrupt) }
                return .resolution(status: status, message: nil)
            }
            guard let message = value["message"] as? String else { throw CocoaError(.coderReadCorrupt) }
            if status == "unrecoverable" {
                guard !message.isEmpty, message.utf16.count <= 2_000 else { throw CocoaError(.coderReadCorrupt) }
            }
            return .resolution(status: status, message: message)
        }
        guard Set(result.keys) == Set(["ok", "error"]), let error = result["error"] as? CoreObject,
              Set(error.keys) == Set(["code", "message"]), let code = error["code"] as? String,
              ["NOT_READY", "INVALID_INPUT", "STALE_REVISION", "TASK_NOT_FOUND", "ACTION_FAILED", "SAVE_FAILED"].contains(code),
              let message = error["message"] as? String else { throw CocoaError(.coderReadCorrupt) }
        return .refused(code: code, message: message)
    }

    private func performProjectAttachmentDownload(_ owner: ProjectAttachmentDownloadOwner, selectedRaw: String) async {
        var ownsBusy = false
        defer {
            if projectAttachmentDownloadOwner?.id == owner.id {
                let current = projectAttachmentDownloadCurrent(owner)
                projectAttachmentDownloadOwner = nil
                projectAttachmentDownloadTask = nil
                projectAttachmentDownloadingID = nil
                if projectAttachmentOpenClaim == owner.id { projectAttachmentOpening = false }
                if ownsBusy, host === owner.host {
                    if current { finishOperation() }
                    else { busy = false; refreshRequested = false }
                }
            }
        }
        // Join an already admitted blur before freezing its ordinary Notes admission.
        if let flush = projectNotesFlushTask {
            guard await flush.value else { return }
        }
        guard projectAttachmentDownloadCurrent(owner, requireClaim: false), projectViewCurrent, !busy,
              let selected = projectAttachmentRows.first(where: { $0.text("id") == owner.attachmentID }),
              (try? json(selected)) == selectedRaw else { return }
        projectAttachmentOpenClaim = owner.id
        projectAttachmentOpening = true
        projectAttachmentDownloadingID = owner.attachmentID
        guard projectAttachmentDownloadCurrent(owner),
              await flushProjectNotesEdit(attachmentOpenClaim: owner.id),
              projectAttachmentDownloadCurrent(owner), projectViewCurrent, !busy else { return }
        let current = { [self] in projectAttachmentDownloadCurrent(owner) }
        if !projectAttachmentsVisible || projectAttachmentLoading {
            await readProjectAttachments(force: true, ownedGuard: current)
        }
        guard current(), projectViewCurrent, !busy,
              !projectNotesDirty, !projectNotesWritePending, projectAttachmentsVisible, !projectAttachmentLoading,
              let row = projectAttachmentRows.first(where: { $0.text("id") == owner.attachmentID }),
              row.text("kind") == "file", row.flag("canDownload"), !row.flag("downloading"),
              (try? json(row)) == selectedRaw else { return }
        let revision = projectDetail.text("mutationRevision")
        guard !revision.isEmpty, revision.utf16.count <= 200 else { return }
        let request: String
        do {
            request = try json(["projectId": owner.projectID, "attachmentId": owner.attachmentID, "revision": revision])
            guard request.utf8.count <= 128 * 1024 else { return }
        } catch { return }
        busy = true
        ownsBusy = true
        projectAttachmentDownloadOwner?.dispatched = true
        let reply: ProjectAttachmentDownloadReply
        do {
            #if DEBUG && (targetEnvironment(simulator) || NATIVE_DEVICE_TEST)
            if projectAttachmentDownloadTestThrowOnce {
                projectAttachmentDownloadTestThrowOnce = false
                throw CocoaError(.fileWriteUnknown)
            }
            #endif
            var encoded = try await owner.host.foregroundSync(command: "projectAttachmentDownload", requestJSON: request)
            #if DEBUG && (targetEnvironment(simulator) || NATIVE_DEVICE_TEST)
            if projectAttachmentDownloadTestDelayOnce {
                projectAttachmentDownloadTestDelayOnce = false
                await withCheckedContinuation { (continuation: CheckedContinuation<Void, Never>) in
                    DispatchQueue.main.asyncAfter(deadline: .now() + 8) { continuation.resume() }
                }
            }
            if projectAttachmentDownloadTestMalformedOnce {
                projectAttachmentDownloadTestMalformedOnce = false
                encoded = "{\"ok\":true,\"value\":{\"status\":\"available\",\"message\":null,\"update\":{}}}"
            }
            #endif
            guard encoded.utf8.count <= 128 * 1024 else { throw CocoaError(.coderReadCorrupt) }
            reply = try validateProjectAttachmentDownloadReply(decode(encoded))
        } catch {
            guard host === owner.host, projectAttachmentDownloadOwner?.id == owner.id else { return }
            do {
                if try await readProjectFileAvailabilityInventory(owner.host, initialOwner: owner, requestJSON: request) {
                    return
                }
            } catch { /* Inventory failure never clears a previously adopted Download. */ }
            guard host === owner.host, projectAttachmentDownloadOwner?.id == owner.id else { return }
            if projectFileAvailabilityPending { return }
            requireSettingsSyncRestart(owner.host)
            return
        }
        if case let .resolution(status, _) = reply, status == "available" || status == "unrecoverable" {
            await rememberProjectFileAvailabilityAcknowledgment(owner, requestJSON: request)
        }
        guard projectAttachmentDownloadCurrent(owner) else { return }
        let message: String?
        switch reply {
        case let .resolution(_, text): message = text
        case let .refused(_, text): message = text
        }
        guard await readProjectDetail(ownedGuard: current), current() else { return }
        if projectNotesEditMode {
            do { try await readProjectNotesEditOptions(ownedGuard: current) }
            catch {
                guard current() else { return }
                projectNotesEditReadError = label("settings.feedback.actionFailed")
            }
        }
        guard current() else { return }
        await readProjectAttachments(force: true, ownedGuard: current)
        guard current() else { return }
        if let message {
            projectAttachmentOpenError = message.isEmpty ? label("settings.feedback.actionFailed") : message
        }
    }

    func dismissProjectAttachmentOpenError() { projectAttachmentOpenError = nil }

    private func projectFileImportCurrent(_ claim: ProjectFileImportClaim) -> Bool {
        host === claim.host && ready && !Task.isCancelled && !appLock.concealed
            && projectFileImportClaim?.id == claim.id && projectFileImporterID == claim.id
            && projectAttachmentEditContext(claim.projectID, session: claim.session)
    }

    func prepareProjectFileImport() async -> UUID? {
        guard let currentHost = host else { return nil }
        let projectID = projectHeader.text("id"), session = projectFilterSession
        let admission = projectFileImportAdmission
        // A blur may already have queued its ordinary Notes flush. Let that
        // admitted task finish even if it owns busy; this awaits existing work
        // and admits no new write before the full check below.
        if let flush = projectNotesFlushTask {
            guard await flush.value else { return nil }
        }
        guard projectFileImportAdmission == admission, host === currentHost,
              !Task.isCancelled, projectFileAddOpenEnabled,
              projectAttachmentEditContext(projectID, session: session) else { return nil }
        let claim = ProjectFileImportClaim(id: UUID(), host: currentHost,
            projectID: projectID, session: session)
        projectFileImportClaim = claim
        projectFileImporterID = claim.id
        projectFileAddOpening = true
        projectFileAddError = nil
        defer { if projectFileImportClaim?.id == claim.id { projectFileAddOpening = false } }
        guard await flushProjectNotesEdit(attachmentOpenClaim: nil, fileAddClaim: claim.id),
              projectFileImportCurrent(claim), !busy, !retryNeeded,
              !projectNotesDirty, !projectNotesWritePending else {
            if projectFileImportClaim?.id == claim.id { cancelProjectFileImport() }
            return nil
        }
        projectFileImporterPresented = true
        return claim.id
    }

    func setProjectFileImporterPresented(_ value: Bool, pickerID: UUID?) {
        guard pickerID == projectFileImporterID else { return }
        if !value { projectFileImporterPresented = false }
    }

    func cancelProjectFileImport() {
        // Invalidate a Prepare still awaiting an already admitted Notes flush.
        projectFileImportAdmission = UUID()
        projectFileImportClaim = nil
        projectFileImporterID = nil
        projectFileImporterPresented = false
        projectFileAddOpening = false
        projectFileImportTask?.cancel()
        // Cancellation ends delivery, not a native intent already submitted.
        // Its original operation/summary remains available for Retry or Stop.
    }

    func completeProjectFileImport(_ result: Result<[URL], Error>, pickerID: UUID) async {
        guard let claim = projectFileImportClaim, claim.id == pickerID else { return }
        guard !projectFileAddOpening else { return }
        guard projectFileImportCurrent(claim) else { cancelProjectFileImport(); return }
        projectFileImporterPresented = false
        let selection: URL
        switch result {
        case .success(let urls):
            guard urls.count == 1, let url = urls.first else { cancelProjectFileImport(); return }
            selection = url
        case .failure(let failure):
            let error = failure as NSError
            if error.domain != NSCocoaErrorDomain || error.code != NSUserCancelledError {
                projectFileAddError = "This file could not be selected. Try again."
            }
            cancelProjectFileImport()
            return
        }
        guard !busy, !retryNeeded, !projectFileAddPending else { cancelProjectFileImport(); return }
        projectFileAddOpening = true
        let task = Task { await performProjectFileImport(selection, claim: claim) }
        projectFileImportTask = task
        await task.value
        if projectFileImportClaim == nil || projectFileImportClaim?.id == claim.id {
            projectFileImportTask = nil
        }
    }

    private func performProjectFileImport(_ selection: URL, claim: ProjectFileImportClaim) async {
        var mutationStarted = false
        var acknowledged = false
        defer {
            if projectFileImportClaim?.id == claim.id {
                projectFileImportClaim = nil
                projectFileImporterID = nil
                projectFileImporterPresented = false
                projectFileAddOpening = false
            }
            if mutationStarted { finishOperation() }
        }
        do {
            guard await flushProjectNotesEdit(attachmentOpenClaim: nil, fileAddClaim: claim.id),
                  projectFileImportCurrent(claim), !projectNotesDirty, !projectNotesWritePending else {
                throw CancellationError()
            }
            // Selection may have remained open across another client's edit.
            // Read the current Project and token now, never the pre-picker array.
            try await readSelectedSurface()
            guard projectFileImportCurrent(claim), !busy, !retryNeeded,
                  !projectNotesDirty, !projectNotesWritePending else { throw CancellationError() }
            projectAttachmentOpeningRaw = nil
            projectAttachmentOpeningRevision = ""
            try await readProjectAttachmentEditOptions(projectID: claim.projectID, session: claim.session)
            guard projectFileImportCurrent(claim), !busy, !retryNeeded,
                  projectAttachmentEditOptionsCurrent, projectAttachmentEditOptions.flag("canEdit"),
                  !projectNotesDirty, !projectNotesWritePending else { throw CancellationError() }
            let token = projectAttachmentEditOptions.object("project").filter { $0.key != "id" }
            let requestID = UUID().uuidString.lowercased()
            let request = try json(["requestId": requestID, "projectId": claim.projectID, "expected": token])
            let operation = ProjectFileAddOperation(host: claim.host, requestID: requestID,
                projectID: claim.projectID, session: claim.session, requestJSON: request)
            projectFileAddOperation = operation
            busy = true
            mutationStarted = true
            let reply = try decode(try await claim.host.addProviderProjectAttachment(selectedURL: selection, requestJSON: request))
            try acknowledgeProjectFileAdd(reply, operation: operation)
            acknowledged = true
            projectAttachmentsCurrent = false
            if projectFileImportCurrent(claim) {
                try await refreshProjectFileAddPresentation(operation)
            }
        } catch {
            guard host === claim.host else { return }
            if let operation = projectFileAddOperation, operation.host === claim.host {
                await retainProjectFileAddAfterFailure(operation)
            } else if projectFileImportClaim?.id == claim.id && !Task.isCancelled && !appLock.concealed {
                projectFileAddError = acknowledged
                    ? "The attachment operation finished, but the Project could not be refreshed. Try again."
                    : "This file could not be added. Try again."
            }
        }
    }

    private func parseProjectFileAvailabilitySummary(_ raw: String) throws -> CoreObject? {
        guard raw.utf8.count <= 4_096 else { throw CocoaError(.coderReadCorrupt) }
        let value = try NativeJSON.jsonObject(with: Data(raw.utf8), options: [.fragmentsAllowed])
        if value is NSNull { return nil }
        guard let summary = value as? CoreObject,
              Set(summary.keys) == Set(["requestId", "projectId", "attachmentId", "phase"]),
              let request = summary["requestId"] as? String,
              UUID(uuidString: request)?.uuidString.lowercased() == request,
              let attachment = summary["attachmentId"] as? String,
              UUID(uuidString: attachment)?.uuidString.lowercased() == attachment,
              let project = summary["projectId"] as? String, !project.isEmpty, project.utf16.count <= 500,
              project.rangeOfCharacter(from: .controlCharacters) == nil,
              ["intent", "stagePrepared", "stageFilled", "published", "domainSaved", "settled"].contains(summary.text("phase")) else {
            throw CocoaError(.coderReadCorrupt)
        }
        return summary
    }

    private func projectFileAvailabilityOperationCurrent(_ operation: ProjectFileAvailabilityOperation) -> Bool {
        host === operation.host && projectFileAvailabilityOperation?.id == operation.id
            && projectFileAvailabilityOperation?.host === operation.host
            && projectFileAvailabilityOperation?.requestID == operation.requestID
            && projectFileAvailabilityOperation?.projectID == operation.projectID
            && projectFileAvailabilityOperation?.attachmentID == operation.attachmentID
            && projectFileAvailabilityOperation?.requestJSON == operation.requestJSON
    }

    @discardableResult
    private func readProjectFileAvailabilityInventory(_ currentHost: CoreHost,
        initialOwner: ProjectAttachmentDownloadOwner? = nil, requestJSON: String? = nil) async throws -> Bool {
        let previous = projectFileAvailabilityOperation
        guard host === currentHost, previous == nil || previous?.host === currentHost else { throw CancellationError() }
        let raw = try await currentHost.projectFileAvailabilitySummary()
        guard host === currentHost, projectFileAvailabilityOperation?.id == previous?.id else { throw CancellationError() }
        if let initialOwner {
            guard initialOwner.host === currentHost, projectAttachmentDownloadOwner?.id == initialOwner.id,
                  projectAttachmentDownloadOwner?.session == initialOwner.session else { throw CancellationError() }
        }
        guard let summary = try parseProjectFileAvailabilitySummary(raw) else {
            // Disappearance is not a terminal acknowledgment for an adopted UUID.
            guard previous == nil else { throw CocoaError(.coderReadCorrupt) }
            return false
        }
        if let previous {
            guard summary.text("requestId") == previous.requestID,
                  summary.text("projectId") == previous.projectID,
                  summary.text("attachmentId") == previous.attachmentID else { throw CancellationError() }
        }
        if let initialOwner {
            guard summary.text("projectId") == initialOwner.projectID,
                  summary.text("attachmentId") == initialOwner.attachmentID else { throw CancellationError() }
        }
        if previous == nil, let acknowledged = projectFileAvailabilityAcknowledged,
           acknowledged.host === currentHost, summary.text("phase") == "settled",
           summary.text("requestId") == acknowledged.requestID,
           summary.text("projectId") == acknowledged.projectID,
           summary.text("attachmentId") == acknowledged.attachmentID { return false }
        if previous == nil {
            projectFileAvailabilityOperation = ProjectFileAvailabilityOperation(id: UUID(), host: currentHost,
                requestID: summary.text("requestId"), projectID: summary.text("projectId"),
                attachmentID: summary.text("attachmentId"), session: initialOwner?.session, requestJSON: requestJSON)
        }
        projectFileAvailabilitySummary = summary
        projectFileAvailabilityError = projectFileAvailabilityError ?? "A pending Project download needs Retry or Stop download."
        retryNeeded = true
        return true
    }

    private func rememberProjectFileAvailabilityAcknowledgment(_ owner: ProjectAttachmentDownloadOwner,
        requestJSON: String) async {
        do {
            let summary = try parseProjectFileAvailabilitySummary(await owner.host.projectFileAvailabilitySummary())
            guard host === owner.host, projectAttachmentDownloadOwner?.id == owner.id,
                  projectFileAvailabilityOperation == nil, let summary, summary.text("phase") == "settled",
                  summary.text("projectId") == owner.projectID,
                  summary.text("attachmentId") == owner.attachmentID else { return }
            projectFileAvailabilityAcknowledged = ProjectFileAvailabilityOperation(id: UUID(), host: owner.host,
                requestID: summary.text("requestId"), projectID: owner.projectID, attachmentID: owner.attachmentID,
                session: owner.session, requestJSON: requestJSON)
        } catch { /* A failed optional inventory cannot revoke the exact terminal foreground ACK. */ }
    }

    private func acknowledgeProjectFileAvailability(_ raw: String, operation: ProjectFileAvailabilityOperation,
        stop: Bool) throws {
        guard projectFileAvailabilityOperationCurrent(operation), raw.utf8.count <= 128 * 1_024 else {
            throw CancellationError()
        }
        let result = try decode(raw)
        let abandoned = Set(result.keys) == Set(["abandoned"])
            && (result["abandoned"] as? NSNumber).map {
                CFGetTypeID($0) == CFBooleanGetTypeID() && $0.boolValue
            } == true
        var terminal = false
        if !stop, !abandoned,
           case let .resolution(status, _) = try validateProjectAttachmentDownloadReply(["ok": true, "value": result]) {
            terminal = status == "available" || status == "unrecoverable"
        }
        guard abandoned || terminal else { throw CocoaError(.coderReadCorrupt) }
        // Clear only this exact request after settlement, before ordinary refresh.
        projectFileAvailabilityAcknowledged = operation
        projectFileAvailabilityOperation = nil
        projectFileAvailabilitySummary = [:]
        projectFileAvailabilityError = nil
        retryNeeded = projectFileAddPending
        error = nil
    }

    private func retainProjectFileAvailabilityAfterFailure(_ operation: ProjectFileAvailabilityOperation) async {
        guard projectFileAvailabilityOperationCurrent(operation) else { return }
        projectFileAvailabilityError = "The download could not finish. Retry it or stop the pending download."
        retryNeeded = true
        do { try await readProjectFileAvailabilityInventory(operation.host) }
        catch {
            if projectFileAvailabilityOperationCurrent(operation) { retryNeeded = true }
        }
    }

    func retryProjectFileAvailability() async { await resolveProjectFileAvailability(stop: false) }
    func stopProjectFileAvailability() async { await resolveProjectFileAvailability(stop: true) }

    func cancelProjectFileAvailabilityRecovery() {
        // Keep the durable request and busy owner until the native invocation drains.
        projectFileAvailabilityRecoveryTask?.cancel()
    }

    private func resolveProjectFileAvailability(stop: Bool) async {
        guard projectFileAvailabilityRecoveryEnabled, !Task.isCancelled,
              let operation = projectFileAvailabilityOperation else { return }
        busy = true
        let invocation = UUID()
        projectFileAvailabilityRecoveryTaskID = invocation
        let task = Task { await self.performProjectFileAvailabilityRecovery(operation, stop: stop, invocation: invocation) }
        projectFileAvailabilityRecoveryTask = task
        await task.value
    }

    private func performProjectFileAvailabilityRecovery(_ operation: ProjectFileAvailabilityOperation,
        stop: Bool, invocation: UUID) async {
        var restart = false
        defer {
            if projectFileAvailabilityRecoveryTaskID == invocation {
                projectFileAvailabilityRecoveryTaskID = nil
                projectFileAvailabilityRecoveryTask = nil
                if host === operation.host {
                    finishOperation()
                    if restart {
                        Task { [currentHost = operation.host] in
                            guard self.host === currentHost, !self.appLock.concealed,
                                  !self.projectFileAvailabilityPending else { return }
                            await self.start()
                        }
                    }
                }
            }
        }
        do {
            guard projectFileAvailabilityOperationCurrent(operation),
                  projectFileAvailabilityRecoveryTaskID == invocation, !Task.isCancelled,
                  !appLock.concealed, UIApplication.shared.applicationState == .active else { return }
            let raw: String
            if stop { raw = try await operation.host.abandonProjectFileAvailability(requestId: operation.requestID) }
            else { raw = try await operation.host.recoverProjectFileAvailability(requestId: operation.requestID) }
            try acknowledgeProjectFileAvailability(raw, operation: operation, stop: stop)
            projectAttachmentsCurrent = false
            if !ready {
                selectedSurface = .projects
                restart = true
            } else if !Task.isCancelled, !appLock.concealed, let session = operation.session,
                      selectedSurface == .project, projectFilterSession == session,
                      projectHeader.text("id") == operation.projectID {
                // Download recovery also refreshes archived Projects; Add's edit-only guard does not apply.
                try await readSelectedSurface()
                guard host === operation.host, !Task.isCancelled, !appLock.concealed,
                      selectedSurface == .project, projectFilterSession == session,
                      projectHeader.text("id") == operation.projectID else { return }
                await readProjectAttachments(force: true)
            }
        } catch {
            if projectFileAvailabilityOperationCurrent(operation) {
                await retainProjectFileAvailabilityAfterFailure(operation)
            } else if host === operation.host, projectFileAvailabilityOperation == nil,
                      projectFileAvailabilityAcknowledged?.id == operation.id, !appLock.concealed {
                projectFileAvailabilityError = "The download finished, but the Project could not be refreshed. Try again."
            }
        }
    }

    private func parseProjectFileAddSummary(_ raw: String) throws -> CoreObject? {
        guard raw.utf8.count <= 4_096 else { throw CocoaError(.coderReadCorrupt) }
        let value = try NativeJSON.jsonObject(with: Data(raw.utf8), options: [.fragmentsAllowed])
        if value is NSNull { return nil }
        guard let summary = value as? CoreObject,
              Set(summary.keys) == Set(["requestId", "projectId", "phase"]),
              let request = summary["requestId"] as? String,
              UUID(uuidString: request)?.uuidString.lowercased() == request,
              let project = summary["projectId"] as? String, !project.isEmpty, project.utf16.count <= 500,
              project.rangeOfCharacter(from: .controlCharacters) == nil,
              ["intent", "stagePrepared", "stageFilled", "published", "domainSaved", "settled"].contains(summary.text("phase")) else {
            throw CocoaError(.coderReadCorrupt)
        }
        return summary
    }

    private func readProjectFileAddInventory(_ currentHost: CoreHost) async throws {
        let raw = try await currentHost.projectFileAddSummary()
        guard host === currentHost else { throw CancellationError() }
        #if DEBUG && targetEnvironment(simulator)
        if startupInventoryReadTestFailureOnce {
            startupInventoryReadTestFailureOnce = false
            _ = try? await currentHost.call("logLine", argumentsJSON: json([
                "Native iOS isolated startup inventory read failed",
                #"{"outcome":"injected"}"#,
            ]))
            guard host === currentHost else { throw CancellationError() }
            throw CocoaError(.fileReadUnknown)
        }
        #endif
        let summary = try parseProjectFileAddSummary(raw)
        if let operation = projectFileAddOperation {
            guard operation.host === currentHost,
                  summary == nil || (summary?.text("requestId") == operation.requestID
                    && summary?.text("projectId") == operation.projectID) else { throw CancellationError() }
        }
        if let summary {
            if projectFileAddOperation == nil {
                projectFileAddOperation = ProjectFileAddOperation(host: currentHost,
                    requestID: summary.text("requestId"), projectID: summary.text("projectId"),
                    session: nil, requestJSON: nil)
            }
            projectFileAddSummary = summary
            retryNeeded = true
        } else if let operation = projectFileAddOperation {
            try clearProjectFileAdd(operation)
        } else {
            projectFileAddSummary = [:]
        }
    }

    private func projectFileAddOperationCurrent(_ operation: ProjectFileAddOperation) -> Bool {
        host === operation.host && projectFileAddOperation?.host === operation.host
            && projectFileAddOperation?.requestID == operation.requestID
            && projectFileAddOperation?.projectID == operation.projectID
            && projectFileAddOperation?.requestJSON == operation.requestJSON
    }

    private func clearProjectFileAdd(_ operation: ProjectFileAddOperation) throws {
        guard projectFileAddOperationCurrent(operation) else { throw CancellationError() }
        projectFileAddOperation = nil
        projectFileAddSummary = [:]
        projectFileAddError = nil
        projectFileAddOpening = false
        retryNeeded = false
        error = nil
    }

    private func acknowledgeProjectFileAdd(_ result: CoreObject, operation: ProjectFileAddOperation) throws {
        guard projectFileAddOperationCurrent(operation) else { throw CancellationError() }
        let abandoned = Set(result.keys) == Set(["abandoned"])
            && (result["abandoned"] as? NSNumber).map {
                CFGetTypeID($0) == CFBooleanGetTypeID() && $0.boolValue
            } == true
        guard abandoned || (Set(result.keys) == Set(["id", "attachmentIds"])
            && result.text("id") == operation.projectID
            && result["attachmentIds"] as? [String] == [operation.requestID]) else {
            throw CocoaError(.coderReadCorrupt)
        }
        // The exact native ACK settles ownership even if presentation was lost.
        // A subsequent inventory/read failure must not replay a completed Add.
        try clearProjectFileAdd(operation)
    }

    private func retainProjectFileAddAfterFailure(_ operation: ProjectFileAddOperation) async {
        guard projectFileAddOperationCurrent(operation) else { return }
        projectFileAddOpening = false
        projectFileAddError = "The attachment operation could not finish. Retry it or stop the pending operation."
        retryNeeded = true
        do {
            try await readProjectFileAddInventory(operation.host)
            if host === operation.host && !projectFileAddPending {
                projectAttachmentsCurrent = false
                projectFileAddError = "The attachment operation could not be confirmed. Refresh the Project to check its saved attachments."
            }
        }
        catch {
            // An unrelated failed read cannot erase a matching retained owner.
            if projectFileAddOperationCurrent(operation) { retryNeeded = true }
        }
    }

    private func refreshProjectFileAddPresentation(_ operation: ProjectFileAddOperation) async throws {
        guard host === operation.host, !Task.isCancelled, !appLock.concealed,
              let session = operation.session,
              projectAttachmentEditContext(operation.projectID, session: session) else { return }
        try await readSelectedSurface()
        guard host === operation.host, !Task.isCancelled, !appLock.concealed,
              projectAttachmentEditContext(operation.projectID, session: session) else { return }
        try await readProjectAttachments(force: true)
        guard host === operation.host, !Task.isCancelled, !appLock.concealed,
              projectAttachmentEditContext(operation.projectID, session: session) else { return }
    }

    func retryProjectFileAdd() async { await resolveProjectFileAdd(stop: false) }
    func stopProjectFileAdd() async { await resolveProjectFileAdd(stop: true) }

    func retryProjectFileAddRead() async {
        guard !projectFileAddPending, !busy, !retryNeeded, !appLock.concealed, let currentHost = host else { return }
        let id = projectHeader.text("id"), session = projectFilterSession
        await retryProjectAttachmentEditRead()
        guard host === currentHost, !Task.isCancelled,
              projectAttachmentEditContext(id, session: session), projectAttachmentsVisible,
              projectAttachmentEditReadError == nil, projectAttachmentError == nil else { return }
        projectFileAddError = nil
    }

    private func resolveProjectFileAdd(stop: Bool) async {
        guard projectFileAddRecoveryEnabled, let operation = projectFileAddOperation else { return }
        busy = true
        var restart = false
        defer {
            finishOperation()
            if restart {
                Task { [currentHost = operation.host] in
                    guard self.host === currentHost, !self.appLock.concealed else { return }
                    await self.start()
                }
            }
        }
        do {
            let raw: String
            if stop { raw = try await operation.host.abandonProjectFileAdd(requestId: operation.requestID) }
            else { raw = try await operation.host.recoverProjectFileAdd(requestId: operation.requestID) }
            guard projectFileAddOperationCurrent(operation) else { throw CancellationError() }
            try acknowledgeProjectFileAdd(decode(raw), operation: operation)
            projectAttachmentsCurrent = false
            if !ready {
                selectedSurface = .projects
                restart = true
            } else {
                try await refreshProjectFileAddPresentation(operation)
            }
        } catch {
            if projectFileAddOperationCurrent(operation) {
                await retainProjectFileAddAfterFailure(operation)
            } else if host === operation.host && !appLock.concealed {
                projectFileAddError = "The attachment operation finished, but the Project could not be refreshed. Try again."
            }
        }
    }

    private func projectAttachmentEditContext(_ id: String, session: Int) -> Bool {
        selectedSurface == .project && projectCurrent && projectFilterSession == session
            && projectHeader.text("id") == id && projectDetail.text("projectId") == id
            && !projectDetail.flag("readOnly") && !appLock.concealed
    }

    private func readProjectAttachmentEditOptions(projectID id: String, session: Int) async throws {
        projectAttachmentEditOptionsCurrent = false
        guard let currentHost = host, projectAttachmentEditContext(id, session: session) else { throw CocoaError(.coderReadCorrupt) }
        let revision = projectDetail.text("mutationRevision")
        let options = try await query("projectAttachmentEditOptions", [try json(["projectId": id])])
        let project = options.object("project")
        guard host === currentHost, !Task.isCancelled, projectAttachmentEditContext(id, session: session),
              options.count == 3, options.text("revision") == revision,
              project.count == 7, project.text("id") == id,
              let canEdit = options["canEdit"] as? NSNumber,
              CFGetTypeID(canEdit) == CFBooleanGetTypeID(), canEdit.boolValue,
              (project["title"] as? String).map({ $0.utf16.count <= 100_000 }) == true,
              ["active", "waiting", "someday"].contains(project.text("status")),
              project["attachments"] is NSNull || project["attachments"] is [CoreObject],
              project["rev"] is NSNull || (project["rev"] as? Int).map({ $0 >= 0 }) == true,
              project["revBy"] is NSNull || (project["revBy"] as? String)
                .map({ $0.utf16.count <= 500 }) == true,
              TaskDatePickerComponents.instant(project.text("updatedAt")) != nil,
              let attachments = project["attachments"],
              let attachmentsRaw = try? json(["attachments": attachments]), attachmentsRaw.utf8.count <= 2_000_000,
              projectAttachmentOpeningRevision.isEmpty || projectAttachmentOpeningRevision == revision,
              projectAttachmentOpeningRaw == nil || projectAttachmentOpeningRaw == attachmentsRaw else {
            throw CocoaError(.coderReadCorrupt)
        }
        projectAttachmentOpeningRevision = revision
        projectAttachmentOpeningRaw = attachmentsRaw
        projectAttachmentEditOptions = options
        projectAttachmentEditOptionsCurrent = true
        projectAttachmentEditReadError = nil
    }

    func openProjectAttachmentLinkSheet() {
        guard projectAttachmentAddOpenEnabled,
              let rowsRaw = try? json(projectAttachmentRows) else { return }
        let id = projectHeader.text("id"), session = projectFilterSession
        let claim = UUID()
        projectAttachmentEditClaim = claim
        projectAttachmentEditOpening = true
        projectAttachmentOpeningRowsRaw = rowsRaw
        projectAttachmentOpeningRaw = nil
        projectAttachmentOpeningRevision = ""
        projectAttachmentLinkError = nil
        projectAttachmentWriteError = nil
        projectAttachmentEditReadError = nil
        Task { await performProjectAttachmentLinkOpen(projectID: id, session: session, claim: claim) }
    }

    private func performProjectAttachmentLinkOpen(projectID id: String, session: Int, claim: UUID) async {
        defer { if projectAttachmentEditClaim == claim { projectAttachmentEditOpening = false } }
        guard await flushProjectNotesEdit(), projectAttachmentEditClaim == claim,
              projectAttachmentEditContext(id, session: session),
              !projectNotesDirty && !projectNotesWritePending else { return }
        if !projectAttachmentsVisible || projectAttachmentLoading { await readProjectAttachments(force: true) }
        guard projectAttachmentsVisible, !projectAttachmentLoading,
              (try? json(projectAttachmentRows)) == projectAttachmentOpeningRowsRaw else {
            projectAttachmentEditReadError = "Project links changed. Try again."
            return
        }
        do {
            try await readProjectAttachmentEditOptions(projectID: id, session: session)
            guard projectAttachmentEditClaim == claim, !projectNotesDirty && !projectNotesWritePending else { return }
            projectAttachmentLinkDraft = ""
            projectAttachmentLinkPresented = true
        } catch {
            if projectAttachmentEditClaim == claim { projectAttachmentEditReadError = "Project links could not be loaded. Try again." }
        }
    }

    func cancelProjectAttachmentLinkSheet() {
        guard projectAttachmentLinkPresented, !busy, !retryNeeded, !projectAttachmentWritePending,
              !projectAttachmentEditOpening else { return }
        projectAttachmentLinkPresented = false
        projectAttachmentLinkDraft = ""
        projectAttachmentLinkError = nil
        projectAttachmentWriteError = nil
        projectAttachmentEditReadError = nil
        projectAttachmentEditOptions = [:]
        projectAttachmentEditOptionsCurrent = false
        projectAttachmentOpeningRaw = nil
        projectAttachmentOpeningRowsRaw = nil
        projectAttachmentOpeningRevision = ""
    }

    func setProjectAttachmentLinkDraft(_ value: String) {
        guard projectAttachmentLinkInputEnabled, value.utf16.count <= 100_000 else { return }
        projectAttachmentLinkDraft = value
        projectAttachmentLinkError = nil
    }

    func saveProjectAttachmentLinks() async {
        guard projectAttachmentLinkCanSave else { return }
        let id = projectHeader.text("id"), session = projectFilterSession
        let text = projectAttachmentLinkDraft
        guard projectAttachmentEditContext(id, session: session),
              !projectNotesDirty && !projectNotesWritePending else { return }
        projectAttachmentEditOpening = true
        defer { projectAttachmentEditOpening = false }
        await performProjectAttachmentWrite(["kind": "add", "text": text], projectID: id,
                                            session: session, submittedText: text)
    }

    func removeProjectAttachmentLink(_ attachmentID: String) {
        beginProjectAttachmentRemove(attachmentID, kind: "link")
    }

    func removeProjectAttachmentFile(_ attachmentID: String) {
        beginProjectAttachmentRemove(attachmentID, kind: "file")
    }

    private func beginProjectAttachmentRemove(_ attachmentID: String, kind: String) {
        guard projectAttachmentRemoveEnabled, let currentHost = host,
              projectAttachmentRows.filter({ $0.text("id") == attachmentID && $0.text("kind") == kind }).count == 1,
              let rowsRaw = try? json(projectAttachmentRows) else { return }
        let id = projectHeader.text("id"), session = projectFilterSession
        let claim = UUID()
        projectAttachmentEditClaim = claim
        projectAttachmentEditOpening = true
        projectAttachmentOpeningRowsRaw = rowsRaw
        projectAttachmentOpeningRaw = nil
        projectAttachmentOpeningRevision = ""
        projectAttachmentWriteError = nil
        projectAttachmentEditReadError = nil
        Task { await performProjectAttachmentRemove(attachmentID, kind: kind, projectID: id,
            session: session, claim: claim, currentHost: currentHost) }
    }

    private func performProjectAttachmentRemove(_ attachmentID: String, kind: String, projectID id: String,
                                                session: Int, claim: UUID, currentHost: CoreHost) async {
        defer { if projectAttachmentEditClaim == claim { projectAttachmentEditOpening = false } }
        func current() -> Bool {
            host === currentHost && !Task.isCancelled && projectAttachmentEditClaim == claim
                && projectAttachmentEditContext(id, session: session)
        }
        guard current(), await flushProjectNotesEdit(), current(),
              !projectNotesDirty && !projectNotesWritePending else { return }
        if !projectAttachmentsVisible || projectAttachmentLoading { await readProjectAttachments(force: true) }
        guard current() else { return }
        guard projectAttachmentsVisible, !projectAttachmentLoading,
              (try? json(projectAttachmentRows)) == projectAttachmentOpeningRowsRaw,
              projectAttachmentRows.filter({ $0.text("id") == attachmentID && $0.text("kind") == kind }).count == 1 else {
            projectAttachmentEditReadError = "Project attachments changed. Try again."
            return
        }
        await performProjectAttachmentWrite(["kind": "remove", "attachmentId": attachmentID],
            projectID: id, session: session, fileRemove: kind == "file", removeClaim: claim)
    }

    private func performProjectAttachmentWrite(_ intent: CoreObject, projectID id: String,
                                               session: Int, submittedText: String? = nil, fileRemove: Bool = false, removeClaim: UUID? = nil) async {
        guard let currentHost = host, projectAttachmentEditContext(id, session: session), !projectNotesDirty,
              !projectNotesWritePending, !busy, !retryNeeded, projectAttachmentWriteRequest == nil else { return }
        busy = true
        defer { finishOperation() }
        do {
            try await readProjectAttachmentEditOptions(projectID: id, session: session)
            guard host === currentHost, !Task.isCancelled,
                  removeClaim == nil || projectAttachmentEditClaim == removeClaim,
                  projectAttachmentEditOptionsCurrent, projectAttachmentEditOptions.flag("canEdit"),
                  !projectNotesDirty && !projectNotesWritePending,
                  submittedText == nil || projectAttachmentLinkDraft == submittedText,
                  projectAttachmentEditContext(id, session: session) else {
                throw CocoaError(.coderReadCorrupt)
            }
            let project = projectAttachmentEditOptions.object("project")
            let expected: CoreObject = ["title": project.text("title"), "status": project.text("status"),
                                        "attachments": project["attachments"]!, "rev": project["rev"]!,
                                        "revBy": project["revBy"]!, "updatedAt": project.text("updatedAt")]
            projectAttachmentWriteRequest = try json(["requestId": UUID().uuidString.lowercased(),
                                                      "projectId": id, "intent": intent, "expected": expected])
            projectAttachmentWriteExpectedID = id
            projectAttachmentWriteSession = session
            projectAttachmentWriteMethod = fileRemove ? "projectFileRemoveWrite" : "projectAttachmentWrite"
            projectAttachmentWriteHost = currentHost
        } catch {
            guard host === currentHost, !Task.isCancelled,
                  removeClaim == nil || projectAttachmentEditClaim == removeClaim,
                  projectAttachmentEditContext(id, session: session) else { return }
            projectAttachmentEditReadError = "Project attachments changed. Try again."
            return
        }
        guard let request = projectAttachmentWriteRequest else { return }
        let method = projectAttachmentWriteMethod
        let result: CoreObject
        do {
            result = try await query(method, [request])
            guard host === currentHost, !Task.isCancelled,
                  projectAttachmentWriteHost === currentHost,
                  projectAttachmentWriteRequest == request, projectAttachmentWriteMethod == method,
                  projectAttachmentWriteExpectedID == id, projectAttachmentWriteSession == session,
                  removeClaim == nil || projectAttachmentEditClaim == removeClaim else { throw CancellationError() }
        }
        catch { await handleProjectAttachmentWriteError(error); return }
        do {
            let accepted = try acknowledgeProjectAttachmentWrite(result)
            if accepted { try await refreshProjectAttachmentsAfterWrite(projectID: id, session: session) }
        } catch {
            if projectAttachmentWriteRequest != nil { await handleProjectAttachmentWriteError(error) }
            else { projectAttachmentEditReadError = "Project attachments could not be refreshed. Try again." }
        }
    }

    @discardableResult private func acknowledgeProjectAttachmentWrite(_ result: CoreObject) throws -> Bool {
        guard projectAttachmentWriteRequest != nil, let id = projectAttachmentWriteExpectedID else {
            throw CocoaError(.coderReadCorrupt)
        }
        if result.count == 1, let message = result["message"] as? String, !message.isEmpty {
            projectAttachmentWriteRequest = nil
            projectAttachmentWriteHost = nil
            projectAttachmentWriteExpectedID = nil
            retryNeeded = false
            projectAttachmentLinkError = message
            projectAttachmentWriteError = message
            error = nil
            return false
        }
        if result.count == 1 && result["blocked"] as? String == "" {
            projectAttachmentWriteRequest = nil
            projectAttachmentWriteHost = nil
            projectAttachmentWriteExpectedID = nil
            projectAttachmentEditOptionsCurrent = false
            retryNeeded = false
            projectAttachmentWriteError = "Project attachments are no longer editable."
            projectAttachmentLinkError = projectAttachmentWriteError
            projectAttachmentEditReadError = projectAttachmentWriteError
            error = nil
            return false
        }
        guard result.count == 2, result.text("id") == id,
              let ids = result["attachmentIds"] as? [String], ids.count <= 500,
              Set(ids).count == ids.count,
              ids.allSatisfy({ !$0.isEmpty && $0.utf16.count <= 500 }) else {
            throw CocoaError(.coderReadCorrupt)
        }
        projectAttachmentWriteRequest = nil
        projectAttachmentWriteHost = nil
        projectAttachmentWriteExpectedID = nil
        projectAttachmentLinkPresented = false
        projectAttachmentLinkDraft = ""
        projectAttachmentLinkError = nil
        projectAttachmentWriteError = nil
        projectAttachmentEditReadError = nil
        projectAttachmentEditOptions = [:]
        projectAttachmentEditOptionsCurrent = false
        projectAttachmentOpeningRaw = nil
        projectAttachmentOpeningRowsRaw = nil
        projectAttachmentOpeningRevision = ""
        retryNeeded = false
        error = nil
        return true
    }

    private func refreshProjectAttachmentsAfterWrite(projectID id: String, session: Int) async throws {
        guard let currentHost = host else { throw CancellationError() }
        try await readSelectedSurface()
        guard host === currentHost, !Task.isCancelled,
              projectAttachmentEditContext(id, session: session) else { throw CocoaError(.coderReadCorrupt) }
        await readProjectAttachments(force: true)
        guard host === currentHost, !Task.isCancelled,
              projectAttachmentEditContext(id, session: session), projectAttachmentsVisible else { throw CocoaError(.coderReadCorrupt) }
    }

    private func handleProjectAttachmentWriteError(_ failure: Error) async {
        if projectAttachmentWriteRequest != nil && isDefiniteRejection(failure) {
            projectAttachmentWriteRequest = nil
            projectAttachmentWriteHost = nil
            projectAttachmentWriteExpectedID = nil
            projectAttachmentEditOptionsCurrent = false
            retryNeeded = false
            projectAttachmentWriteError = "Project attachments could not be saved. Try again."
            projectAttachmentLinkError = projectAttachmentWriteError
            projectAttachmentEditReadError = projectAttachmentWriteError
            error = nil
        } else {
            retryNeeded = projectAttachmentWriteRequest != nil
            projectAttachmentWriteError = "Project attachments could not be saved. Retry the pending write."
            projectAttachmentLinkError = projectAttachmentWriteError
            error = projectAttachmentWriteError
        }
    }

    func retryProjectAttachmentEditRead() async {
        guard selectedSurface == .project, !busy, !retryNeeded, !projectAttachmentWritePending else { return }
        let id = projectHeader.text("id"), session = projectFilterSession
        busy = true
        defer { finishOperation() }
        do {
            try await readSelectedSurface()
            guard projectAttachmentEditContext(id, session: session) else { throw CocoaError(.coderReadCorrupt) }
            await readProjectAttachments(force: true)
            guard projectAttachmentsVisible else { throw CocoaError(.coderReadCorrupt) }
            projectAttachmentOpeningRowsRaw = try json(projectAttachmentRows)
            projectAttachmentOpeningRaw = nil
            projectAttachmentOpeningRevision = ""
            try await readProjectAttachmentEditOptions(projectID: id, session: session)
            projectAttachmentEditReadError = nil
            projectAttachmentWriteError = nil
        } catch { projectAttachmentEditReadError = "Project attachments could not be loaded. Try again." }
    }

    func flushProjectNotesEdit() async -> Bool {
        await flushProjectNotesEdit(attachmentOpenClaim: nil)
    }

    private func flushProjectNotesEdit(attachmentOpenClaim: UUID?, fileAddClaim: UUID? = nil) async -> Bool {
        if let task = projectNotesFlushTask { return await task.value }
        // A delayed blur cannot install a fresh flush under Open's freeze and
        // make the captured Open await a task which refuses its own admission.
        guard (attachmentOpenClaim != nil || !projectAttachmentOpening),
              fileAddClaim != nil || (!projectFileAddOpening && projectFileImporterID == nil) else { return false }
        if !projectNotesExpanded || !projectNotesEditMode || !projectNotesEditLoaded {
            return projectNotesWriteRequest == nil && !retryNeeded
        }
        guard projectNotesEditReadError == nil, !projectNotesEditConflict,
              projectNotesEditError == nil, projectNotesWriteRequest == nil, !retryNeeded else { return false }
        guard projectNotesDirty else { return true }
        let id = UUID()
        let task = Task { await self.performProjectNotesFlush(attachmentOpenClaim: attachmentOpenClaim, fileAddClaim: fileAddClaim) }
        projectNotesFlushID = id
        projectNotesFlushTask = task
        let accepted = await task.value
        if projectNotesFlushID == id {
            projectNotesFlushTask = nil
            projectNotesFlushID = nil
        }
        return accepted
    }

    private func performProjectNotesFlush(attachmentOpenClaim: UUID?, fileAddClaim: UUID?) async -> Bool {
        // This captured Open may flush its already-present notes before reading
        // files, while the opening flag continues to refuse fresh Project work.
        let ownedOpen = attachmentOpenClaim.map {
            projectAttachmentOpenClaim == $0 && projectAttachmentOpening && projectFileOpenPresentation == nil
        } == true
        let ownedAdd = fileAddClaim.map {
            projectFileImportClaim?.id == $0 && projectFileAddOpening
                && projectFileImportClaim.map(projectFileImportCurrent) == true
        } == true
        guard projectActionsEnabled || ((ownedOpen || ownedAdd) && projectActionsCurrent),
              projectNotesExpanded, projectNotesEditMode,
              projectNotesEditLoaded, !busy else { return false }
        busy = true
        defer { finishOperation() }
        let id = projectHeader.text("id")
        let text = projectNotesDraft
        do {
            if !projectNotesEditOptionsCurrent
                || projectNotesEditOptions.text("revision") != projectDetail.text("mutationRevision") {
                try await readProjectNotesEditOptions()
            }
            guard projectNotesEditOptionsCurrent, !projectNotesEditConflict,
                  projectNotesEditOptions.flag("canEdit"), projectHeader.text("id") == id,
                  projectCurrent, projectNotesDraft == text else { return false }
            let project = projectNotesEditOptions.object("project")
            let expected: CoreObject = ["title": project.text("title"), "status": project.text("status"),
                                        "supportNotes": project["supportNotes"]!, "rev": project["rev"]!,
                                        "revBy": project["revBy"]!, "updatedAt": project.text("updatedAt")]
            let request = try json(["requestId": UUID().uuidString.lowercased(), "projectId": id,
                                    "text": text, "expected": expected])
            projectNotesWriteRequest = request
            projectNotesExpectedRaw = text
            let result = try await query("projectNotesWrite", [request])
            guard try acknowledgeProjectNotesWrite(result) else { return false }
        } catch {
            await handleProjectNotesWriteError(error)
            return false
        }
        do {
            try await readSelectedSurface()
            guard projectCurrent, projectNotesEditReadError == nil else { throw CocoaError(.coderReadCorrupt) }
            return true
        } catch {
            projectNotesEditReadError = error.localizedDescription
            return false
        }
    }

    @discardableResult private func acknowledgeProjectNotesWrite(_ result: CoreObject) throws -> Bool {
        guard projectNotesWriteRequest != nil, let expected = projectNotesExpectedRaw else {
            throw CocoaError(.coderReadCorrupt)
        }
        if result.count == 1 && result["blocked"] as? String == "" {
            projectNotesWriteRequest = nil
            projectNotesExpectedRaw = nil
            projectNotesEditOptionsCurrent = false
            retryNeeded = false
            projectNotesEditError = "Project Notes are no longer editable. Discard the draft to reload."
            return false
        }
        guard result.count == 2, result.text("id") == projectHeader.text("id"),
              result["supportNotes"] as? String == expected else { throw CocoaError(.coderReadCorrupt) }
        projectNotesEditBaseRaw = expected
        projectNotesEditLoaded = true
        projectNotesEditOptionsCurrent = false
        projectNotesWriteRequest = nil
        projectNotesExpectedRaw = nil
        retryNeeded = false
        projectNotesEditError = nil
        projectNotesEditReadError = nil
        error = nil
        return true
    }

    private func handleProjectNotesWriteError(_ failure: Error) async {
        if projectNotesWriteRequest != nil && isDefiniteRejection(failure) {
            projectNotesWriteRequest = nil
            projectNotesExpectedRaw = nil
            projectNotesEditOptionsCurrent = false
            retryNeeded = false
            projectNotesEditError = failure.localizedDescription
            do {
                try await readSelectedSurface()
            } catch { projectNotesEditReadError = error.localizedDescription }
        } else {
            retryNeeded = projectNotesWriteRequest != nil
            projectNotesEditError = failure.localizedDescription
            error = failure.localizedDescription
        }
    }

    func loadMoreProjectNotes() async {
        guard projectActionsEnabled, projectNotesExpanded, projectNotesCurrent,
              projectNotes.objects("blocks").count < projectNotes.number("total") else { return }
        busy = true
        defer { finishOperation() }
        let offset = projectNotes.objects("blocks").count
        let limit = min(pageSize, projectNotes.number("total") - offset)
        projectNotesLoadedDepth = offset + limit
        projectNotesCurrent = false
        do {
            let window = try await query("projectNotes", [projectHeader.text("id"), offset, limit, projectNotes.text("revision")])
            try validateProjectNotesWindow(window, against: projectNotes, count: limit)
            guard projectCurrent, projectHeader.text("id") == window.text("projectId"),
                  projectDetail.text("mutationRevision") == window.text("revision") else {
                throw CocoaError(.coderReadCorrupt)
            }
            projectNotes["blocks"] = projectNotes.objects("blocks") + window.objects("blocks")
            projectNotesCurrent = true
            projectNotesError = nil
        } catch { projectNotesError = error.localizedDescription }
    }

    var projectNotesReferenceEnabled: Bool {
        projectViewOpenEnabled && !appLock.concealed && projectNotesExpanded && !projectNotesEditMode
            && !projectViewOptionsPresented && !projectTaskSortPresented && !projectFiltersPresented
            && projectNotesCurrent && !projectNotesWritePending
            && projectNotes.text("revision") == projectDetail.text("mutationRevision")
    }

    func openProjectNotesReference(projectID: String, revision: String,
                                   blockIndex: Int, itemIndex: Int?, inlineIndex: Int) async {
        guard projectNotesReferenceEnabled, projectHeader.text("id") == projectID,
              projectNotes.text("revision") == revision else { return }
        let session = projectFilterSession
        projectNotesReferenceOpening = true
        projectNotesReferenceError = nil
        defer { projectNotesReferenceOpening = false }
        func sourceCurrent() -> Bool {
            selectedSurface == .project && projectFilterSession == session && projectCurrent
                && projectHeader.text("id") == projectID && projectNotesCurrent && projectNotesExpanded
                && !projectNotesEditMode && projectNotes.text("revision") == revision
                && projectDetail.text("mutationRevision") == revision && !appLock.concealed
                && !projectNotesDirty && !projectNotesWritePending && !retryNeeded && !taskPresented
                && !projectViewOptionsPresented && !projectTaskSortPresented && !projectFiltersPresented
        }
        func refuseCurrentSource() {
            if selectedSurface == .project, projectFilterSession == session,
               projectHeader.text("id") == projectID {
                projectNotesReferenceError = "This Notes link changed or is unavailable. Refresh Notes and try again."
            }
        }
        guard await flushProjectNotesEdit(), sourceCurrent(), !busy else {
            refuseCurrentSource()
            return
        }
        if taskRecoverySnapshot != nil || taskRecoveryCorrupt {
            taskRecoveryConflict = "A saved task draft needs a decision before following a Notes link."
            taskRecoveryGateVisible = true
            return
        }
        var input: CoreObject = ["projectId": projectID, "revision": revision,
                                 "blockIndex": blockIndex, "inlineIndex": inlineIndex]
        if let itemIndex { input["itemIndex"] = itemIndex }
        let target: CoreObject
        busy = true
        do {
            target = try await query("projectNotesReferenceTarget", [try json(input)])
            guard sourceCurrent(), target.count == 2,
                  ["task", "project"].contains(target.text("kind")),
                  !target.text("id").isEmpty, target.text("id").utf16.count <= 500 else {
                throw CocoaError(.coderReadCorrupt)
            }
        } catch {
            finishOperation()
            refuseCurrentSource()
            return
        }
        finishOperation()
        guard sourceCurrent(), !busy else {
            refuseCurrentSource()
            return
        }
        if target.text("kind") == "task" {
            prepareTaskPresentation(target.text("id"))
            await readTaskView()
            if taskError == nil && taskPresented && viewedTaskID == target.text("id") {
                NSLog("Native iOS Project Notes reference opened releaseCheck=v1.3.4/ios-project-notes-links destination=task")
            }
        } else if target.text("id") != projectID {
            await presentProject(["id": target.text("id")], caller: projectCaller)
            if projectCurrent && projectHeader.text("id") == target.text("id") {
                NSLog("Native iOS Project Notes reference opened releaseCheck=v1.3.4/ios-project-notes-links destination=project")
            }
        }
    }

    func retryProjectNotes() async {
        guard projectActionsEnabled, projectNotesExpanded else { return }
        busy = true
        defer { finishOperation() }
        await readProjectNotes()
    }

    private func readProjectNotes() async {
        projectNotesCurrent = false
        projectNotesError = nil
        projectNotesReferenceError = nil
        let id = projectHeader.text("id")
        for attempt in 0..<2 {
            do {
                guard projectCurrent, projectDetail.text("projectId") == id,
                      !projectDetail.text("mutationRevision").isEmpty else { throw CocoaError(.coderReadCorrupt) }
                var next = try await query("projectNotes", [id, 0, pageSize, ""])
                guard next.text("projectId") == id, !next.text("revision").isEmpty,
                      let total = next["total"] as? Int, total >= 0,
                      let firstBlocks = next["blocks"] as? [CoreObject],
                      firstBlocks.count == min(pageSize, total),
                      let readOnly = next["readOnly"] as? NSNumber,
                      CFGetTypeID(readOnly) == CFBooleanGetTypeID(),
                      readOnly.boolValue == projectDetail.flag("readOnly"),
                      ["ltr", "rtl"].contains(next.text("direction")),
                      validProjectNotesLabels(next.object("markdownLabels")) else {
                    throw CocoaError(.coderReadCorrupt)
                }
                if next.text("revision") != projectDetail.text("mutationRevision") {
                    if attempt == 0 {
                        await readProjectDetail()
                        continue
                    }
                    throw CocoaError(.coderReadCorrupt)
                }
                var blocks = next.objects("blocks")
                let target = min(projectNotesLoadedDepth, next.number("total"))
                while blocks.count < target {
                    let limit = min(pageSize, target - blocks.count)
                    let window = try await query("projectNotes", [id, blocks.count, limit, next.text("revision")])
                    try validateProjectNotesWindow(window, against: next, count: limit)
                    blocks += window.objects("blocks")
                }
                guard projectCurrent, projectHeader.text("id") == id,
                      projectDetail.text("mutationRevision") == next.text("revision") else {
                    throw CocoaError(.coderReadCorrupt)
                }
                next["blocks"] = blocks
                projectNotes = next
                projectNotesCurrent = true
                return
            } catch { projectNotesError = error.localizedDescription; return }
        }
    }

    private func validProjectNotesLabels(_ labels: CoreObject) -> Bool {
        labels.count == 3 && ["deletedTask", "deletedProject", "copyCode"].allSatisfy { labels[$0] is String }
    }

    private func validateProjectNotesWindow(_ window: CoreObject, against snapshot: CoreObject, count: Int) throws {
        guard window.text("projectId") == snapshot.text("projectId"),
              window.text("revision") == snapshot.text("revision"),
              window.number("total") == snapshot.number("total"),
              let readOnly = window["readOnly"] as? NSNumber,
              CFGetTypeID(readOnly) == CFBooleanGetTypeID(),
              readOnly.boolValue == snapshot.flag("readOnly"),
              window.text("direction") == snapshot.text("direction"),
              validProjectNotesLabels(window.object("markdownLabels")),
              ["deletedTask", "deletedProject", "copyCode"].allSatisfy({
                  window.object("markdownLabels").text($0) == snapshot.object("markdownLabels").text($0)
              }),
              window.objects("blocks").count == count else { throw CocoaError(.coderReadCorrupt) }
    }

    func openSearch() {
        guard !savedSearchWritePresented, ready, !settingsPersonCreatePresented, !settingsPersonEditPresented && !settingsTaxonomyActive && !generalPreferenceActive, !settingsPersonDeleteActive, !busy, !retryNeeded, !capturePresented, !areaPickerPresented, !taskPresented,
              !calendarComposerPresented, !mindSweepPresented, selectedSurface != .search else { return }
        if selectedSurface == .savedSearch {
            savedSearchReturns.append(SavedSearchReturn(id: savedSearchID, caller: savedSearchCaller,
                depth: savedSearchLoadedDepth, query: searchQuery, filters: searchFilters, searchCaller: searchCaller))
        } else { savedSearchReturns = [] }
        searchCaller = selectedSurface
        morePresented = false
        selectedSurface = .search
        searchQuery = ""
        searchFilters = [:]
        searchView = [:]
        requestSearch(delay: 0)
    }

    func closeSearch() async {
        guard !savedSearchWritePresented, selectedSurface == .search, !busy, !retryNeeded, !taskPresented else { return }
        selectedSurface = searchCaller
        if selectedSurface == .savedSearch, let previous = savedSearchReturns.popLast() {
            savedSearchID = previous.id
            savedSearchCaller = previous.caller
            savedSearchLoadedDepth = previous.depth
            savedSearch = [:]
            savedSearchCurrent = false
            searchQuery = previous.query
            searchFilters = previous.filters
            searchCaller = previous.searchCaller
        }
        invalidateSearch()
        searchLoading = false
        searchNeedsRead = false
        searchError = nil
        await refresh()
    }

    func setSearchQuery(_ text: String) {
        guard !savedSearchWritePresented, selectedSurface == .search, !retryNeeded, !taskPresented, text != searchQuery else { return }
        searchQuery = text
        requestSearch()
    }

    func setSearchFilters(_ filters: CoreObject) {
        guard !savedSearchWritePresented, selectedSurface == .search, !busy, !retryNeeded, !taskPresented, !filters.isEmpty else { return }
        searchFilters = filters
        requestSearch()
    }

    func removeSearchChip(_ key: String) {
        guard searchActionsEnabled,
              let chip = searchView.objects("activeChips").first(where: { $0.text("key") == key }) else { return }
        setSearchFilters(chip.object("clearedFilters"))
    }

    func retrySearch() {
        guard selectedSurface == .search, !busy, !retryNeeded, !taskPresented else { return }
        requestSearch(delay: 0)
    }

    func openSearchTask(_ id: String) async {
        guard searchActionsEnabled,
              let row = searchView.objects("tasks").first(where: { $0.text("id") == id }),
              row.flag("inStore"), row.object("tap").text("kind") == "editor" else { return }
        invalidateSearch()
        await openTask(row.object("tap").text("id"))
    }

    func completeSearchTask(_ id: String) async {
        guard searchActionsEnabled,
              let row = searchView.objects("tasks").first(where: { $0.text("id") == id }),
              row.flag("canComplete"), !row.flag("readOnly") else { return }
        invalidateSearch()
        error = nil
        await complete(id, taskRevision: row.text("taskRevision"))
    }

    private func invalidateSearch() {
        searchGeneration += 1
        searchTask?.cancel()
        searchNeedsRead = true
        searchLoading = selectedSurface == .search
    }

    private func requestSearch(delay: UInt64 = 200_000_000) {
        invalidateSearch()
        searchError = nil
        scheduleSearch(delay: delay)
    }

    private func scheduleSearch(delay: UInt64 = 200_000_000) {
        guard ready, selectedSurface == .search, !busy, !retryNeeded, !taskPresented else { return }
        let generation = searchGeneration
        searchTask = Task {
            do { try await Task.sleep(nanoseconds: delay) } catch { return }
            guard !Task.isCancelled, generation == searchGeneration, !busy, !retryNeeded, !taskPresented,
                  selectedSurface == .search else { return }
            await readSearch(generation: generation, ownsOperation: false)
        }
    }

    private func readSearch(generation: Int, ownsOperation: Bool) async {
        let text = searchQuery
        let filters = searchFilters
        do {
            let value = try await query("search", [try json([
                "query": text, "filters": filters.isEmpty ? NSNull() : filters as Any, "limit": 100])])
            guard generation == searchGeneration, selectedSurface == .search, !retryNeeded, !taskPresented,
                  ownsOperation || !busy else { return }
            // Empty input gets its entire default filter object from core. Never
            // synthesize defaults or copy an older response over newer input.
            if searchFilters.isEmpty { searchFilters = value.object("defaultFilters") }
            searchView = value
            publishedSearchGeneration = generation
            searchNeedsRead = false
            searchLoading = false
            searchError = nil
        } catch {
            guard generation == searchGeneration, selectedSurface == .search, !retryNeeded, !taskPresented,
                  ownsOperation || !busy else { return }
            searchNeedsRead = false
            searchLoading = false
            searchError = error.localizedDescription
        }
    }

    func openAreaPicker() async {
        guard ready, !settingsPersonCreatePresented, !settingsPersonEditPresented && !settingsTaxonomyActive && !generalPreferenceActive, !settingsPersonDeleteActive, !busy, !retryNeeded, !capturePresented, !taskPresented,
              !projectRenameEditing,
              !calendarComposerPresented, !mindSweepPresented else { return }
        UIApplication.shared.sendAction(#selector(UIResponder.resignFirstResponder), to: nil, from: nil, for: nil)
        busy = true
        defer { finishOperation() }
        do {
            area = try await query("areaFilter")
            areaPickerPresented = true
        } catch { self.error = error.localizedDescription }
