    func closeAreaPicker() {
        guard !busy, !retryNeeded else { return }
        areaPickerPresented = false
        if selectedSurface == .board && boardNeedsRead { scheduleBoardRead(delay: 0) }
        if selectedSurface == .contexts && !contextsCurrent { requestContextsRead(delay: 0) }
        if selectedSurface == .focus && !focusCurrent { requestFocusRead(delay: 0) }
    }

    func selectArea(_ next: CoreObject) async {
        guard ready, areaPickerPresented, !busy, !retryNeeded else { return }
        busy = true
        error = nil
        defer { finishOperation() }
        do {
            // This is core's final selection, never a native toggle/cycle.
            // The host journals it unchanged for exact recovery.
            _ = try await query("setAreaFilter", [try json(next)])
        } catch {
            retryNeeded = !isDefiniteRejection(error)
            self.error = error.localizedDescription
            return
        }
        do { try await readSelectedSurface() } catch { self.error = error.localizedDescription }
    }

    func loadMore() async {
        guard ready, selectedSurface == .inbox, !busy, !retryNeeded, items.count < inbox.number("total") else { return }
        busy = true
        defer { finishOperation() }
        do {
            let next = try await query("inboxView", [try json([
                "offset": items.count, "limit": pageSize, "revision": inbox.text("revision")])])
            guard next.text("revision") == inbox.text("revision") else { try await readInbox(); return }
            inbox["items"] = items + next.objects("items")
        } catch {
            // A minute or data revision can expire between windows. Restart the query, never mix revisions.
            do { try await readInbox() } catch { self.error = error.localizedDescription }
        }
    }

    func loadMoreFocus(_ key: String) async {
        guard focusActionsEnabled, let section = focus.objects("sections").first(where: { $0.text("key") == key }),
              section.objects("rows").count < section.number("rowTotal") else { return }
        focusLoadedDepth[key] = section.objects("rows").count + pageSize
        requestFocusRead(delay: 0)
    }

    private func visibleDescriptionReference(_ sourceID: String?, kind: String, id: String) -> Bool {
        guard let sourceID else { return false }
        let rows: [CoreObject]
        switch selectedSurface {
        case .focus where focusShowDetails:
            rows = focus.objects("sections").flatMap { $0.objects("rows") }
        case .waiting where waiting.flag("showDetails"):
            rows = waiting.objects("rows")
        case .someday where someday.flag("showDetails"):
            rows = someday.objects("items").filter { $0.text("type") == "task" }.map { $0.object("row") }
        default: return false
        }
        return rows.contains { row in
            row.text("id").utf8.elementsEqual(sourceID.utf8)
                && row.object("meta").object("description").objects("inline").contains { run in
                    run.text("type") == "link" && run.object("target").text("kind") == kind
                        && run.object("target").text("id").utf8.elementsEqual(id.utf8)
                }
        }
    }

    func openTask(_ id: String, descriptionSourceID: String? = nil) async {
        if selectedSurface == .project { guard await flushProjectNotesEdit() else { return } }
        guard ready, !settingsPersonCreatePresented, !settingsPersonEditPresented && !settingsTaxonomyActive && !generalPreferenceActive, !settingsPersonDeleteActive, !busy, !retryNeeded, !capturePresented, !areaPickerPresented, !taskPresented,
              !projectRenameEditing, selectedSurface != .trash else { return }
        if taskRecoverySnapshot != nil || taskRecoveryCorrupt
            || (taskAttachmentState != .none && taskAttachmentState != .discardedCleanup) {
            taskRecoveryConflict = taskRecoverySnapshot?.taskID == id
                ? nil : "A saved task draft needs a decision before another task can open."
            taskRecoveryGateVisible = true
            return
        }
        if selectedSurface == .review {
            guard reviewActionsEnabled, reviewTaskIDs.contains(id) else { return }
        }
        if selectedSurface == .board {
            guard boardActionsEnabled, boardView.objects("columns").contains(where: {
                $0.objects("cards").contains(where: { $0.object("row").text("id") == id })
            }) else { return }
        }
        if selectedSurface == .calendar { guard calendarActionsEnabled, calendarEditableTask(id) else { return } }
        if selectedSurface == .focus {
            guard focusActionsEnabled, visibleDescriptionReference(descriptionSourceID, kind: "task", id: id)
                || focus.objects("sections").contains(where: {
                $0.objects("rows").contains(where: { $0.text("id") == id })
            }) else { return }
        }
        if selectedSurface == .contexts {
            guard contextsActionsEnabled, contexts.objects("rows").contains(where: { $0.text("id") == id }) else { return }
        }
        if selectedSurface == .savedSearch {
            guard savedSearchActionsEnabled, savedSearch.objects("rows").contains(where: { $0.text("id") == id }) else { return }
        }
        if selectedSurface == .history {
            guard historyActionsEnabled, history.objects("items").contains(where: {
                $0.text("type") == "task" && $0.object("row").text("id") == id
            }) else { return }
        }
        if selectedSurface == .reference {
            guard referenceActionsEnabled, reference.objects("items").contains(where: {
                $0.text("type") == "task" && $0.object("row").text("id") == id
            }) else { return }
        }
        if selectedSurface == .someday {
            guard somedayActionsEnabled, visibleDescriptionReference(descriptionSourceID, kind: "task", id: id)
                || someday.objects("items").contains(where: {
                $0.text("type") == "task" && $0.object("row").text("id") == id
            }) else { return }
        }
        if selectedSurface == .waiting {
            guard waitingActionsEnabled, visibleDescriptionReference(descriptionSourceID, kind: "task", id: id)
                || waiting.objects("rows").contains(where: { $0.text("id") == id }) else { return }
        }
        if selectedSurface == .project {
            guard projectActionsEnabled, projectDetail.objects("items").contains(where: {
                $0.text("type") == "task" && $0.object("row").text("id") == id
            }) else { return }
        }
        prepareTaskPresentation(id, automaticTab: selectedSurface == .inbox ? "task" : "view")
        await readTaskView()
    }

    private func prepareTaskPresentation(_ id: String, initialTab: String = "view", automaticTab: String = "view") {
        taskOpeningIntent = taskRecoveryHydrating ? nil : [
            "rawMode": rawTaskOpenMode, "automaticTab": automaticTab,
            "explicitEdit": initialTab == "task"]
        taskPersonCreateReadRetry = nil
        taskPersonCreateReadError = nil
        taskRecoverySession = UUID().uuidString.lowercased()
        taskRecoveryGeneration = 0
        taskRecoveryCheckpointedGeneration = 0
        taskRecoveryTouched = []
        taskRecoveryChecklistTouched = false
        taskRecoveryAttachmentsOwned = false
        taskRecoveryCheckpointError = nil
        taskRecoverySaving = false
        resetTaskDestination()
        resetTaskTokens()
        resetTaskSchedule()
        resetTaskChecklistState()
        viewedTaskID = id
        taskInitialTab = initialTab
        taskView = [:]
        taskEditor = [:]
        taskOriginalDraft = [:]
        taskOriginalAttachments = []
        taskAttachments = []
        taskAttachmentRows = []
        taskLinkSheet = [:]
        taskLinkSheetError = nil
        taskLinkSubmitting = false
        taskSharePayload = nil
        taskShareError = nil
        invalidateTaskAttachmentOpen()
        taskAttachmentOpenError = nil
        taskTitleDraft = ""
        taskNoteDraft = ""
        taskEditorDraftDirection = ""
        taskLocationDraft = ""
        taskEstimateInput = ""
        taskEstimateResolvedInput = ""
        taskTimeSpentInput = ""
        taskTimeSpentResolvedInput = ""
        taskReferenceError = nil
        taskError = nil
        taskPresented = true
    }

    func closeTask() {
        guard !busy, !retryNeeded, !taskReferenceOpening, !taskAttachmentOpening, !taskPersonCreateOwed, !taskSavePending, taskChecklistWriteKind == nil,
              !taskChecklistReadPending, !taskScheduleUpdating else { return }
        guard !taskDirty else { return }
        Task { await discardCleanTaskSnapshotAndClose() }
    }

    func discardTask() {
        guard !busy, !retryNeeded, !taskReferenceOpening, !taskAttachmentOpening, !taskPersonCreateOwed, !taskSavePending, taskChecklistWriteKind == nil,
              !taskChecklistReadPending, !taskScheduleUpdating else { return }
        Task { await discardTaskRecoveryDraft(close: true) }
    }

    private func discardCleanTaskSnapshotAndClose(refreshCaller: Bool = true) async {
        guard !taskDirty else { return }
        if taskHasActiveAttachmentOwner {
            await saveTask()
            return
        }
        let wasBusy = busy
        busy = true
        taskRecoverySaving = true
        defer { busy = wasBusy; taskRecoverySaving = false }
        if taskRecoverySnapshot != nil {
            await flushTaskDraftCheckpoint()
            guard let host else { return }
            do {
                if try await host.readEditorDraft() != nil {
                    try await host.discardEditorDraft(expectedSession: taskRecoverySession)
                }
            }
            catch { taskRecoveryCheckpointError = error.localizedDescription; return }
            taskRecoverySnapshot = nil
        }
        dismissTask(refreshCaller: refreshCaller)
    }

    private func discardTaskAttachmentOwner(_ currentHost: CoreHost, close: Bool) async {
        guard taskAttachmentSaveRequest == nil, taskAttachmentState != .savedCleanup else {
            taskAttachmentError = "Task saved. Finish attachment cleanup before continuing."
            return
        }
        let wasBusy = busy
        busy = true
        taskAttachmentWorking = true
        taskRecoverySaving = true
        defer { busy = wasBusy; taskAttachmentWorking = false; taskRecoverySaving = false }
        await flushTaskDraftCheckpoint()
        do {
            try await readTaskAttachmentInventory(currentHost)
            let summary = taskAttachmentSummary
            guard host === currentHost, !summary.isEmpty else { throw CocoaError(.coderReadCorrupt) }
            let session = summary.text("sessionID")
            let discard = summary.object("discard")
            let requestID: String
            let reply: String
            if !discard.isEmpty {
                requestID = discard.text("requestId")
                if [3, 4, 5].contains(summary.number("version")) {
                    reply = try await currentHost.finishAttachmentDraftDiscardV3(expectedSession: session, requestId: requestID)
                } else { reply = try await currentHost.finishAttachmentDraftDiscard(expectedSession: session, requestId: requestID) }
            } else {
                let checkpoint = summary.object("checkpoint")
                guard checkpoint.text("sessionID") == session,
                      !taskPresented || session == taskRecoverySession else { throw CocoaError(.coderReadCorrupt) }
                let request: String
                if let retained = taskAttachmentDiscardRequest { request = retained; requestID = try decode(retained).text("requestId") }
                else {
                    requestID = UUID().uuidString.lowercased()
                    request = try json(["version": 1, "requestId": requestID, "sessionID": session,
                        "generation": checkpoint.number("generation")])
                    taskAttachmentDiscardRequest = request
                }
                if [3, 4, 5].contains(summary.number("version")) { reply = try await currentHost.discardAttachmentDraftV3(requestJSON: request) }
                else { reply = try await currentHost.discardAttachmentDraft(requestJSON: request) }
            }
            let value = try decode(reply)
            guard host === currentHost, value.text("sessionID") == session,
                  value.text("requestId") == requestID else { throw CancellationError() }
            try await readTaskAttachmentInventory(currentHost, adoptEditor: true)
            guard taskRecoverySnapshot == nil,
                  taskAttachmentState == .none || taskAttachmentState == .discardedCleanup else { throw CocoaError(.coderReadCorrupt) }
            if taskAttachmentSummary.isEmpty { taskAttachmentDiscardRequest = nil }
            taskRecoveryCorrupt = false
            taskRecoveryConflict = nil
            taskRecoveryCheckpointError = nil
            taskRecoveryGateVisible = taskAttachmentState != .none
            taskAttachmentError = nil
            taskRecoveryTouched = []
            taskRecoveryChecklistTouched = false
            taskRecoveryAttachmentsOwned = false
            taskAttachmentCheckpointFailed = nil
            taskAttachmentCheckpointDesired = nil
            if close && taskPresented { dismissTask() }
            Task { [currentHost] in await currentHost.recordEditorAttachmentAcknowledgment(operation: "discard") }
        } catch {
            // An exact decision may have detached the editor before cleanup
            // refused. Reread the host's actual phase; never infer release.
            try? await readTaskAttachmentInventory(currentHost, adoptEditor: true)
            taskAttachmentError = error.localizedDescription
            taskRecoveryGateVisible = true
            if taskAttachmentState == .discardedCleanup, taskRecoverySnapshot == nil {
                taskAttachmentCheckpointFailed = nil
                taskAttachmentCheckpointDesired = nil
            }
            if close, taskAttachmentState == .discardedCleanup, taskRecoverySnapshot == nil, taskPresented { dismissTask() }
        }
    }

    func discardTaskRecoveryDraft(close: Bool = false) async {
        guard !taskRecoverySaving, let host else { return }
        cancelTaskFileImport()
        let independentOrdinary = taskAttachmentState == .discardedCleanup && taskAttachmentHasIndependentDraft
        if (!taskAttachmentSummary.isEmpty || taskAttachmentState == .blocked) && !independentOrdinary {
            await discardTaskAttachmentOwner(host, close: close)
            return
        }
        let wasBusy = busy
        busy = true
        taskRecoverySaving = true
        defer { busy = wasBusy; taskRecoverySaving = false }
        await flushTaskDraftCheckpoint()
        do {
            if taskRecoveryCorrupt { try await host.discardCorruptEditorDraft() }
            else if let snapshot = taskRecoverySnapshot, try await host.readEditorDraft() != nil {
                try await host.discardEditorDraft(expectedSession: snapshot.sessionID)
            }
            taskRecoverySnapshot = nil
            taskRecoveryCorrupt = false
            taskRecoveryConflict = nil
            taskRecoveryReviewOptions = [:]
            taskRecoveryCheckpointError = nil
            taskRecoveryGateVisible = taskAttachmentState != .none
            taskRecoveryTouched = []
            taskRecoveryChecklistTouched = false
            taskRecoveryAttachmentsOwned = false
            NSLog("Native iOS editor recovery outcome=discarded releaseCheck=v1.3.4/ios-editor-draft-recovery")
            if close && taskPresented { dismissTask() }
        } catch {
            taskRecoveryCheckpointError = error.localizedDescription
            taskRecoveryGateVisible = true
        }
    }

    func keepTaskRecoveryForLater() async {
        guard !taskRecoverySaving else { return }
        cancelTaskFileImport()
        taskOwnedMenuAction = nil
        taskOwnedMenuSelection = nil
        let wasBusy = busy
        busy = true
        taskRecoverySaving = true
        defer { busy = wasBusy; taskRecoverySaving = false }
        await flushTaskDraftCheckpoint()
        guard taskRecoveryCheckpointError == nil else {
            taskRecoveryGateVisible = true
            return
        }
        taskRecoveryGateVisible = false
        if taskPresented { dismissTask() }
    }

    func showTaskRecovery() {
        guard taskRecoveryAvailable else { return }
        taskRecoveryGateVisible = true
    }

    func restoreTaskRecovery() async {
        guard ready, !appLock.concealed, !busy, let host,
              taskRecoverySnapshot != nil || taskRecoveryCorrupt else { return }
        guard !taskRecoveryCorrupt, var snapshot = taskRecoverySnapshot else {
            taskRecoveryConflict = "The saved task draft is unreadable."
            return
        }
        guard taskAttachmentCheckpointFailed == nil else {
            taskRecoveryConflict = "Retry the latest draft changes before reopening."
            return
        }
        let owned = !taskAttachmentSummary.isEmpty && taskAttachmentSummary.text("sessionID") == snapshot.sessionID
        func requireOwnedRestore() throws {
            guard !owned || (self.host === host && !appLock.concealed && !Task.isCancelled
                && taskRecoverySnapshot == snapshot && taskRecoverySession == snapshot.sessionID
                && taskRecoveryGeneration == snapshot.generation) else { throw CancellationError() }
        }
        busy = true
        taskRecoveryConflict = nil
        taskRecoveryReviewOptions = [:]
        defer { finishOperation() }
        do {
            if owned {
                guard [3, 4, 5].contains(taskAttachmentSummary.number("version")),
                      taskAttachmentSummary.object("discard").isEmpty,
                      taskAttachmentState != .savedCleanup else { throw CocoaError(.coderReadCorrupt) }
                _ = try await host.recoverAttachmentDraftV3(expectedSession: snapshot.sessionID)
                try requireOwnedRestore()
                guard self.host === host, !appLock.concealed else { throw CancellationError() }
                guard let recovered = try await host.readEditorDraft(), recovered.sessionID == snapshot.sessionID,
                      recovered.taskID == snapshot.taskID, self.host === host, !appLock.concealed else { throw CancellationError() }
                snapshot = recovered
                taskRecoverySnapshot = recovered
                taskRecoveryGeneration = recovered.generation
                taskRecoveryCheckpointedGeneration = recovered.generation
                try await readTaskAttachmentInventory(host)
                try requireOwnedRestore()
            }
            let payload = try decode(snapshot.payloadJSON)
            guard [1, 2].contains(payload.number("version")), payload.text("taskID") == snapshot.taskID,
                  ["task", "view"].contains(payload.text("tab")),
                  let touchedBase = payload["touchedBase"] as? CoreObject,
                  let edited = payload["edited"] as? CoreObject,
                  let raw = payload["raw"] as? CoreObject,
                  let queue = payload["scheduleEdits"] as? [CoreObject],
                  let tokens = raw["tokens"] as? [String: String],
                  let tokenCanonical = raw["tokenCanonical"] as? [String: String],
                  let tokenResolved = raw["tokenResolved"] as? [String: String],
                  let tokenEdited = raw["tokenEdited"] as? [String],
                  let checklistInputs = raw["checklistInputs"] as? [String: String],
                  let recurrenceInputs = raw["recurrenceInputs"] as? [String: String],
                  let recurrenceOwned = raw["recurrenceOwned"] as? [String],
                  let recurrenceCommitRequested = raw["recurrenceCommitRequested"] as? [String],
                  Set(edited.keys) == Set(touchedBase.keys),
                  ["title", "note", "location", "estimate", "estimateResolved", "timeSpent", "timeSpentResolved",
                   "checklistAppend", "relativeAmount", "relativeUnit"].allSatisfy({ raw[$0] is String }),
                  raw["relativeOwned"] is Bool, raw["relativeCommitRequested"] is Bool else {
                throw CocoaError(.coderReadCorrupt)
            }
            let hasAttachments = payload.number("version") == 2
            let savedAttachments = payload["attachmentsBase"] as? [CoreObject]
            let editedAttachments = payload["attachments"] as? [CoreObject]
            let savedLinkSheet = payload["linkSheet"] as? CoreObject
            guard !hasAttachments || (payload["attachmentsOwned"] as? Bool == true
                && savedAttachments != nil && editedAttachments != nil && savedLinkSheet != nil) else {
                throw CocoaError(.coderReadCorrupt)
            }
            if let sheet = savedLinkSheet, !sheet.isEmpty {
                guard Set(sheet.keys) == Set(sheet["editing"] == nil ? ["id", "text"] : ["id", "text", "editing"]),
                      let sheetID = sheet["id"] as? String,
                      sheetID == UUID(uuidString: sheetID)?.uuidString.lowercased(),
                      let text = sheet["text"] as? String, text.utf16.count <= 32_000 else {
                    throw CocoaError(.coderReadCorrupt)
                }
                if let editing = sheet["editing"] as? CoreObject {
                    guard Set(editing.keys) == Set(["attachmentId", "title", "uri"]),
                          let target = editedAttachments?.first(where: { $0.text("id") == editing.text("attachmentId") }),
                          target.text("kind") == "link", target.text("title") == editing.text("title"),
                          target.text("uri") == editing.text("uri") else { throw CocoaError(.coderReadCorrupt) }
                }
            }
            var check: CoreObject = ["id": snapshot.taskID, "touchedBase": touchedBase]
            if let base = payload["scheduleBase"] { check["scheduleBase"] = base }
            if let base = payload["recurrenceBase"] { check["recurrenceBase"] = base }
            if let base = payload["checklistBase"] { check["checklistBase"] = base }
            if let savedAttachments, let editedAttachments {
                check["attachmentsBase"] = savedAttachments
                check["attachments"] = editedAttachments
            }
            let ready: CoreObject
            if owned {
                let envelope = try decode(try await host.checkAttachmentDraftResumeV3(expectedSession: snapshot.sessionID,
                    expectedGeneration: snapshot.generation))
                try requireOwnedRestore()
                guard self.host === host, !appLock.concealed, envelope.number("version") == 1,
                      try json(envelope.object("checkpoint")) == json(try decode(String(decoding: JSONEncoder().encode(snapshot), as: UTF8.self))) else {
                    throw CancellationError()
                }
                ready = envelope.object("ready")
            } else { ready = try await query("taskEditorResumeCheck", [try json(check)]) }
            guard ready.text("kind") == "ready", let fresh = ready["freshDraft"] as? CoreObject,
                  let freshChecklist = ready["freshChecklistBase"] as? [CoreObject],
                  let freshAttachments = ready["freshAttachmentsBase"] as? [CoreObject],
                  let freshSchedule = ready["freshScheduleBase"] as? CoreObject,
                  let freshRecurrence = ready["freshRecurrenceBase"] as? CoreObject else {
                throw CocoaError(.coderReadCorrupt)
            }
            try requireOwnedRestore()
            let freshEditor = try await query("editorModel", [snapshot.taskID])
            try requireOwnedRestore()
            guard !freshEditor.flag("readOnly"),
                  taskSaveFields.allSatisfy({ taskDraftValuesEqual(freshEditor.object("draft")[$0], fresh[$0]) }),
                  (taskRecoveryScheduleFields + taskRecurrenceFields + taskRecoveryLifecycleFields + ["timeSpentMinutes"])
                    .allSatisfy({ taskDraftValuesEqual(freshEditor.object("draft")[$0], fresh[$0]) }) else {
                throw CocoaError(.coderReadCorrupt)
            }
            try await readTaskEditorLabels(freshEditor)
            try requireOwnedRestore()
            let restoredChecklist = payload["checklistValue"] as? [CoreObject] ?? freshChecklist
            let restoredEditor: CoreObject
            if edited.isEmpty { restoredEditor = freshEditor }
            else {
                restoredEditor = try await query("editDraft", [try json([
                    "id": snapshot.taskID, "draft": freshEditor.object("draft"),
                    "checklist": restoredChecklist,
                    "edit": ["type": "fields", "patch": edited]])])
                try requireOwnedRestore()
            }
            let checklistResult = try await query("checklistEdit", [try json([
                "id": snapshot.taskID, "draft": restoredEditor.object("draft"),
                "checklist": restoredChecklist])])
            try requireOwnedRestore()
            guard let checklist = checklistResult["checklist"] as? [CoreObject],
                  !checklistResult.object("field").isEmpty else { throw CocoaError(.coderReadCorrupt) }
            let finalEditor = try await query("editDraft", [try json([
                "id": snapshot.taskID, "draft": checklistResult.object("draft"), "checklist": checklist])])
            try requireOwnedRestore()
            var restoredQueue: [TaskScheduleEdit] = []
            for item in queue {
                guard let id = item["id"] as? Int, id > 0,
                      let control = item["control"] as? String,
                      let edit = item["edit"] as? CoreObject,
                      let coalesces = item["coalesces"] as? Bool else { throw CocoaError(.coderReadCorrupt) }
                restoredQueue.append(TaskScheduleEdit(id: id, control: control, edit: edit, coalesces: coalesces))
            }
            var restoredInputs: [Int: String] = [:]
            for (index, value) in checklistInputs {
                guard let parsed = Int(index), parsed >= 0, parsed < checklist.count else { throw CocoaError(.coderReadCorrupt) }
                restoredInputs[parsed] = value
            }
            try requireOwnedRestore()
            taskRecoveryHydrating = true
            prepareTaskPresentation(snapshot.taskID, initialTab: payload.text("tab"))
            taskRecoverySession = snapshot.sessionID
            taskRecoveryGeneration = snapshot.generation
            taskRecoveryCheckpointedGeneration = snapshot.generation
            taskRecoverySnapshot = snapshot
            taskRecoveryTouched = Set(touchedBase.keys)
            taskRecoveryChecklistTouched = payload["checklistBase"] != nil
            taskRecoveryAttachmentsOwned = hasAttachments
            taskEditor = finalEditor
            taskOriginalDraft = fresh
            for (field, value) in touchedBase { taskOriginalDraft[field] = value }
            taskOriginalSchedule = payload.object("scheduleBase").isEmpty ? freshSchedule : payload.object("scheduleBase")
            taskOriginalRecurrence = payload.object("recurrenceBase").isEmpty ? freshRecurrence : payload.object("recurrenceBase")
            taskChecklistLoaded = true
            taskOriginalChecklist = payload["checklistBase"] as? [CoreObject] ?? freshChecklist
            taskChecklist = checklist
            taskOriginalAttachments = savedAttachments ?? freshAttachments
            taskAttachments = editedAttachments ?? freshAttachments
            taskLinkSheet = savedLinkSheet ?? [:]
            taskLinkSheetError = nil
            taskChecklistField = checklistResult.object("field")
            taskChecklistInputs = taskRecoveryChecklistTouched ? restoredInputs : [:]
            taskChecklistAppendInput = taskRecoveryChecklistTouched ? raw.text("checklistAppend") : ""
            taskTitleDraft = taskRecoveryTouched.contains("title") ? raw.text("title") : finalEditor.object("draft").text("title")
            taskNoteDraft = taskRecoveryTouched.contains("description") ? raw.text("note") : finalEditor.object("draft").text("description")
            taskLocationDraft = taskRecoveryTouched.contains("location") ? raw.text("location") : finalEditor.object("draft").text("location")
            resetTaskEstimateInput()
            if taskRecoveryTouched.contains("timeEstimate") {
                taskEstimateInput = raw.text("estimate")
                taskEstimateResolvedInput = raw.text("estimateResolved")
            }
            resetTaskTimeSpentInput()
            if taskRecoveryTouched.contains("timeSpentMinutes") {
                taskTimeSpentInput = raw.text("timeSpent")
                taskTimeSpentResolvedInput = raw.text("timeSpentResolved")
            }
            initializeTaskTokens()
            for field in taskTokenFields where taskRecoveryTouched.contains(field) {
                guard let input = tokens[field], let canonical = tokenCanonical[field] else {
                    throw CocoaError(.coderReadCorrupt)
                }
                taskTokenInputs[field] = input
                taskTokenCanonical[field] = canonical
                taskTokenResolvedInputs[field] = tokenResolved[field]
                if tokenEdited.contains(field) { taskTokenEdited.insert(field) }
            }
            if taskRecoveryTouched.contains(where: { taskRecoveryScheduleFields.contains($0) }) {
                taskRelativeAmountInput = raw.text("relativeAmount")
                taskRelativeUnitInput = raw.text("relativeUnit")
                taskRelativeInputOwned = raw.flag("relativeOwned")
                taskRelativeInputCommitRequested = raw.flag("relativeCommitRequested")
            } else { synchronizeTaskRelativeInput() }
            if taskRecoveryTouched.contains(where: { taskRecurrenceFields.contains($0) }) {
                taskRecurrenceInputs = recurrenceInputs
                taskRecurrenceInputOwned = Set(recurrenceOwned)
                taskRecurrenceInputCommitRequested = Set(recurrenceCommitRequested)
            } else { synchronizeTaskRecurrenceInputs() }
            taskScheduleEdits = restoredQueue
            taskScheduleSequence = restoredQueue.map(\.id).max() ?? 0
            taskSchedulePending = !restoredQueue.isEmpty
            taskScheduleFailedID = payload["scheduleFailedID"] as? Int
            taskScheduleFailure = taskScheduleFailedID == nil ? nil : CocoaError(.coderReadCorrupt)
            taskRecoveryHydrating = false
            if !owned { taskRecoveryGateVisible = false }
            taskRecoveryConflict = nil
            taskRecoveryReviewOptions = [:]
            try await refreshTaskAttachmentRows()
            try requireOwnedRestore()
            NSLog("Native iOS editor recovery outcome=resumed releaseCheck=v1.3.4/ios-editor-draft-recovery")
            if owned { await readRecoveredTaskPreview(); try requireOwnedRestore() }
            for field in taskTokenFields { requestTaskTokenRead(field, delay: 0) }
            if taskScheduleFailure == nil { startTaskSchedulePump() }
            if !owned { await readRecoveredTaskPreview() }
            if owned {
                try requireOwnedRestore()
                // The gate owns the SwiftUI restore task. Dismiss only after
                // its final await so removing that view cannot cancel hydration.
                taskRecoveryGateVisible = false
            }
        } catch {
            taskRecoveryHydrating = false
            taskRecoveryGateVisible = true
            if (!owned || (self.host === host && !appLock.concealed && !Task.isCancelled)),
               let editor = try? await query("editorModel", [snapshot.taskID]),
               !owned || (self.host === host && !appLock.concealed && !Task.isCancelled) {
                taskRecoveryReviewOptions = editor.object("options")
                try? await readTaskEditorLabels(editor)
            }
            taskRecoveryConflict = error.localizedDescription
            NSLog("Native iOS editor recovery outcome=retained releaseCheck=v1.3.4/ios-editor-draft-recovery")
        }
    }

    private func readRecoveredTaskPreview() async {
        guard taskPresented, let _ = taskRecoverySnapshot else { return }
        let session = taskRecoverySession
        let id = viewedTaskID
        let currentHost = host
        let owned = taskHasActiveAttachmentOwner
        do {
            let view = try await query("taskView", [try json([
                "id": id, "draft": taskDraft, "checklist": taskChecklist,
                "attachments": taskAttachments, "offset": 0, "limit": pageSize])])
            if taskPresented, taskRecoverySession == session, viewedTaskID == id,
               !owned || (host === currentHost && !appLock.concealed && !Task.isCancelled) { taskView = view }
        } catch { taskError = error.localizedDescription }
    }

    private func dismissTask(refreshCaller: Bool = true) {
        cancelTaskFileImport()
        // Resetting the checklist publishes a value. Close must never turn
        // that reset into a new checkpoint or replace a Keep-for-later draft.
        taskRecoveryHydrating = true
        taskPresented = false
        taskEditor = [:]
        taskOpeningIntent = nil
        resetTaskDestination()
        resetTaskTokens()
        resetTaskSchedule()
        resetTaskChecklistState()
        taskOriginalAttachments = []
        taskAttachments = []
        taskAttachmentRows = []
        taskLinkSheet = [:]
        taskLinkSheetError = nil
        taskLinkSubmitting = false
        taskSharePayload = nil
        taskShareError = nil
        invalidateTaskAttachmentOpen()
        taskAttachmentOpenError = nil
        viewedTaskID = ""
        taskRecoveryHydrating = false
        if taskRecoverySnapshot == nil {
            taskRecoveryTouched = []
            taskRecoveryChecklistTouched = false
            taskRecoveryAttachmentsOwned = false
        }
        // Reset can commit while the editor stays open; Close and Discard must
        // also refresh the caller, including its status membership and counts.
        if refreshCaller { Task { await refresh() } }
    }

    private func resetTaskChecklistState() {
        taskChecklistSession += 1
        taskChecklistLoaded = false
        taskChecklist = []
        taskOriginalChecklist = []
        taskChecklistField = [:]
        taskChecklistInputs = [:]
        taskChecklistAppendInput = ""
        taskChecklistFocusIndex = nil
        taskChecklistWriteKind = nil
        taskChecklistWriteRequest = nil
        taskChecklistResetAcknowledgment = nil
        taskChecklistReadPending = false
    }

    func setTaskChecklistInput(_ index: Int, text: String) {
        guard taskPresented, taskChecklistLoaded, !busy, !retryNeeded, !taskSavePending, !taskRecoverySaving,
              taskChecklistWriteKind == nil, !taskChecklistReadPending,
              index >= 0, index < taskChecklist.count else { return }
        if text == taskChecklist[index].text("title") { taskChecklistInputs.removeValue(forKey: index) }
        else { taskChecklistInputs[index] = text }
        taskRecoveryOwn(checklist: true)
    }

    private func applyTaskChecklistEdit(_ edit: CoreObject?, id: String, session: Int) async throws -> Bool {
        guard taskPresented, viewedTaskID == id, taskChecklistSession == session else { throw CancellationError() }
        var input: CoreObject = ["id": id, "draft": taskDraft, "checklist": taskChecklist]
        if let edit { input["edit"] = edit }
        let result = try await query("checklistEdit", [try json(input)])
        guard taskPresented, viewedTaskID == id, taskChecklistSession == session else { throw CancellationError() }
        guard !result.object("draft").isEmpty, result["checklist"] is [CoreObject],
              !result.object("field").isEmpty else { throw CocoaError(.coderReadCorrupt) }
        let editor = try await query("editDraft", [try json([
            "id": id, "draft": result.object("draft"), "checklist": result.objects("checklist")])])
        guard taskPresented, viewedTaskID == id, taskChecklistSession == session else { throw CancellationError() }
        taskEditor = editor
        taskChecklist = result.objects("checklist")
        taskChecklistField = result.object("field")
        if let focusID = result["focusId"] as? String {
            taskChecklistFocusIndex = taskChecklist.firstIndex { $0.text("id") == focusID }
        } else { taskChecklistFocusIndex = nil }
        return result.flag("changed")
    }

    private func flushTaskChecklistInputs(id: String, session: Int, append: Bool = true) async throws {
        // Reverse order keeps global indexes stable when a pasted multiline title
        // inserts rows after its source item.
        for _ in 0..<8 {
            for index in taskChecklistInputs.keys.sorted(by: >) {
                guard let text = taskChecklistInputs[index] else { continue }
                guard index < taskChecklist.count else { throw CocoaError(.coderReadCorrupt) }
                _ = try await applyTaskChecklistEdit(["kind": "rename", "index": index, "text": text], id: id, session: session)
                if taskChecklistInputs[index] == text {
                    taskChecklistInputs.removeValue(forKey: index)
                    checkpointTaskDraft()
                }
            }
            if append, !taskChecklistAppendInput.isEmpty {
                let title = taskChecklistAppendInput
                _ = try await applyTaskChecklistEdit(["kind": "append", "title": title], id: id, session: session)
                if taskChecklistAppendInput == title {
                    taskChecklistAppendInput = ""
                    checkpointTaskDraft()
                }
            }
            if taskChecklistInputs.isEmpty && (!append || taskChecklistAppendInput.isEmpty) { return }
        }
        throw CocoaError(.coderReadCorrupt)
    }

    func editTaskChecklist(_ edit: CoreObject, refreshPreview: Bool = false) async {
        guard taskPresented, taskChecklistLoaded, !taskEditor.flag("readOnly"), !busy, !retryNeeded,
              taskChecklistWriteKind == nil, !taskChecklistReadPending else { return }
        let id = viewedTaskID
        let session = taskChecklistSession
        taskRecoveryOwn(checklist: true)
        busy = true
        taskError = nil
        defer { finishOperation() }
        do {
            try await flushTaskChecklistInputs(id: id, session: session, append: edit.text("kind") != "append")
            _ = try await applyTaskChecklistEdit(edit, id: id, session: session)
            if edit.text("kind") == "append", taskChecklistAppendInput == edit.text("title") {
                taskChecklistAppendInput = ""
                checkpointTaskDraft()
            }
            if refreshPreview { Task { await readTaskView() } }
        } catch {
            if taskPresented, viewedTaskID == id, taskChecklistSession == session {
                taskError = error.localizedDescription
            }
        }
    }

    func appendTaskChecklist() async {
        let title = taskChecklistAppendInput
        guard !title.isEmpty else { return }
        await editTaskChecklist(["kind": "append", "title": title], refreshPreview: true)
    }

    private func validTaskChecklistResetResult(_ result: CoreObject, id: String) -> Bool {
        result.text("id") == id && result["checklistBase"] is [CoreObject]
            && (result["status"] as? String)?.isEmpty == false
            && (result["completedAt"] is String || result["completedAt"] is NSNull)
            && result["isFocusedToday"] is Bool
    }

    private func acceptTaskChecklistReset(_ result: CoreObject, id: String, session: Int) async throws {
        guard taskPresented, viewedTaskID == id, taskChecklistSession == session,
              validTaskChecklistResetResult(result, id: id),
              let savedStatus = result["status"] as? String,
              let focusedToday = result["isFocusedToday"] as? Bool else {
            throw CocoaError(.coderReadCorrupt)
        }
        let completedAt: String
        if let storedDate = result["completedAt"] as? String { completedAt = storedDate }
        else if result["completedAt"] is NSNull { completedAt = "" }
        else { throw CocoaError(.coderReadCorrupt) }
        if taskChecklistResetAcknowledgment == nil {
            let originalStatus = taskOriginalDraft.text("status")
            var original = taskOriginalDraft
            original["status"] = savedStatus
            original["completedAt"] = completedAt
            original["focusedToday"] = focusedToday
            taskOriginalDraft = original
            taskOriginalChecklist = result.objects("checklistBase")
            if taskDraft.text("status") == originalStatus {
                var editor = taskEditor
                var draft = editor.object("draft")
                draft["status"] = savedStatus
                draft["completedAt"] = completedAt
                draft["focusedToday"] = focusedToday
                editor["draft"] = draft
                taskEditor = editor
            }
            taskChecklistResetAcknowledgment = result
        }
        taskChecklistReadPending = true
        _ = try await applyTaskChecklistEdit(["kind": "uncheckAll"], id: id, session: session)
        taskChecklistReadPending = false
        taskChecklistResetAcknowledgment = nil
        taskError = nil
        Task { await readTaskView() }
    }

    func resetTaskChecklist() async {
        guard taskPresented, taskChecklistLoaded, !taskEditor.flag("readOnly"), !busy, !retryNeeded,
              taskChecklistWriteKind == nil, !taskChecklistReadPending else { return }
        if taskRecoverySnapshot != nil {
            guard !taskDirty else {
                taskRecoveryConflict = "Save or discard this task draft before resetting its checklist."
                taskRecoveryGateVisible = true
                return
            }
            let owned = taskHasActiveAttachmentOwner
            let currentHost = host, taskID = viewedTaskID, caller = selectedSurface
            let oldSession = taskRecoverySession, tab = taskInitialTab
            await discardTaskRecoveryDraft()
            guard taskRecoverySnapshot == nil, taskRecoveryCheckpointError == nil else { return }
            if owned {
                guard host === currentHost, taskPresented, viewedTaskID == taskID,
                      taskRecoverySession == oldSession, selectedSurface == caller, !appLock.concealed,
                      !Task.isCancelled, taskAttachmentState == .none || taskAttachmentState == .discardedCleanup else { return }
                prepareTaskPresentation(taskID, initialTab: tab)
                let freshSession = taskRecoverySession
                await readTaskView()
                guard host === currentHost, taskPresented, viewedTaskID == taskID,
                      taskRecoverySession == freshSession, selectedSurface == caller, !appLock.concealed,
                      !Task.isCancelled, !taskEditor.isEmpty, !taskEditor.flag("readOnly"),
                      taskChecklistLoaded, !busy, !retryNeeded else { return }
            } else {
                taskRecoverySession = UUID().uuidString.lowercased()
                taskRecoveryGeneration = 0
                taskRecoveryCheckpointedGeneration = 0
            }
        }
        let id = viewedTaskID
        let session = taskChecklistSession
        busy = true
        taskError = nil
        defer { finishOperation() }
        do {
            try await resolveTaskEditorInputs()
            try await flushTaskChecklistInputs(id: id, session: session)
            let request: CoreObject = ["id": id, "requestId": UUID().uuidString.lowercased(),
                                       "checklistBase": taskOriginalChecklist]
            let payload = try json(request)
            taskChecklistWriteRequest = payload
            taskChecklistWriteKind = "reset"
            let result = try await query("checklistReset", [payload])
            guard validTaskChecklistResetResult(result, id: id) else {
                throw CocoaError(.coderReadCorrupt)
            }
            taskChecklistWriteKind = nil
            taskChecklistWriteRequest = nil
            retryNeeded = false
            try await acceptTaskChecklistReset(result, id: id, session: session)
        } catch {
            if isDefiniteRejection(error) {
                taskChecklistWriteKind = nil
                taskChecklistWriteRequest = nil
            }
            retryNeeded = taskChecklistWriteKind != nil
            taskError = error.localizedDescription
        }
    }

    func retryTaskChecklistRead() async {
        guard !busy, taskChecklistReadPending, let result = taskChecklistResetAcknowledgment else { return }
        busy = true
        defer { finishOperation() }
        do { try await acceptTaskChecklistReset(result, id: viewedTaskID, session: taskChecklistSession) }
        catch { taskError = error.localizedDescription }
    }

    @Published private(set) var referenceProjectNextActionPresented = false
    @Published private(set) var referenceProjectNextActionOptions: CoreObject = [:]
    @Published private(set) var referenceProjectNextActionCandidates: [CoreObject] = []
    @Published private(set) var referenceProjectNextActionText = ""
    @Published private(set) var referenceProjectNextActionCanSave = false
    @Published private(set) var referenceProjectNextActionReading = false
    @Published private(set) var referenceProjectNextActionError: String?
    private var referenceProjectNextActionOrigin: CoreObject = [:]
    private var referenceProjectNextActionRequest: String?
    private var referenceProjectNextActionGeneration = 0
    private var referenceProjectNextActionInputGeneration = 0
    private var referenceProjectNextActionReadTask: Task<Void, Never>?
    private var referenceProjectNextActionInputTask: Task<Void, Never>?
    private var referenceProjectNextActionEditID: String?
    var referenceProjectNextActionPending: Bool { referenceProjectNextActionRequest != nil }
    var referenceProjectNextActionControlsEnabled: Bool {
        ready && referenceProjectNextActionPresented && !busy && !retryNeeded
            && !referenceProjectNextActionPending && !referenceProjectNextActionReading
            && !referenceProjectNextActionOptions.isEmpty && referenceProjectNextActionError == nil
    }

    private func queueReferenceProjectNextAction(kind: String, submitted: CoreObject) {
        guard selectedSurface == .reference else { return }
        invalidateReferenceProjectNextAction()
        referenceProjectNextActionOrigin = ["kind": kind, "id": submitted.text("id"), "requestId": submitted.text("requestId")]
    }

    func presentQueuedReferenceProjectNextAction() {
        guard !referenceProjectNextActionOrigin.isEmpty, !referenceProjectNextActionPresented,
              ready, selectedSurface == .reference, !busy, !retryNeeded, !taskPresented, !taskStatusMenuPresented else { return }
        referenceProjectNextActionPresented = true
        referenceProjectNextActionReadTask = Task { await readReferenceProjectNextAction() }
    }

    func dismissReferenceProjectNextAction() {
        guard !busy, !referenceProjectNextActionPending else { return }
        invalidateReferenceProjectNextAction()
    }

    func referenceProjectNextActionOwnerChanged() {
        guard !referenceProjectNextActionPending else { return }
        if selectedSurface != .reference || taskPresented || appLock.concealed { invalidateReferenceProjectNextAction() }
    }

    private func invalidateReferenceProjectNextAction() {
        referenceProjectNextActionGeneration += 1
        referenceProjectNextActionInputGeneration += 1
        referenceProjectNextActionReadTask?.cancel()
        referenceProjectNextActionReadTask = nil
        referenceProjectNextActionInputTask?.cancel()
        referenceProjectNextActionInputTask = nil
        referenceProjectNextActionPresented = false
        referenceProjectNextActionOptions = [:]
        referenceProjectNextActionCandidates = []
        referenceProjectNextActionOrigin = [:]
        referenceProjectNextActionText = ""
        referenceProjectNextActionCanSave = false
        referenceProjectNextActionReading = false
        referenceProjectNextActionError = nil
    }

    func readReferenceProjectNextAction(more: Bool = false) async {
        guard referenceProjectNextActionPresented, selectedSurface == .reference,
              !referenceProjectNextActionPending, !referenceProjectNextActionReading, let host else { return }
        let generation = referenceProjectNextActionGeneration
        let origin = referenceProjectNextActionOrigin
        let revision = more ? referenceProjectNextActionOptions.text("promptRevision") : ""
        let offset = more ? referenceProjectNextActionCandidates.count : 0
        referenceProjectNextActionReading = true
        referenceProjectNextActionError = nil
        defer { if generation == referenceProjectNextActionGeneration { referenceProjectNextActionReading = false } }
        do {
            let request: CoreObject = ["origin": origin, "params": ["offset": offset, "revision": revision.isEmpty ? NSNull() : revision as Any]]
            let value = try await host.call("referenceProjectNextActionOptions", argumentsJSON: json([try json(request)]))
            guard !Task.isCancelled, generation == referenceProjectNextActionGeneration,
                  referenceProjectNextActionPresented, selectedSurface == .reference, !referenceProjectNextActionPending else { return }
            if value == "null" { invalidateReferenceProjectNextAction(); return }
            let options = try decode(value)
            guard Set(options.keys) == Set(["origin", "promptRevision", "title", "description", "project", "section", "scope", "candidates", "input", "completeProject", "skip"]),
                  (try json(options.object("origin"))).utf8.elementsEqual((try json(origin)).utf8),
                  !options.text("promptRevision").isEmpty,
                  options.object("candidates").number("offset") == offset,
                  !more || options.text("promptRevision").utf8.elementsEqual(revision.utf8) else { throw CocoaError(.coderReadCorrupt) }
            referenceProjectNextActionOptions = options
            if more { referenceProjectNextActionCandidates += options.object("candidates").objects("items") }
            else { referenceProjectNextActionCandidates = options.object("candidates").objects("items") }
            updateReferenceProjectNextActionText(referenceProjectNextActionText)
        } catch {
            guard generation == referenceProjectNextActionGeneration, !Task.isCancelled else { return }
            referenceProjectNextActionError = error.localizedDescription
        }
    }

    func updateReferenceProjectNextActionText(_ text: String) {
        guard referenceProjectNextActionPresented, !referenceProjectNextActionPending else { return }
        referenceProjectNextActionText = text
        referenceProjectNextActionCanSave = false
        referenceProjectNextActionInputGeneration += 1
        let inputGeneration = referenceProjectNextActionInputGeneration
        let generation = referenceProjectNextActionGeneration
        referenceProjectNextActionInputTask?.cancel()
        referenceProjectNextActionInputTask = Task {
            do {
                let result = try await query("referenceProjectNextActionInput", [text])
                guard !Task.isCancelled, inputGeneration == referenceProjectNextActionInputGeneration,
                      generation == referenceProjectNextActionGeneration, referenceProjectNextActionPresented,
                      !referenceProjectNextActionPending, referenceProjectNextActionText.utf8.elementsEqual(text.utf8),
                      Set(result.keys) == Set(["canSave"]), result["canSave"] is Bool else { return }
                referenceProjectNextActionCanSave = result.flag("canSave")
            } catch {
                guard !Task.isCancelled, generation == referenceProjectNextActionGeneration,
                      inputGeneration == referenceProjectNextActionInputGeneration else { return }
                referenceProjectNextActionError = error.localizedDescription
            }
        }
    }

    func performReferenceProjectNextAction(_ action: String, candidate: CoreObject? = nil, openAfterSave: Bool = false) async {
        guard referenceProjectNextActionControlsEnabled,
              action != "add" || referenceProjectNextActionCanSave else { return }
        var request: CoreObject = ["requestId": UUID().uuidString.lowercased(), "origin": referenceProjectNextActionOrigin,
                                   "promptRevision": referenceProjectNextActionOptions.text("promptRevision"), "action": action]
        if action == "choose" {
            guard let candidate, referenceProjectNextActionCandidates.contains(where: {
                $0.text("id").utf8.elementsEqual(candidate.text("id").utf8)
                    && $0.text("taskRevision").utf8.elementsEqual(candidate.text("taskRevision").utf8)
            }) else { return }
            request["candidateId"] = candidate.text("id")
            request["candidateRevision"] = candidate.text("taskRevision")
        } else if action == "add" {
            request["text"] = referenceProjectNextActionText
            request["openAfterSave"] = openAfterSave
        } else if action == "completeProject" {
            guard !referenceProjectNextActionOptions.object("completeProject").isEmpty else { return }
        } else { return }
        busy = true
        referenceProjectNextActionError = nil
        defer { finishOperation() }
        do {
            let encoded = try json(request)
            referenceProjectNextActionRequest = encoded
            let result = try await query("referenceProjectNextAction", [encoded])
            try acknowledgeReferenceProjectNextAction(result)
            _ = await readReference()
        } catch { await handleReferenceProjectNextActionError(error) }
    }

    private func acknowledgeReferenceProjectNextAction(_ result: CoreObject) throws {
        guard let encoded = referenceProjectNextActionRequest else { throw CocoaError(.coderReadCorrupt) }
        let request = try decode(encoded)
        let action = request.text("action")
        guard result.text("action") == action, !result.text("id").isEmpty else { throw CocoaError(.coderReadCorrupt) }
        if action == "choose" {
            guard Set(result.keys) == Set(["action", "id"]),
                  result.text("id").utf8.elementsEqual(request.text("candidateId").utf8) else { throw CocoaError(.coderReadCorrupt) }
        } else if action == "add" {
            guard Set(result.keys) == Set(["action", "id", "openAfterSave"]), result["openAfterSave"] is Bool,
                  result.flag("openAfterSave") == request.flag("openAfterSave") else { throw CocoaError(.coderReadCorrupt) }
        } else {
            guard Set(result.keys) == Set(["action", "id", "status"]), result.text("status") == "archived",
                  result.text("id").utf8.elementsEqual(referenceProjectNextActionOptions.object("project").text("id").utf8) else { throw CocoaError(.coderReadCorrupt) }
        }
        let editID = action == "add" && result.flag("openAfterSave") ? result.text("id") : nil
        referenceProjectNextActionRequest = nil
        retryNeeded = false
        error = nil
        invalidateReferenceProjectNextAction()
        referenceProjectNextActionEditID = editID
    }

    private func handleReferenceProjectNextActionError(_ failure: Error) async {
        if isDefiniteRejection(failure) {
            referenceProjectNextActionRequest = nil
            retryNeeded = false
            referenceProjectNextActionError = failure.localizedDescription
            // A refusal may invalidate the accepted candidates. Only this readonly
            // read can replace that snapshot; the entered draft remains intact.
            await readReferenceProjectNextAction()
            if referenceProjectNextActionPresented { referenceProjectNextActionError = failure.localizedDescription }
        } else {
            retryNeeded = referenceProjectNextActionPending
            referenceProjectNextActionError = failure.localizedDescription
            error = failure.localizedDescription
        }
    }

    @Published private(set) var taskActionNotice: CoreObject = [:]
    private var taskActionRequestID: String?
    private var taskActionUndoRequest: String?
    private var taskCompletionRequest: String?
    private var taskActionNoticeGeneration = 0
    private var taskActionCompleteCancellation = false

    private var taskActionUndoMethod: String {
        switch taskActionNotice.text("operation") {
        case "archiveBulkDelete": return "archivedTasksDeleteUndoWrite"
        case "doneBulkDelete", "referenceBulkDelete": return "archivedTasksDeleteUndoWrite"
        case "delete": return "taskDeleteUndo"
        case "completion": return "taskCompletionUndo"
        default: return "taskCancellationUndo"
        }
    }

    private func showTaskAction(_ result: CoreObject, operation: String = "cancel", source: String? = nil, completeCancellation: Bool = false) {
        guard let requestID = taskActionRequestID else { return }
        let notice = result.object(operation == "delete" ? "deletion" : operation == "completion" ? "completion" : "cancellation")
        guard !notice.isEmpty else { return }
        taskActionRequestID = nil
        taskActionCompleteCancellation = operation == "cancel" && completeCancellation
        var presentation: CoreObject = ["requestId": requestID, "id": result.text("id"), "operation": operation]
        if let source { presentation["source"] = source }
        showTaskActionNotice(notice.merging(presentation) { _, new in new })
    }

    private func showTaskActionNotice(_ notice: CoreObject) {
        taskActionNotice = notice
        taskActionNoticeGeneration += 1
        let generation = taskActionNoticeGeneration
        Task {
            try? await Task.sleep(nanoseconds: 5_200_000_000)
            if taskActionNoticeGeneration == generation && taskActionUndoRequest == nil {
                taskActionNotice = [:]
            }
        }
    }

    func undoTaskAction() async {
        guard !busy, !retryNeeded, !taskPresented, !capturePresented,
              archiveBulkDeleteConfirmation.isEmpty,
              !referenceProjectNextActionPending, taskActionNotice.flag("undoEnabled"), taskActionUndoRequest == nil else { return }
        if taskActionNotice.text("operation") == "completion", taskActionNotice.text("source") == "reference",
           taskActionNotice.text("requestId") == referenceProjectNextActionOrigin.text("requestId") {
            invalidateReferenceProjectNextAction()
        }
        busy = true
        error = nil
        defer { finishOperation() }
        do {
            let proofField = ["delete", "archiveBulkDelete", "doneBulkDelete", "referenceBulkDelete"].contains(taskActionNotice.text("operation")) ? "deleteRequestId"
                : taskActionNotice.text("operation") == "completion" ? "completionRequestId" : "cancelRequestId"
            var fields: CoreObject = ["requestId": UUID().uuidString.lowercased(),
                                     proofField: taskActionNotice.text("requestId")]
            if taskActionNotice.text("operation") == "cancel", taskActionCompleteCancellation { fields["version"] = 2 }
            let request = try json(fields)
            taskActionUndoRequest = request
            let result = try await query(taskActionUndoMethod, [request])
            try acknowledgeTaskActionUndo(result)
            do { try await readSelectedSurface() } catch { self.error = error.localizedDescription }
        } catch {
            let historyUndo = ["done", "archive"].contains(taskActionNotice.text("source"))
            let referenceUndo = taskActionNotice.text("source") == "reference"
            if isDefiniteRejection(error) {
                taskActionUndoRequest = nil
                taskActionNotice = [:]
            }
            retryNeeded = taskActionUndoRequest != nil
            self.error = error.localizedDescription
            if historyUndo { historyError = error.localizedDescription }
            if referenceUndo { referenceError = error.localizedDescription }
        }
    }

    private func acknowledgeTaskActionUndo(_ result: CoreObject) throws {
        guard taskActionUndoRequest != nil else { throw CocoaError(.coderReadCorrupt) }
        if ["archiveBulkDelete", "doneBulkDelete", "referenceBulkDelete"].contains(taskActionNotice.text("operation")) {
            guard Set(result.keys) == Set(["count"]), let count = result["count"] as? NSNumber,
                  CFGetTypeID(count) != CFBooleanGetTypeID(),
                  count.doubleValue == Double(taskActionNotice.number("count")) else { throw CocoaError(.coderReadCorrupt) }
        } else {
            let idMatches = taskActionNotice.text("source") == "reference"
                ? result.text("id").utf8.elementsEqual(taskActionNotice.text("id").utf8)
                : result.text("id") == taskActionNotice.text("id")
            guard idMatches else { throw CocoaError(.coderReadCorrupt) }
        }
        if ["done", "archive"].contains(taskActionNotice.text("source")) { historyError = nil }
        if taskActionNotice.text("source") == "reference" { referenceError = nil }
        taskActionUndoRequest = nil
        taskActionNotice = [:]
        retryNeeded = false
        error = nil
    }

    private var taskDeleteRequest: String?

    func deleteTask() async {
        guard taskPresented, !taskEditor.isEmpty, !taskEditor.flag("readOnly"), !busy, !retryNeeded,
              !taskScheduleUpdating, !taskAttachmentOpening, !taskLinkSheetActive,
              !taskPersonCreateOwed, !taskPersonCreateNeedsReview,
              taskChecklistWriteKind == nil, !taskChecklistReadPending, let host else { return }
        if requestTaskOwnedMenuAction(.delete) { return }
        // Like RN, Delete acts on the saved Task. Keep unsaved edits until its ACK.
        taskRecoveryOwn(["title"])
        busy = true
        taskError = nil
        defer { finishOperation() }
        do {
            checkpointTaskDraft(force: true)
            await flushTaskDraftCheckpoint()
            guard taskRecoveryCheckpointError == nil, let snapshot = taskRecoverySnapshot else {
                throw CocoaError(.fileWriteUnknown)
            }
            let requestID = UUID().uuidString.lowercased()
            let request = try json(["requestId": requestID, "taskId": viewedTaskID,
                                    "taskRevision": taskEditor.text("taskRevision")])
            taskDeleteRequest = request
            taskActionRequestID = requestID
            taskRecoverySaving = true
            let result = try decode(try await host.saveEditorDraft("taskDelete",
                argumentsJSON: try json([request]), expectedSession: snapshot.sessionID,
                expectedGeneration: snapshot.generation))
            try await acknowledgeTaskDelete(result)
        } catch {
            if isDefiniteRejection(error) { taskDeleteRequest = nil }
            retryNeeded = taskDeleteRequest != nil
            taskRecoverySaving = retryNeeded
            taskError = error.localizedDescription
        }
    }

    private func acknowledgeTaskDelete(_ result: CoreObject) async throws {
        guard let request = taskDeleteRequest, let host,
              result.text("id") == (try decode(request)).text("taskId"),
              !result.object("deletion").isEmpty else { throw CocoaError(.coderReadCorrupt) }
        taskRecoverySnapshot = try await host.readEditorDraft()
        guard taskRecoverySnapshot == nil else { throw CocoaError(.coderReadCorrupt) }
        taskDeleteRequest = nil
        taskRecoverySaving = false
        retryNeeded = false
        taskError = nil
        showTaskAction(result, operation: "delete")
        dismissTask(refreshCaller: false)
        do { try await readSelectedSurface() } catch { self.error = error.localizedDescription }
    }

    private var taskDuplicateRequest: String?

    func duplicateTask() async {
        guard taskPresented, !taskEditor.isEmpty, !taskEditor.flag("readOnly"), !busy, !retryNeeded,
              !taskScheduleUpdating, !taskAttachmentOpening, !taskLinkSheetActive,
              !taskPersonCreateOwed, !taskPersonCreateNeedsReview,
              taskChecklistWriteKind == nil, !taskChecklistReadPending, let host else { return }
        if requestTaskOwnedMenuAction(.duplicate) { return }
        // RN duplicates the saved source, not the unsaved editor. Freeze even a
        // clean editor so success and cold replay settle the same owned snapshot.
        taskRecoveryOwn(["title"])
        busy = true
        taskError = nil
        defer { finishOperation() }
        do {
            checkpointTaskDraft(force: true)
            await flushTaskDraftCheckpoint()
            guard taskRecoveryCheckpointError == nil, let snapshot = taskRecoverySnapshot else {
                throw CocoaError(.fileWriteUnknown)
            }
            let request = try json(["requestId": UUID().uuidString.lowercased(),
                                    "action": ["type": "duplicateTask", "taskId": viewedTaskID]])
            taskDuplicateRequest = request
            taskRecoverySaving = true
            let result = try decode(try await host.saveEditorDraft("boardAction",
                argumentsJSON: try json([request]), expectedSession: snapshot.sessionID,
                expectedGeneration: snapshot.generation))
            try await acknowledgeTaskDuplicate(result)
        } catch {
            if isDefiniteRejection(error) { taskDuplicateRequest = nil }
            retryNeeded = taskDuplicateRequest != nil
            taskRecoverySaving = retryNeeded
            taskError = error.localizedDescription
        }
    }

    private func acknowledgeTaskDuplicate(_ result: CoreObject) async throws {
        guard let request = taskDuplicateRequest, let host,
              result.flag("changed"), result.object("open").text("tab") == "task",
              result.object("open").text("taskId") == (try decode(request)).text("requestId") else {
            throw CocoaError(.coderReadCorrupt)
        }
        taskRecoverySnapshot = try await host.readEditorDraft()
        guard taskRecoverySnapshot == nil else { throw CocoaError(.coderReadCorrupt) }
        let copiedID = result.object("open").text("taskId")
        taskDuplicateRequest = nil
        taskRecoverySaving = false
        retryNeeded = false
        taskError = nil
        dismissTask(refreshCaller: false)
        do { try await readSelectedSurface() } catch { self.error = error.localizedDescription }
        prepareTaskPresentation(copiedID, initialTab: "task")
        Task { await readTaskView() }
    }

    private var taskPromotionRequest: String?

    func promoteTaskToProject() async {
        guard taskPresented, !taskEditor.isEmpty, !taskEditor.flag("readOnly"), !busy, !retryNeeded,
              !taskScheduleUpdating, !taskAttachmentOpening, !taskLinkSheetActive,
              !taskPersonCreateOwed, !taskPersonCreateNeedsReview,
              taskChecklistWriteKind == nil, !taskChecklistReadPending, let host else { return }
        // RN uses the draft title for the project name, but moves the saved task.
        let title = (taskTitleDraft.isEmpty ? taskOriginalDraft.text("title") : taskTitleDraft)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        if requestTaskOwnedMenuAction(.promote, promoteTitle: title) { return }
        await submitTaskPromotion(title: title)
    }

    private func submitTaskPromotion(title: String) async {
        guard taskPresented, !taskEditor.isEmpty, !taskEditor.flag("readOnly"), !busy, !retryNeeded,
              !taskHasActiveAttachmentOwner, let host else { return }
        taskRecoveryOwn(["title"])
        busy = true
        taskError = nil
        defer { finishOperation() }
        do {
            checkpointTaskDraft(force: true)
            await flushTaskDraftCheckpoint()
            guard taskRecoveryCheckpointError == nil, let snapshot = taskRecoverySnapshot else {
                throw CocoaError(.fileWriteUnknown)
            }
            let request = try json(["requestId": UUID().uuidString.lowercased(),
                                    "taskId": viewedTaskID, "taskRevision": taskEditor.text("taskRevision"),
                                    "title": title])
            taskPromotionRequest = request
            taskRecoverySaving = true
            let result = try decode(try await host.saveEditorDraft("taskPromote",
                argumentsJSON: try json([request]), expectedSession: snapshot.sessionID,
                expectedGeneration: snapshot.generation))
            try await acknowledgeTaskPromotion(result)
        } catch {
            if isDefiniteRejection(error) { taskPromotionRequest = nil }
            retryNeeded = taskPromotionRequest != nil
            taskRecoverySaving = retryNeeded
            taskError = error.localizedDescription
        }
    }

    private func acknowledgeTaskPromotion(_ result: CoreObject) async throws {
        guard let request = taskPromotionRequest, let host else { throw CocoaError(.coderReadCorrupt) }
        let requestID = (try decode(request)).text("requestId")
        guard Set(result.keys) == Set(["id", "reused"]), let reused = result["reused"] as? Bool,
              !result.text("id").isEmpty, reused || result.text("id") == requestID else {
            throw CocoaError(.coderReadCorrupt)
        }
        taskRecoverySnapshot = try await host.readEditorDraft()
        guard taskRecoverySnapshot == nil else { throw CocoaError(.coderReadCorrupt) }
        let projectID = result.text("id")
        taskPromotionRequest = nil
        taskRecoverySaving = false
        retryNeeded = false
        taskError = nil
        dismissTask(refreshCaller: false)
        await presentProject(["id": projectID], caller: .projects)
        showTaskActionNotice(["message": label(reused ? "task.promoteToProjectMoved" : "task.promoteToProjectCreated"),
                              "operation": "promote", "undoEnabled": false])
    }

    enum TaskSaveIntent: String { case cancel, skip }

    func saveTask(intent: TaskSaveIntent? = nil) async {
        let cancel = intent == .cancel
        guard taskPresented, !taskEditor.isEmpty, !taskEditor.flag("readOnly"), !busy, !retryNeeded,
              !taskAttachmentOpening,
              !taskLinkSheetActive,
              !taskPersonCreateOwed, !taskPersonCreateNeedsReview,
              taskChecklistWriteKind == nil, !taskChecklistReadPending else { return }
        guard !taskAttachmentWorking, taskFileImporterID == nil else { return }
        let ownedSave = taskHasActiveAttachmentOwner
        guard !ownedSave || (taskAttachmentState == .active && [3, 4, 5].contains(taskAttachmentSummary.number("version"))) else {
            taskAttachmentError = "Finish the interrupted attachment change before saving."
            return
        }
        guard !cancel || taskEditor.flag("canCancel") else { return }
        guard intent != .skip || taskEditor.flag("canSkipOccurrence") else { return }
        guard taskDirty || intent != nil || ownedSave else { await discardCleanTaskSnapshotAndClose(); return }
        let id = viewedTaskID
        let session = taskChecklistSession
        let attachmentSession = taskRecoverySession
        let attachmentHost = host
        func requireOwnedSaveClaim() throws {
            guard !ownedSave || (self.host === attachmentHost && taskPresented && viewedTaskID == id
                && taskRecoverySession == attachmentSession && !appLock.concealed && !Task.isCancelled) else {
                throw CancellationError()
            }
        }
        if intent != nil { taskRecoveryOwn(["title"]) }
        if ownedSave { taskRecoveryOwn(checklist: true, attachments: true) }
        taskRecoverySaving = true
        busy = true
        taskError = nil
        var cancellationResult: CoreObject?
        defer { finishOperation() }
        do {
            try await resolveTaskEditorInputs()
            try requireOwnedSaveClaim()
            try await flushTaskChecklistInputs(id: id, session: session)
            try requireOwnedSaveClaim()
            if taskRecoverySnapshot != nil {
                checkpointTaskDraft(force: true)
                await flushTaskDraftCheckpoint()
                try requireOwnedSaveClaim()
                    guard taskRecoveryCheckpointError == nil else { throw CocoaError(.fileWriteUnknown) }
            }
            guard !taskEditor.flag("readOnly") else { taskRecoverySaving = false; return }
            var base: CoreObject = [:]
            var patch: CoreObject = [:]
            let current = taskDraft
            for field in taskSaveFields {
                let original = taskOriginalDraft.text(field)
                let edited = current.text(field)
                if edited != original { base[field] = original; patch[field] = edited }
            }
            let associationFields = ["projectId", "areaId", "sectionId"]
            if associationFields.contains(where: { current.text($0) != taskOriginalDraft.text($0) }) {
                // A move can clear companion associations. Compare the complete
                // original tuple so a concurrent section/area edit is not erased.
                for field in associationFields {
                    base[field] = taskOriginalDraft.text(field)
                    patch[field] = current.text(field)
                }
            }
            if !taskDraftValuesEqual(current["relativeStartOffset"], taskOriginalDraft["relativeStartOffset"]) {
                base["relativeStartOffset"] = taskOriginalDraft["relativeStartOffset"] ?? NSNull()
                patch["relativeStartOffset"] = current["relativeStartOffset"] ?? NSNull()
            }
            if !taskDraftValuesEqual(current["timeSpentMinutes"], taskOriginalDraft["timeSpentMinutes"]) {
                let original = taskOriginalDraft["timeSpentMinutes"] ?? NSNull()
                let edited = current["timeSpentMinutes"] ?? NSNull()
                guard [original, edited].allSatisfy({ value in
                    value is NSNull || (value as? NSNumber).map {
                        CFGetTypeID($0) != CFBooleanGetTypeID() && $0.doubleValue.isFinite && $0.doubleValue >= 0
                    } == true
                }) else { throw CocoaError(.coderReadCorrupt) }
                base["timeSpentMinutes"] = original
                patch["timeSpentMinutes"] = edited
            }
            let recurrenceChanged = taskRecurrenceFields.contains { !taskDraftValuesEqual(current[$0], taskOriginalDraft[$0]) }
            if recurrenceChanged {
                for field in taskRecurrenceFields {
                    base[field] = taskOriginalDraft[field]
                    patch[field] = current[field]
                }
            }
            let lifecycleFields = ["status", "focusedToday", "completedAt"]
            let lifecycleChanged = lifecycleFields.contains { !taskDraftValuesEqual(current[$0], taskOriginalDraft[$0]) }
            for field in lifecycleFields where !taskDraftValuesEqual(current[field], taskOriginalDraft[field]) {
                guard let original = taskOriginalDraft[field], let edited = current[field] else {
                    throw CocoaError(.coderReadCorrupt)
                }
                base[field] = original
                patch[field] = edited
            }
            let checklistChanged = !taskDraftValuesEqual(taskChecklist, taskOriginalChecklist)
            let attachmentsChanged = !taskDraftValuesEqual(taskAttachments, taskOriginalAttachments)
            let checklistSave = checklistChanged || lifecycleChanged || intent != nil
            guard !patch.isEmpty || checklistSave || attachmentsChanged || ownedSave else {
                taskRecoverySaving = false
                await discardCleanTaskSnapshotAndClose()
                return
            }
            var request: CoreObject = ["id": viewedTaskID, "base": base, "patch": patch]
            guard !taskOriginalSchedule.isEmpty else { throw CocoaError(.coderReadCorrupt) }
            request["scheduleBase"] = taskOriginalSchedule
            if recurrenceChanged {
                guard !taskOriginalRecurrence.isEmpty else { throw CocoaError(.coderReadCorrupt) }
                request["recurrenceBase"] = taskOriginalRecurrence
            }
            if attachmentsChanged || ownedSave {
                request["attachments"] = ["base": taskOriginalAttachments, "value": taskAttachments]
            }
            if checklistSave || ownedSave {
                request["checklist"] = ["base": taskOriginalChecklist, "value": taskChecklist]
                request["requestId"] = UUID().uuidString.lowercased()
            }
            if let intent { request["intent"] = intent.rawValue }
            if cancel { taskActionRequestID = request.text("requestId") }
            let payload = try json(request)
            if ownedSave {
                guard let host, let snapshot = taskRecoverySnapshot, taskAttachmentSaveRequest == nil else {
                    throw CocoaError(.coderInvalidValue)
                }
                taskAttachmentSaveRequest = payload
                let result = try decode(try await host.saveAttachmentDraftComplete(saveRequestJSON: payload,
                    expectedSession: snapshot.sessionID, expectedGeneration: snapshot.generation))
                guard self.host === host, taskRecoverySession == snapshot.sessionID else { throw CancellationError() }
                try await acceptTaskAttachmentSave(result, request: payload, currentHost: host)
                return
            } else if let snapshot = taskRecoverySnapshot {
                guard let host else { throw CocoaError(.coderInvalidValue) }
                if checklistSave {
                    taskChecklistWriteKind = "save"
                    taskChecklistWriteRequest = payload
                } else { taskSavePending = true }
                let result = try decode(try await host.saveEditorDraft(
                    checklistSave ? "checklistSave" : "saveDraft",
                    argumentsJSON: try json([payload]), expectedSession: snapshot.sessionID,
                    expectedGeneration: snapshot.generation))
                if checklistSave, result.text("id") != id { throw CocoaError(.coderReadCorrupt) }
                if cancel { cancellationResult = result }
                taskRecoverySnapshot = nil
                taskRecoverySaving = false
                taskChecklistWriteKind = nil
                taskChecklistWriteRequest = nil
                taskSavePending = false
            } else if checklistSave {
                taskChecklistWriteKind = "save"
                taskChecklistWriteRequest = payload
                let result = try await query("checklistSave", [payload])
                guard result.text("id") == id else { throw CocoaError(.coderReadCorrupt) }
                if cancel { cancellationResult = result }
                taskChecklistWriteKind = nil
                taskChecklistWriteRequest = nil
            } else {
                taskSavePending = true
                _ = try await query("saveDraft", [payload])
                taskSavePending = false
            }
        } catch let pending as CoreHostAttachmentCleanupPending {
            guard let payload = taskAttachmentSaveRequest,
                  let result = try? decode(pending.resultJSON),
                  let request = try? decode(payload), result.text("id") == request.text("id") else {
                taskAttachmentState = .blocked
                taskAttachmentError = "The saved task outcome needs review."
                return
            }
            taskAttachmentSavedResult = result
            taskAttachmentSavedHost = attachmentHost
            taskAttachmentState = .savedCleanup
            taskAttachmentError = pending.localizedDescription
            taskRecoverySaving = true
            retryNeeded = true
            return
        } catch {
            if isDefiniteRejection(error) {
                if ownedSave { taskAttachmentSaveRequest = nil }
                taskRecoverySaving = false
                taskSavePending = false
                taskChecklistWriteKind = nil
                taskChecklistWriteRequest = nil
            }
            retryNeeded = taskSavePending || taskChecklistWriteKind != nil || taskAttachmentSaveRequest != nil
            if taskRecoveryCheckpointError != nil { retryNeeded = false; taskRecoverySaving = false }
            if !retryNeeded { taskRecoverySaving = false }
            taskError = error.localizedDescription
            if ownedSave { taskAttachmentError = error.localizedDescription }
            return
        }
        taskRecoverySaving = false
        if let cancellationResult { showTaskAction(cancellationResult) }
        dismissTask()
        do { try await readSelectedSurface() } catch { self.error = error.localizedDescription }
    }

    func editTaskMetadata(_ field: String, value: String) async {
        guard taskPresented, !taskEditor.isEmpty, !taskEditor.flag("readOnly"), !busy, !retryNeeded,
              ["priority", "energyLevel", "timeEstimate"].contains(field),
              taskEditor.object("layout").objects("sections").contains(where: {
                  ($0["fields"] as? [String] ?? []).contains(field)
              }) else { return }
        taskRecoveryOwn([field])
        busy = true
        taskError = nil
        defer { finishOperation() }
        do {
            // Switching an estimate preset replaces its text buffer; other
            // controls first resolve it through core into the complete draft.
            try await resolveTaskEditorInputs(estimate: field != "timeEstimate")
            guard !taskEditor.flag("readOnly") else { return }
            let editor = try await query("editDraft", [try json(taskEditRequest(
                ["type": "fields", "patch": [field: value]]))])
            taskEditor = editor
            resetTaskEstimateInput()
            try await refreshTaskDestination()
        } catch { taskError = error.localizedDescription }
    }

    var taskEditorSession: Int { taskScheduleSession }

    var taskBackdatedCompletionMinutesSeed: String {
        if taskTimeSpentPending { return taskTimeSpentInput }
        if let minutes = taskEditor.object("backdatedCompletionStart")["initialTimeSpentMinutes"] as? NSNumber,
           CFGetTypeID(minutes) != CFBooleanGetTypeID() {
            return minutes.stringValue
        }
        return ""
    }

    func taskStatusEditable(_ status: String) -> Bool {
        let statusVisible = taskEditor.object("layout").flag("showStatusField")
            && taskEditor.object("layout").objects("sections").contains(where: {
                $0.text("id") == "basic" && ($0["fields"] as? [String] ?? []).contains("status")
            })
        return taskPresented && !taskEditor.isEmpty && !taskEditor.flag("readOnly") && !busy && !retryNeeded
            && taskChecklistWriteKind == nil && !taskChecklistReadPending
            && (statusVisible || (status == "next" && taskEditor.object("draft").text("status") == "reference"))
            && (taskEditor.object("options")["statuses"] as? [String] ?? []).contains(status)
    }

    func editTaskStatus(_ status: String, assignedTo: String? = nil,
                        expectedID: String? = nil, expectedSession: Int? = nil) async -> Bool {
        guard taskStatusEditable(status), assignedTo == nil || status == "waiting",
              expectedID == nil || expectedID == viewedTaskID,
              expectedSession == nil || expectedSession == taskScheduleSession else { return false }
        taskRecoveryOwn(assignedTo == nil ? ["status"] : ["status", "assignedTo"])
        let id = viewedTaskID
        let session = taskScheduleSession
        busy = true
        taskError = nil
        defer { finishOperation() }
        do {
            try await resolveTaskEditorInputs()
            guard taskPresented, viewedTaskID == id, taskScheduleSession == session,
                  !taskEditor.flag("readOnly") else { throw CancellationError() }
            var patch: CoreObject = ["status": status]
            if let assignedTo { patch["assignedTo"] = assignedTo.trimmingCharacters(in: .whitespacesAndNewlines) }
            let editor = try await query("editDraft", [try json(taskEditRequest(
                ["type": "fields", "patch": patch]))])
            guard taskPresented, viewedTaskID == id, taskScheduleSession == session else { throw CancellationError() }
            taskEditor = editor
            if assignedTo != nil {
                let field = "assignedTo"
                invalidateTaskTokenRead(field)
                let canonical = editor.object("draft").text(field)
                taskTokenInputs[field] = canonical
                taskTokenCanonical[field] = canonical
                taskTokenResolvedInputs[field] = canonical
                taskTokenSuggestions[field] = nil
                taskTokenErrors[field] = nil
                taskTokenEdited.insert(field)
                taskTokenNeedsRead.insert(field)
            }
            do { try await refreshTaskDestination() }
            catch { taskError = error.localizedDescription }
            return true
        } catch {
            taskError = error.localizedDescription
            return false
        }
    }

    func editTaskBackdatedCompletion(_ completedAt: String, timeSpentText: String?,
                                    expectedID: String, expectedSession: Int) async -> Bool {
        guard taskStatusEditable("done"), viewedTaskID == expectedID,
              taskScheduleSession == expectedSession,
              timeSpentText == nil || taskEditor.object("fields").object("timeSpent").flag("enabled") else { return false }
        taskRecoveryOwn(timeSpentText == nil ? ["status"] : ["status", "timeSpentMinutes"])
        busy = true
        taskError = nil
        defer { finishOperation() }
        do {
            try await resolveTaskEditorInputs()
            guard taskPresented, viewedTaskID == expectedID, taskScheduleSession == expectedSession,
                  !taskEditor.flag("readOnly") else { throw CancellationError() }
            var edit: CoreObject = ["type": "backdatedCompletion", "completedAt": completedAt]
            if let timeSpentText { edit["timeSpentText"] = timeSpentText }
            let editor = try await query("editDraft", [try json(taskEditRequest(edit))])
            guard taskPresented, viewedTaskID == expectedID, taskScheduleSession == expectedSession else {
                throw CancellationError()
            }
            taskEditor = editor
            if timeSpentText != nil { resetTaskTimeSpentInput() }
            NSLog("Native iOS backdated completion draft confirmed releaseCheck=v1.3.4/ios-editor-backdate outcome=confirmed")
            do { try await refreshTaskDestination() }
            catch { taskError = error.localizedDescription }
            guard taskPresented, viewedTaskID == expectedID, taskScheduleSession == expectedSession else {
                throw CancellationError()
            }
            return true
        } catch {
            taskError = error.localizedDescription
            return false
        }
    }

    func taskWaitingSuggestions(_ raw: String, id: String, session: Int) async throws -> CoreObject {
        guard taskPresented, viewedTaskID == id, taskScheduleSession == session,
              !taskEditor.flag("readOnly"), !retryNeeded else { throw CancellationError() }
        let result = try await readTaskTokenSuggestions("assignedTo", raw: raw, id: id)
        guard taskPresented, viewedTaskID == id, taskScheduleSession == session,
              !taskEditor.flag("readOnly"), !retryNeeded,
              result["draftValue"] is String, result["matches"] is [CoreObject],
              result.objects("matches").allSatisfy({ $0["text"] is String && $0["value"] is String }) else {
            throw CancellationError()
        }
        return result
    }

    func commitTaskEstimateInput() async {
        guard taskPresented, !taskEditor.isEmpty, !taskEditor.flag("readOnly"), !busy, !retryNeeded, taskEstimatePending else { return }
        busy = true
        taskError = nil
        defer { finishOperation() }
        do {
            try await resolveTaskEditorInputs()
            try await refreshTaskDestination()
        } catch { taskError = error.localizedDescription }
