    #if DEBUG && targetEnvironment(simulator)
    private func recordReferenceBulkRemoveTestRead(_ event: String,
        read: (query: String, request: String, session: String, generation: Int), cancelled: Bool = false) {
        let record: CoreObject = ["event": event, "query": read.query, "request": read.request,
            "session": read.session, "generation": read.generation, "cancelled": cancelled]
        guard let encoded = try? json(record) else { return }
        let lines = referenceBulkRemoveTestReadState.split(separator: "\n").map(String.init) + [encoded]
        referenceBulkRemoveTestReadState = lines.suffix(12).joined(separator: "\n")
    }
    #endif

    private func decode(_ result: String) throws -> CoreObject {
        guard let object = try NativeJSON.jsonObject(with: Data(result.utf8)) as? CoreObject else {
            throw CocoaError(.coderReadCorrupt)
        }
        return object
    }

    private func json(_ value: Any) throws -> String {
        String(decoding: try JSONSerialization.data(withJSONObject: value, options: [.sortedKeys]), as: UTF8.self)
    }

    private func invalidatePreview() { previewGeneration += 1; previewTask?.cancel() }
    private func isDefiniteRejection(_ error: Error) -> Bool {
        #if DEBUG && targetEnvironment(simulator)
        if error is SimulatedSomedayDeleteRefusal || error is SimulatedSomedayOrderRefusal
            || error is SimulatedUnassignedColorRefusal || error is SimulatedManageAreaRefusal
            || error is SimulatedManagePersonCreateRefusal { return true }
        #endif
        return error is CoreHostRejection
    }
    private func finishOperation() {
        defer {
            admitReminderLifecycle(); admitSearchLifecycle(); admitNotificationResponses()
            if entityLinkTask == nil { requestEntityLinks() }
        }
        busy = false
        if projectFileAvailabilityPending {
            retryNeeded = true
            refreshRequested = false
            return
        }
        if settingsSyncRestartRequired { refreshRequested = false; return }
        if resumeFeedbackConfigurationIfNeeded() { return }
        admitForegroundSync()
        if foregroundSyncOwner != nil { return }
        presentQueuedReferenceProjectNextAction()
        if let id = referenceProjectNextActionEditID, ready, !retryNeeded, !taskPresented, !appLock.concealed {
            referenceProjectNextActionEditID = nil
            // This ID is from an exact acknowledged Add. It need not be visible
            // in Reference, and must never be reconstructed by parsing the input.
            prepareTaskPresentation(id, initialTab: "task")
            Task { await readTaskView() }
        }
        if taskPresented && !retryNeeded && !taskAttachmentEditorInterrupted {
            startTaskSchedulePump()
            for field in taskTokenFields where taskTokenNeedsRead.contains(field) { requestTaskTokenRead(field, delay: 0) }
        }
        if taskPresented && taskDestinationNeedsRead && !retryNeeded && !taskAttachmentEditorInterrupted { requestTaskDestinationRead(delay: 0) }
        if capturePresented && (!captureIsCurrent || (contextPickerPresented && !contextPickerReady)) { textChanged() }
        if refreshRequested {
            refreshRequested = false
            Task { await refresh() }
        }
        if selectedSurface == .board && boardNeedsRead && !retryNeeded && !taskPresented { scheduleBoardRead() }
        if selectedSurface == .calendar && calendarNeedsRead && !retryNeeded && !taskPresented
            && !calendarComposerPresented { scheduleCalendarRead() }
        if selectedSurface == .focus && focusNeedsRead && !retryNeeded && !taskPresented { scheduleFocusRead() }
        if selectedSurface == .contexts && contextsNeedsRead && !retryNeeded && !taskPresented {
            scheduleContextsRead()
        }
        if selectedSurface == .search && searchNeedsRead && !retryNeeded && !taskPresented {
            scheduleSearch()
        }
        if selectedSurface == .someday && (somedayTextNeedsRead || somedayPickerNeedsRead) && !retryNeeded && !taskPresented {
            scheduleSomedayRead()
        }
        if selectedSurface == .history && (historyNeedsRead || historyPickerNeedsRead) && !retryNeeded && !taskPresented {
            scheduleHistoryRead()
        }
        if selectedSurface == .reference && (referenceTextNeedsRead || referencePickerNeedsRead) && !retryNeeded && !taskPresented {
            scheduleReferenceRead()
        }
        if selectedSurface == .project && !retryNeeded && !taskPresented
            && (projectFilterNeedsRead || ((projectFilterTextEdits.isEmpty == false || projectFilterPickerNeedsRead)
                && projectError == nil && projectFilterError == nil)) {
            scheduleProjectFilterRead(delay: 0)
        }
    }
